/**
 * 199 real, published board games. Stats, cover image and description were
 * refreshed against a live BGG import (2026-08-26, `scripts/refresh-board-games-from-bgg.ts`
 * run against both the dev and prod DB) for every title BGG resolved to
 * exactly one match; ambiguous titles (multiple or zero exact BGG hits, see
 * that script's "needs-review" output) kept their previous, Wikipedia-sourced
 * values. Descriptions came back untranslated English for most titles — the
 * translation API's daily quota was exhausted mid-run — a later rerun can
 * backfill German text without touching the other fields. A handful of
 * titles resolve to a different BGG-canonical name than the one used here
 * (e.g. "6 Nimmt!" → BGG's "Take 5", "Dobble" → "Spot it!"); the title in
 * this file intentionally keeps the familiar marketing name even though the
 * DB row now shows BGG's name.
 */
export type DemoGame = {
  title: string;
  imageUrl: string | null;
  minPlayers: number | null;
  maxPlayers: number | null;
  playTimeMinutes: number | null;
  weight: number | null;
  description: string;
  mechanics: string[];
};

export const DEMO_GAMES: DemoGame[] = [
  // Batch 1
  { title: "Catan", imageUrl: "https://cf.geekdo-images.com/0XODRpReiZBFUffEcqT5-Q__original/img/oRc0AomWA9ZtFqQDZiZbIyKE1j0=/0x0/filters:format(png)/pic9156909.png", minPlayers: 3, maxPlayers: 4, playTimeMinutes: 120, weight: 2.3, description: "In CATAN (formerly The Settlers of Catan), players try to be the dominant force on the island of Catan by building settlements, cities and roads. On each turn dice are rolled to determine which resources the island produces. Players build structures by 'spending' resources (sheep, wheat, wood, brick and ore) which are represented by the relevant resource cards; each land type, with the exception of the unproductive desert, produces a specific resource: hills produce brick, forests produce wood, mountains produce ore, fields produce wheat, and pastures produce sheep.\n\nSet-up includes randomly placing large hexagonal tiles (each depicting one of the five resource-producing terrain types--or the desert) in a honeycomb shape and surrounding them with water tiles, some of which contain ports of exchange. A number disk, the value of which will correspond to the roll of two 6-sided dice, are placed on each terrain tile. Each player is given two settlements (think: houses) and roads (sticks) which are placed on intersections and borders of the terrain tiles. Players collect a hand of resource cards based on which terrain tiles their last-placed settlement is adjacent to. A robber pawn is placed on the desert tile.\n\nA turn consists of rolling the dice, collecting resource cards based on this dice roll and the position of settlements (or upgraded cities—think: hotels), turning in resource cards (if possible and desired) for improvements, trading cards at a port, possibly playing a development card, or trading resource cards with other players. If the dice roll is a 7, the active player moves the robber to a new terrain tile and steals a resource card from another player who has a settlement adjacent to that tile.\n\nPoints are accumulated by building settlements and cities, having the longest road or the largest army (from some of the development cards), and gathering certain development cards that simply award victory points. When a player has gathered 10 points (some of which may be held in secret), s/he announces this and claims the win.", mechanics: ["Chaining", "Würfelglück", "Handkartenmanagement", "Hexagon Grid", "Hidden Victory Points", "Income", "Market", "Modularer Spielplan", "Verhandlung", "Streckenbau", "Race", "Random Production", "Take That", "Handel", "Variable Set-up"] },
  { title: "Carcassonne", imageUrl: "https://cf.geekdo-images.com/peUgu3A20LRmAXAMyDQfpQ__original/img/bP18m_PYjyFOv1IBGgMOteQUneA=/0x0/filters:format(jpeg)/pic8621446.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 45, weight: 1.9, description: "Carcassonne is a tile placement game in which the players draw and place a tile with a piece of southern French landscape represented on it. The tile might feature a city, a road, a cloister, grassland or some combination thereof, and it must be placed adjacent to tiles that have already been played, in such a way that cities are connected to cities, roads to roads, et cetera. Having placed a tile, the player can then decide to place one of their meeples in one of the areas on it: in the city as a knight, on the road as a robber, in the cloister as a monk, or in the field as a farmer. When that area is complete that meeple scores points for its owner.\n\nDuring a game of Carcassonne, players are faced with decisions like: \"Is it really worth putting my last meeple there?\" or \"Should I use this tile to expand my city, or should I place it near my opponent instead, thus making it a harder for them to complete it and score points?\" Since players place only one tile and have the option to place one meeple on it, turns proceed quickly even if it is a game full of options and possibilities.\n\nFirst game in the Carcassonne series.", mechanics: ["Gebietskontrolle", "Enclosure", "Kill Steal", "Map Addition", "Musterbildung", "Square Grid", "Plättchen platzieren"] },
  { title: "Pandemic", imageUrl: "https://cf.geekdo-images.com/S3ybV1LAp-8SnHIXLLjVqA__original/img/IsrvRLpUV1TEyZsO5rC-btXaPz0=/0x0/filters:format(jpeg)/pic1534148.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 45, weight: 2.4, description: "In Pandemic, several virulent diseases have broken out simultaneously all over the world! The players are disease-fighting specialists whose mission is to treat disease hotspots while researching cures for each of four plagues before they get out of hand.\n\nThe game board depicts several major population centers on Earth. On each turn, a player can use up to four actions to travel between cities, treat infected populaces, discover a cure, or build a research station. A deck of cards provides the players with these abilities, but sprinkled throughout this deck are Epidemic! cards that accelerate and intensify the diseases' activity. A second, separate deck of cards controls the \"normal\" spread of the infections.\n\nTaking a unique role within the team, players must plan their strategy to mesh with their specialists' strengths in order to conquer the diseases. For example, the Operations Expert can build research stations which are needed to find cures for the diseases and which allow for greater mobility between cities; the Scientist needs only four cards of a particular disease to cure it instead of the normal five—but the diseases are spreading quickly and time is running out. If one or more diseases spreads beyond recovery or if too much time elapses, the players all lose. If they cure the four diseases, they all win!\n\nThe 2013 edition of Pandemic includes two new characters—the Contingency Planner and the Quarantine Specialist—not available in earlier editions of the game.\n\nPandemic is the first game in the Pandemic series.", mechanics: ["Aktionspunkte", "Chaining", "Contracts", "Kooperativ", "Events", "Handkartenmanagement", "Multi-Use Cards", "Bewegung entlang von Punkten", "Set Collection", "Simulation", "Solospiel", "Tags", "Handel", "Variable Spielerfähigkeiten", "Variable Set-up"] },
  { title: "Ticket to Ride", imageUrl: "https://cf.geekdo-images.com/kdWYkW-7AqG63HhqPL6ekA__original/img/rWF8r4JXXCQQ7QhiWHhmT-rQ3Pc=/0x0/filters:format(jpeg)/pic8937637.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 60, weight: 1.8, description: "With elegantly simple gameplay, Ticket to Ride can be learned in under 15 minutes. Players collect cards of various types of train cars they then use to claim railway routes in North America. The longer the routes, the more points they earn. Additional points come to those who fulfill Destination Tickets – goal cards that connect distant cities; and to the player who builds the longest continuous route.\n\n\"The rules are simple enough to write on a train ticket – each turn you either draw more cards, claim a route, or get additional Destination Tickets,\" says Ticket to Ride author, Alan R. Moon. \"The tension comes from being forced to balance greed – adding more cards to your hand, and fear – losing a critical route to a competitor.\"\n\nTicket to Ride continues in the tradition of Days of Wonder's big format board games featuring high-quality illustrations and components including: an oversize board map of North America, 225 custom-molded train cars, 144 illustrated cards, and wooden scoring markers.\n\nSince its introduction and numerous subsequent awards, Ticket to Ride has become the BoardGameGeek epitome of a \"gateway game\" -- simple enough to be taught in a few minutes, and with enough action and tension to keep new players involved and in the game for the duration.\n\nPart of the Ticket to Ride series.", mechanics: ["Connections", "Contracts", "End Game Bonuses", "Handkartenmanagement", "Streckenbau", "Open Drafting", "Risikomanagement", "Set Collection"] },
  { title: "Codenames", imageUrl: "https://cf.geekdo-images.com/nC6ifPCDnAItwoKSKXVrnw__original/img/Id-jjIer_61ZbvI2_RVRCeBZFY4=/0x0/filters:format(jpeg)/pic8907965.jpg", minPlayers: 2, maxPlayers: 8, playTimeMinutes: 15, weight: 1.3, description: "Two rival spymasters know the secret identities of 25 agents. Their teammates know the agents only by their codenames — single-word labels like \"disease\", \"Germany\", and \"carrot\". Yes, carrot. It's a legitimate codename. Each spymaster wants their team to identify their agents first...without uncovering the assassin by mistake.\n\nIn Codenames, two teams compete to see who can make contact with all of their agents first. Lay out 25 cards, each bearing a single word. The spymasters look at a card showing the identity of each card, then take turns clueing their teammates. A clue consists of a single word and a number, with the number suggesting how many cards in play have some association to the given clue word. The teammates then identify one agent they think is on their team; if they're correct, they can keep guessing up to one more than the stated number of times; if the agent belongs to the opposing team or is an innocent bystander, the team's turn ends; and if they fingered the assassin, they lose the game.\n\nSpymasters continue giving clues until one team has identified all of their agents or the assassin has removed one team from play.", mechanics: ["Communication Limits", "Deduction", "Merkfähigkeit", "Race", "Teamspiel"] },
  { title: "Azul", imageUrl: "https://cf.geekdo-images.com/aPSHJO0d0XOpQR5X-wJonw__original/img/AkbtYVc6xXJF3c9EUrakklcclKw=/0x0/filters:format(png)/pic6973671.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 45, weight: 1.8, description: "Die von den Mauren eingeführten Azulejos (ursprünglich weiße und blaue Keramikfliesen) wurden von den Portugiesen voll und ganz angenommen, als ihr König Manuel I. bei einem Besuch des Alhambra-Palastes in Südspanien von der atemberaubenden Schönheit der maurischen Dekorfliesen fasziniert war. Der König, beeindruckt von der inneren Schönheit der Alhambra, ordnete sofort an, dass sein eigener Palast in Portugal mit ähnlichen Wandfliesen geschmückt werden sollte. Als Fliesenleger wurden Sie aufgefordert, die Wände des Königspalastes von Evora zu verschönern.\n\nIm Spiel Azul ziehen die Spieler abwechselnd farbige Steine von Lieferanten auf ihr Spielerbrett. Später in der Runde erhalten die Spieler Punkte, je nachdem, wie sie ihre Steine platziert haben, um den Palast zu dekorieren. Zusätzliche Punkte werden für bestimmte Muster und das Abschließen von Sätzen erzielt. Verschwendetes Zubehör schadet der Punktzahl des Spielers. Der Spieler mit den meisten Punkten am Ende des Spiels gewinnt.", mechanics: ["Chaining", "End Game Bonuses", "Grid Coverage", "Open Drafting", "Musterbildung", "Set Collection", "Square Grid", "Plättchen platzieren", "Turn Order: Claim Action"] },
  { title: "Wingspan", imageUrl: "https://cf.geekdo-images.com/yLZJCVLlIx4c7eJEWUNJ7w__original/img/cI782Zis9cT66j2MjSHKJGnFPNw=/0x0/filters:format(jpeg)/pic4458123.jpg", minPlayers: 1, maxPlayers: 5, playTimeMinutes: 70, weight: 2.5, description: "Wingspan is a competitive, medium-weight, card-driven, engine-building board game from Stonemaier Games. It's designed by Elizabeth Hargrave and features 180 birds illustrated by Natalia Rojas and Ana Maria Martinez.\n\nYou are bird enthusiasts—researchers, bird watchers, ornithologists, and collectors—seeking to discover and attract the best birds to your network of wildlife preserves. Each bird extends a chain of powerful combinations in one of your habitats (actions). These habitats  focus on several key aspects of growth:\n\n\n     Gain food tokens via custom dice in a birdfeeder dice tower\n     Lay eggs using egg miniatures in a variety of colors\n     Draw from hundreds of unique bird cards and play them\n\n\nThe winner is the player with the most points after 4 rounds.\n\n—description from the publisher\n\nFrom the 7th printing on, the base game box includes Wingspan: Swift-Start Promo Pack.", mechanics: ["Action Queue", "Würfelglück", "End Game Bonuses", "Handkartenmanagement", "Once-Per-Game Abilities", "Open Drafting", "Set Collection", "Solospiel", "Turn Order: Progressive"] },
  { title: "Terraforming Mars", imageUrl: "https://cf.geekdo-images.com/wg9oOLcsKvDesSUdZQ4rxw__original/img/thIqWDnH9utKuoKVEUqveDixprI=/0x0/filters:format(jpeg)/pic3536616.jpg", minPlayers: 1, maxPlayers: 5, playTimeMinutes: 120, weight: 3.3, description: "In the 2400s, mankind begins to terraform the planet Mars. Giant corporations, sponsored by the World Government on Earth, initiate huge projects to raise the temperature, the oxygen level, and the ocean coverage until the environment is habitable. In Terraforming Mars, you play one of those corporations and work together in the terraforming process, but compete for getting victory points that are awarded not only for your contribution to the terraforming, but also for advancing human infrastructure throughout the solar system, and doing other commendable things.\n\nAs a player, you acquire unique project cards (from over two hundred different ones) by buying them to your hand. The cards can give you immediate bonuses, as well as increasing your production of different resources. Many cards also have requirements and they become playable when the temperature, oxygen, or ocean coverage increases enough. Buying cards is costly, so there is a balance between buying cards and actually playing them. Standard Projects are always available to complement your hand of cards. Your basic income, as well as your basic score, are based on your Terraform Rating. However, your income is boosted by your production, and VPs are also gained from many other sources.\n\nYou keep track of your production and resources on your player board.  The game uses six types of resources: MegaCredits, Steel, Titanium, Plants, Energy, and Heat. On the game board, you compete for the best places for your city tiles, ocean tiles, and greenery tiles. You also compete for different Milestones and Awards worth many VPs. Each round is called a generation and consists of the following phases:\n\n1) Player order shifts clockwise.\n2) Research phase: All players buy cards from four privately drawn.\n3) Action phase: Players take turns doing 1-2 actions from these options: Playing a card, claiming a Milestone, funding an Award, using a Standard project, converting plant into greenery tiles (and raising oxygen), converting heat into a temperature raise, and using the action of a card in play. The turn continues around the table (sometimes several laps) until all players have passed.\n4) Production phase: Players get resources according to their terraform rating and production parameters.\n\nWhen the three global parameters (temperature, oxygen, ocean) have all reached their required levels, the terraforming is complete, and the game ends after that generation. Combine your Terraform Rating and other VPs to determine the winning corporation!", mechanics: ["Closed Drafting", "Contracts", "End Game Bonuses", "Handkartenmanagement", "Hexagon Grid", "Income", "Solospiel", "Tags", "Take That", "Plättchen platzieren", "Turn Order: Progressive", "Variable Spielerfähigkeiten", "Variable Set-up"] },
  { title: "7 Wonders", imageUrl: "https://cf.geekdo-images.com/35h9Za_JvMMMtx_92kT0Jg__original/img/jt70jJDZ1y1FWJs4ZQf5FI8APVY=/0x0/filters:format(jpeg)/pic7149798.jpg", minPlayers: 2, maxPlayers: 7, playTimeMinutes: 30, weight: 2.3, description: "Du bist der Anführer einer der 7 großen Städte der Antike. Sammle Ressourcen, entwickle kommerzielle Routen und bestätige deine militärische Vorherrschaft. Bauen Sie Ihre Stadt und errichten Sie ein architektonisches Wunder, das die Zukunft transzendieren wird.\n\n7 Wunder dauern drei Zeitalter. In jedem Alter erhalten die Spieler sieben Karten von einem bestimmten Deck, wählen eine dieser Karten aus und geben den Rest an einen benachbarten Spieler weiter. Die Spieler legen ihre Karten gleichzeitig offen, zahlen bei Bedarf Ressourcen oder sammeln Ressourcen oder interagieren auf verschiedene Weise mit anderen Spielern. (Spieler haben einzelne Bretter mit besonderen Fähigkeiten, auf denen sie ihre Karten organisieren können, und die Bretter sind doppelseitig). Jeder Spieler wählt dann eine weitere Karte aus dem Stapel, den er weitergegeben hat, und der Vorgang wird wiederholt, bis die Spieler ab diesem Alter sechs Karten im Spiel haben. Nach drei Zeitaltern endet das Spiel.\n\nIm Wesentlichen ist 7 Wonders ein Kartenentwicklungsspiel. Einige Karten haben sofortige Effekte, während andere später im Spiel Boni oder Upgrades bieten. Einige Karten bieten Rabatte auf zukünftige Einkäufe. Einige bieten militärische Stärke, um deine Nachbarn zu überwältigen, und andere geben nichts als Siegpunkte. Jede Karte wird sofort nach dem Draft gespielt, so dass Sie wissen, welche Karten Ihre Nachbarin erhält und wie sich ihre Entscheidungen auf das auswirken könnten, was Sie bereits aufgebaut haben. Die Karten werden über die drei Zeitalter hinweg links-rechts-links weitergegeben, daher müssen Sie die Nachbarn in beide Richtungen im Auge behalten.\n\nObwohl die Schachtel früherer Ausgaben als für 3–7", mechanics: ["Closed Drafting", "End Game Bonuses", "Handkartenmanagement", "Melding and Splaying", "Multi-Use Cards", "Neighbor Scope", "Once-Per-Game Abilities", "Score-and-Reset Game", "Set Collection", "Gleichzeitige Aktionswahl", "Tags", "Tech Trees / Tech Tracks", "Variable Spielerfähigkeiten", "Variable Set-up"] },
  { title: "Dominion", imageUrl: "https://upload.wikimedia.org/wikipedia/en/b/b5/Dominion_game.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 30, weight: 2.3, description: "Als Herrscher eines kleinen Königreichs bauen die Spieler ihr eigenes Kartendeck mit Aktionen, Geld und Siegpunkten stetig aus.", mechanics: ["Deckbuilding", "Kartenmanagement"] },
  { title: "Puerto Rico", imageUrl: "https://upload.wikimedia.org/wikipedia/en/6/66/Puerto_Rico_game.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 120, weight: 3.3, description: "Als Plantagenbesitzer in der Kolonialzeit bauen und verschiffen die Spieler Waren wie Zucker, Tabak und Kaffee, um Puerto Rico wirtschaftlich zu entwickeln.", mechanics: ["Rollenwahl", "Ressourcenmanagement", "Worker Placement"] },
  { title: "Agricola", imageUrl: "https://cf.geekdo-images.com/3L6ZtOll9W5O6-3-EwSMyw__original/img/V37KuMJlCzpxAilzN39BzeLvc9Q=/0x0/filters:format(jpeg)/pic1899157.jpg", minPlayers: 1, maxPlayers: 5, playTimeMinutes: 150, weight: 3.6, description: "In Agricola bist du ein Bauer in einer Holzhütte mit deinem Ehepartner und sonst wenig. Zunächst kann Ihre Familie abwechselnd nur zwei Maßnahmen ergreifen, eine für Sie und eine für Ihren Ehepartner, wie sie unter allen Möglichkeiten auf einem Bauernhof zu finden sind: Pflügen von Feldern; Sammeln von Materialien; Bau von Zäunen usw. Es gibt zahlreiche Möglichkeiten, und während das Spiel fortschreitet, werden Sie immer mehr haben, da jede Runde eine neue Aktionskarte umgedreht wird, die eine weitere mögliche Aktion bietet. Sie könnten darüber nachdenken, Kinder zu haben, um mehr Arbeit zu erledigen, aber zuerst müssen Sie Ihr Haus erweitern, um Platz zu schaffen - und was werden Sie all die kleinen Teppichratten füttern?\n\nDas Spiel unterstützt viele Komplexitätsstufen, hauptsächlich durch die Verteilung von Karten, die kleinere Verbesserungen und Berufe darstellen. In der Anfängerversion (in den USA als Familienvariante bezeichnet) werden diese Karten überhaupt nicht verwendet. Für fortgeschrittenes Spiel enthält die US-Version drei Stufen beider Arten von Karten; Basic (E-Deck), Interactive (I-Deck) und Complex (K-Deck), und das Regelwerk ermutigt die Spieler, mit den verschiedenen Decks und Mischungen davon zu experimentieren. Aftermarket-Decks wie das Z-Deck und das L-Deck sind ebenfalls vorhanden. Jeder Spieler beginnt mit einer Hand aus 7 Berufskarten (von insgesamt mehr als 160) und 7 Kleinen Verbesserungskarten (von insgesamt mehr als 140), die er während des Spiels verwenden kann, wenn sie in seine Strategie passen.\n\nAgricola ist ein rundenbasiertes Spiel, und das zu überwindende Problem ist, dass jeder", mechanics: ["Automatic Resource Growth", "Closed Drafting", "Enclosure", "Increase Value of Unchosen Resources", "Solospiel", "Turn Order: Claim Action", "Arbeitereinsatz"] },
  { title: "Scythe", imageUrl: "https://cf.geekdo-images.com/7k_nOxpO9OGIjhLq2BUZdA__original/img/HlDb9F365w0tSP8uD1vf1pfniQE=/0x0/filters:format(jpeg)/pic3163924.jpg", minPlayers: 1, maxPlayers: 5, playTimeMinutes: 115, weight: 3.5, description: "It is a time of unrest in 1920s Europa. The ashes from the first great war still darken the snow. The capitalistic city-state known simply as &ldquo;The Factory&rdquo;, which fueled the war with heavily armored mechs, has closed its doors, drawing the attention of several nearby countries.\n\nScythe is an engine-building game set in a 1920s era, alternate-history. It is a time of farming and war, broken hearts and rusted gears, innovation and valor. In Scythe, each player controls one of five factions of Eastern Europe, all of which are attempting to earn their fortunes and claim their stakes in the land around the mysterious Factory. Players conquer territory, enlist new recruits, reap resources, gain villagers, build structures, and activate monstrous mechs.\n\nEach player begins the game with different resources (power, coins, combat acumen, and popularity), a different starting location, and a hidden goal. Starting positions are specially calibrated to contribute to each faction&rsquo;s uniqueness and the asymmetrical nature of the game (each faction always starts in the same place). Scythe uses a streamlined action-selection mechanism (no rounds or phases) to keep gameplay moving at a brisk pace and reduce downtime between turns. While there is plenty of direct conflict for players who seek it, there is no player elimination.\n\nScythe gives players almost complete control over their fate. Other than each player&rsquo;s individual hidden objective card, the only elements of luck or variability are &ldquo;encounter&rdquo; cards that players will draw as they interact with the citizens of newly explored lands. Each encounter card provides the player with several options, allowing them to mitigate the luck of the draw through their selection. Combat is also driven by choices, not luck or randomness. Every part of Scythe has an aspect of engine-building to it. Players can upgrade actions to become more efficient, build structures that improve their position on the map, enlist new recruits to enhance character abilities, activate mechs to deter opponents from invading, and expand their borders to reap greater types and quantities of resources. These engine-building aspects create a sense of momentum and progress throughout the game. The order in which players improve their engines adds to the unique feel of each game, even if having played one faction multiple times.", mechanics: ["Gebietskontrolle", "Card Play Conflict Resolution", "Contracts", "End Game Bonuses", "Force Commitment", "Bewegung auf Gitterfeld", "Hexagon Grid", "King of the Hill", "Movement Points", "Narrative Choice / Paragraph", "Solospiel", "Take That", "Tech Trees / Tech Tracks", "Variable Spielerfähigkeiten", "Variable Set-up", "Victory Points as a Resource", "Kontrollzonen"] },
  { title: "Gloomhaven", imageUrl: "https://cf.geekdo-images.com/sZYp_3BTDGjh2unaZfZmuA__original/img/7d-lj5Gd1e8PFnD97LYFah2c45M=/0x0/filters:format(jpeg)/pic2437871.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 120, weight: 3.9, description: "Gloomhaven  is a game of Euro-inspired tactical combat in a persistent world of shifting motives. Players will take on the roles of wandering adventurers with their own special sets of skills and their own reasons for traveling to this dark corner of the world. Players must work together out of necessity to clear out menacing dungeons and forgotten ruins. In the process, they will enhance their abilities with experience and loot, discover new locations to explore and plunder, and expand an ever-branching story fueled by the decisions they make.\n This is a game with a persistent and changing world that is ideally played over many game sessions. After a scenario, players will make decisions about what to do next, which will determine how the story continues, kind of like a &ldquo;Choose Your Own Adventure&rdquo; book. Playing through a scenario is a co-operative affair where players will fight against automated monsters using an innovative card system to determine the order of play and what a player does on their turn.\n\nEach turn, a player chooses two cards to play out of their hand. The number on the top card determines their initiative for the round. Each card also has a top and bottom power, and when it is a player&rsquo;s turn in the initiative order, they determine whether to use the top power of one card and the bottom power of the other, or vice-versa. Players must be careful, though, because over time they will permanently lose cards from their hands. If they take too long to clear a dungeon, they may end u exhausted and be forced to retreat.", mechanics: ["Action Queue", "Action Retrieval", "Campaign / Battle Card Driven", "Card Play Conflict Resolution", "Communication Limits", "Kooperativ", "Critical Hits and Failures", "Deck Construction", "Bewegung auf Gitterfeld", "Handkartenmanagement", "Hexagon Grid", "Legacy-Spiel", "Line of Sight", "Modularer Spielplan", "Movement Points", "Multi-Use Cards", "Multiple Maps", "Narrative Choice / Paragraph", "Once-Per-Game Abilities", "Spielerausscheidung", "Role Playing", "Scenario / Mission / Campaign Game", "Gleichzeitige Aktionswahl", "Solospiel", "Geschichten erzählen", "Tags", "Variable Spielerfähigkeiten"] },
  { title: "Root", imageUrl: "https://cf.geekdo-images.com/JUAUWaVUzeBgzirhZNmHHw__original/img/E0s2LvtFA1L5YKk-_44D4u2VD2s=/0x0/filters:format(jpeg)/pic4254509.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 90, weight: 3.8, description: "Root is a game of adventure and war in which 2 to 4 (1 to 6 with the 'Riverfolk' expansion, 2-6 with the 'Underworld', or 'Marauder' expansions) players battle for control of a vast wilderness. Like Vast: The Crystal Caverns, each player in Root has unique capabilities and a different victory condition. Now, with the aid of gorgeous, multi-use cards, a truly asymmetric design has never been more accessible.\n\nThe nefarious Marquise de Cat has seized the great woodland, intent on harvesting its riches. Under her rule, the many creatures of the forest have banded together. This Alliance will seek to strengthen its resources and subvert the rule of Cats. In this effort, the Alliance may enlist the help of the wandering Vagabonds who are able to move through the more dangerous woodland paths. Though some may sympathize with the Alliance&rsquo;s hopes and dreams, these wanderers are old enough to remember the great birds of prey who once controlled the woods.\n\nMeanwhile, at the edge of the region, the proud, squabbling Eyrie have found a new commander who they hope will lead their faction to resume their ancient birthright. The stage is set for a contest that will decide the fate of the great woodland. It is up to the players to decide which group will ultimately take root.\n\nIn Root, players drive the narrative, and the differences between each role create an unparalleled level of interaction and replayability. Leder Games invites you and your family to explore the fantastic world of Root!\n\n—description from the publisher", mechanics: ["Aktionspunkte", "Action Queue", "Action Retrieval", "Gebietskontrolle", "Area Movement", "Würfelglück", "Handkartenmanagement", "Multi-Use Cards", "Verhandlung", "Bewegung entlang von Punkten", "Race", "Sudden Death Ending", "Take That", "Variable Spielerfähigkeiten", "Variable Set-up"] },
  { title: "Brass: Birmingham", imageUrl: "https://cf.geekdo-images.com/x3zxjr-Vw5iU4yDPg70Jgw__original/img/FpyxH41Y6_ROoePAilPNEhXnzO8=/0x0/filters:format(jpeg)/pic3490053.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 120, weight: 3.9, description: "Brass: Birmingham is an economic strategy game sequel to Martin Wallace's 2007 masterpiece, Brass. Brass: Birmingham tells the story of competing entrepreneurs in Birmingham during the industrial revolution between the years of 1770 and 1870.\n\nIt offers a very different story arc and experience from its predecessor. As in its predecessor, you must develop, build and establish your industries and network in an effort to exploit low or high market demands. The game is played over two halves: the canal era (years 1770-1830) and the rail era (years 1830-1870). To win the game, score the most VPs. VPs are counted at the end of each half for the canals, rails and established (flipped) industry tiles.\n\nEach round, players take turns according to the turn order track, receiving two actions to perform any of the following actions (found in the original game):\n\n1) Build - Pay required resources and place an industry tile.\n2) Network - Add a rail / canal link, expanding your network.\n3) Develop - Increase the VP value of an industry.\n4) Sell - Sell your cotton, manufactured goods and pottery.\n5) Loan - Take a &pound;30 loan and reduce your income.\n\nBrass: Birmingham also features a new sixth action:\n\n6) Scout - Discard three cards and take a wild location and wild industry card. (This action replaces Double Action Build in original Brass.)", mechanics: ["Chaining", "End Game Bonuses", "Handkartenmanagement", "Income", "Loans", "Market", "Multi-Use Cards", "Streckenbau", "Ownership", "Tags", "Tech Trees / Tech Tracks", "Plättchen platzieren", "Turn Order: Stat-Based", "Variable Set-up"] },
  { title: "Everdell", imageUrl: "https://cf.geekdo-images.com/fjE7V5LNq31yVEW_yuqI-Q__original/img/HQ1ti16wT9lqja5_h3gUfHUIcVI=/0x0/filters:format(png)/pic3918905.png", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 80, weight: 2.8, description: "Within the charming valley of Everdell, beneath the boughs of towering trees, among meandering streams and mossy hollows, a civilization of forest critters is thriving and expanding. From Everfrost to Bellsong, many a year have come and gone, but the time has come for new territories to be settled and new cities established. You will be the leader of a group of critters intent on just such a task. There are buildings to construct, lively characters to meet, events to host—you have a busy year ahead of yourself. Will the sun shine brightest on your city before the winter moon rises?\n\nEverdell is a game of dynamic tableau building and worker placement.\n\nOn their turn a player can take one of three actions:\n\na) Place a Worker: Each player has a collection of Worker pieces. These are placed on the board locations, events, and on Destination cards. Workers perform various actions to further the development of a player's tableau: gathering resources, drawing cards, and taking other special actions.\n\nb) Play a Card: Each player is building and populating a city; a tableau of up to 15 Construction and Critter cards. There are five types of cards: Travelers, Production, Destination, Governance, and Prosperity. Cards generate resources (twigs, resin, pebbles, and berries), grant abilities, and ultimately score points. The interactions of the cards reveal numerous strategies and a near infinite variety of working cities.\n\nc) Prepare for the next Season: Workers are returned to the players supply and new workers are added. The game is played from Winter through to the onset of the following winter, at which point the player with the city with the most points wins.", mechanics: ["Contracts", "End Game Bonuses", "Handkartenmanagement", "Income", "Open Drafting", "Ownership", "Set Collection", "Solospiel", "Tags", "Variable Set-up", "Arbeitereinsatz"] },
  { title: "Splendor", imageUrl: "https://cf.geekdo-images.com/vNFe4JkhKAERzi4T0Ntwpw__original/img/rqcUdtu_N4v-SpI96XVmpYHnJww=/0x0/filters:format(png)/pic8234167.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 30, weight: 1.8, description: "Splendor is a game of chip-collecting and card development. Players are merchants of the Renaissance trying to buy gem mines, means of transportation, shops—all in order to acquire the most prestige points. If you're wealthy enough, you might even receive a visit from a noble at some point, which of course will further increase your prestige.\n\nOn your turn, you may (1) collect chips (gems), or (2) buy and build a card, or (3) reserve one card. If you collect chips, you take either three different kinds of chips or two chips of the same kind. If you buy a card, you pay its price in chips and add it to your playing area. To reserve a card—in order to make sure you get it, or, why not, your opponents don't get it—you place it in front of you face down for later building; this costs you a round, but you also get gold in the form of a joker chip, which you can use as any gem.\n\nAll of the cards you buy increase your wealth as they give you a permanent gem bonus for later buys; some of the cards also give you prestige points. In order to win the game, you must reach 15 prestige points before your opponents do.", mechanics: ["Contracts", "Open Drafting", "Race", "Set Collection"] },
  { title: "King of Tokyo", imageUrl: "https://cf.geekdo-images.com/m_RzXpHURC0_xLkvRSR_sw__original/img/hSvWgiRYJCTTuoLOWTW3c8sYtl8=/0x0/filters:format(jpeg)/pic3043734.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 30, weight: 1.5, description: "In King of Tokyo, you play mutant monsters, gigantic robots, and strange aliens—all of whom are destroying Tokyo and whacking each other in order to become the one and only King of Tokyo.\n\nAt the start of each turn, you roll six dice, which show the following six symbols: 1, 2, or 3 Victory Points, Energy, Heal, and Attack. Over three successive throws, choose whether to keep or discard each die in order to win victory points, gain energy, restore health, or attack other players into understanding that Tokyo is YOUR territory.\n\nThe fiercest player will occupy Tokyo, and earn extra victory points, but that player can't heal and must face all the other monsters alone!\n\nTop this off with special cards purchased with energy that have a permanent or temporary effect, such as the growing of a second head which grants you an additional die, body armor, nova death ray, and more.... and it's one of the most explosive games of the year!\n\nIn order to win the game, one must either destroy Tokyo by accumulating 20 victory points, or be the only surviving monster once the fighting has ended.\n\nFirst Game in the King of Tokyo series", mechanics: ["Würfelglück", "Die Icon Resolution", "King of the Hill", "Open Drafting", "Spielerausscheidung", "Risikomanagement", "Re-rolling and Locking", "Take That"] },
  { title: "Dixit", imageUrl: "https://cf.geekdo-images.com/J0PlHArkZDJ57H-brXW2Fw__original/img/jt3kFCHJ3HJ2079dMLwipFZqdQg=/0x0/filters:format(jpeg)/pic6738336.jpg", minPlayers: 3, maxPlayers: 6, playTimeMinutes: 30, weight: 1.2, description: "Each turn in Dixit, one player is the storyteller who chooses one of the six cards in their hand, then expresses an idea, with sounds or words, that is reflected on that card's image, and places the card face down on the playing surface. Each other player then selects the card that best matches that expression, and passes the selected card to the storyteller, face down.\n\nThe storyteller shuffles all the cards together, then turns them over to reveal them. Each player other than the storyteller then secretly guesses which card belongs to the storyteller. If nobody or everybody guesses the correct card, the storyteller scores 0 points, and each other player scores 2 points. Otherwise, the storyteller and whoever found the correct answer score 3 points. Additionally, the non-storyteller players score 1 point for every vote received by their card.\n\nThe game ends when the deck is empty or if a player has scored at least 30 points. In either case, the player with the most points wins.\n\nThe Dixit base game and each expansion contain 84 cards, and the cards can be mixed together as desired.", mechanics: ["Race", "Gleichzeitige Aktionswahl", "Singing", "Geschichten erzählen", "Targeted Clues", "Abstimmung"] },
  { title: "Concept", imageUrl: "https://cf.geekdo-images.com/hHFs0_KRoW_FJ0cMIVgZcw__original/img/vbR7Wrdlq4fPcwUE1Ck9CowlJHY=/0x0/filters:format(jpeg)/pic4991925.jpg", minPlayers: 4, maxPlayers: 12, playTimeMinutes: 40, weight: 1.4, description: "In Concept, your goal is to guess words through the association of icons. A team of two players – neighbors at the table – choose a word or phrase that the other players need to guess. Acting together, this team places pieces judiciously on the available icons on the game board.\n\nTo get others to guess \"milk\", for example, the team might place the question mark icon (which signifies the main concept) on the liquid icon, then cubes of this color on the icons for \"food/drink\" and \"white\". For a more complicated concept, such as \"Leonardo DiCaprio\", the team can use the main concept and its matching cubes to clue players into the hidden phrase being an actor or director, while then using sub-concept icons and their matching cubes to gives clues to particular movies in which DiCaprio starred, such as Titanic or Inception.\n\nThe first player to discover the word or phrase receives 2 victory points, the team receives points as well, and the player who ends up with the most points wins.", mechanics: ["Communication Limits", "Race", "Teamspiel"] },
  { title: "Just One", imageUrl: "https://cf.geekdo-images.com/74haNunMBn85beBi-yIKwA__original/img/hA22qL6nZxchA8FMTIfhLMcI53I=/0x0/filters:format(png)/pic8669313.png", minPlayers: 3, maxPlayers: 7, playTimeMinutes: 60, weight: 1, description: "Just One is a co-operative party game in which you all play together to get the best score! Your goal each round is to get one player — the active player — to guess a mystery word based on the clues given by teammates. Can you achieve a perfect score by guessing all the mystery words?\n\nIn more detail, everyone who is not the active player sees the mystery word, then each player independently writes a clue on their personal easel. Once everyone has finished, you reveal the clues to one another. All identical clues are removed from play, so try to be original!\n\nAfter eliminating duplicate clues, reveal the remaining clues to the active player. If they correctly guess the mystery word, your team scores a point. If they decline to guess, you don't score the current card. If they guess wrong, you don't score the current card and you lose one of the points you had already scored. Thus, be original, but not so original that you don't help the active player guess correctly!", mechanics: ["Communication Limits", "Kooperativ", "Deduction", "Paper-and-Pencil", "Score-and-Reset Game"] },
  { title: "Sushi Go!", imageUrl: "https://cf.geekdo-images.com/Fn3PSPZVxa3YurlorITQ1Q__original/img/5vRsn2TT9eJmq27i9HtLWKpB_xs=/0x0/filters:format(jpeg)/pic1900075.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 15, weight: 1.2, description: "In the super-fast sushi card game Sushi Go!, you are eating at a sushi restaurant and trying to grab the best combination of sushi dishes as they whiz by. Score points for collecting the most sushi rolls or making a full set of sashimi. Dip your favorite nigiri in wasabi to triple its value! And once you've eaten it all, finish your meal with all the pudding you've got! But be careful which sushi you allow your friends to take; it might be just what they need to beat you!\n\nSushi Go! takes the card-drafting mechanism of Fairy Tale and 7 Wonders and distills it into a twenty-minute game that anyone can play. The dynamics of \"draft and pass\" are brought to the fore, while keeping the rules to a minimum. As you see the first few hands of cards, you must quickly assess the make-up of the round and decide which type of sushi you'll go for. Then, each turn you'll need to weigh which cards to keep and which to pass on. The different scoring combinations allow for some clever plays and nasty blocks. Round to round, you must also keep your eye on the goal of having the most pudding cards at the end of the game!", mechanics: ["Closed Drafting", "End Game Bonuses", "Handkartenmanagement", "Score-and-Reset Game", "Set Collection", "Gleichzeitige Aktionswahl"] },
  { title: "Love Letter", imageUrl: "https://upload.wikimedia.org/wikipedia/en/e/e1/Love_Letter_box_cover.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 20, weight: 1.2, description: "Mit nur 16 Karten versuchen die Spieler, ihren Liebesbrief als Einzige der Prinzessin zu übermitteln, indem sie gegnerische Karten durch Deduktion ausschalten.", mechanics: ["Deduktion", "Bluffen", "Kartenmanagement"] },
  { title: "Skull", imageUrl: null, minPlayers: 3, maxPlayers: 6, playTimeMinutes: 45, weight: 1.6, description: "Die Spieler legen verdeckt Blumen- oder Totenkopfkarten und bieten darauf, wie viele Blumenkarten sie aufdecken können, ohne auf einen Totenkopf zu treffen.", mechanics: ["Bluffen", "Bieten", "Push your luck"] },

  // Batch 2
  { title: "Coup", imageUrl: null, minPlayers: 2, maxPlayers: 6, playTimeMinutes: 15, weight: 1.4, description: "Ein Bluff- und Verhandlungsspiel, bei dem Spieler Charakterkarten mit besonderen Fähigkeiten behaupten zu besitzen, um Gegner aus dem Spiel zu eliminieren.", mechanics: ["Bluffen", "Kartenmanagement", "Eliminierung"] },
  { title: "Bang!", imageUrl: "https://upload.wikimedia.org/wikipedia/en/7/7b/Bang_box_art.jpg", minPlayers: 4, maxPlayers: 7, playTimeMinutes: 30, weight: 1.6, description: "Ein Wildwest-Kartenspiel mit verdeckten Rollen, in dem Sheriff, Gesetzlose, Vizesheriffs und ein Verräter gegeneinander antreten.", mechanics: ["Verdeckte Rollen", "Kartenmanagement", "Bluffen"] },
  { title: "Munchkin", imageUrl: "https://cf.geekdo-images.com/J-ts3MW0UhDzs621TR6cog__original/img/FbqPPCilgZKND2xmhWJgkfjZiYE=/0x0/filters:format(jpeg)/pic1871016.jpg", minPlayers: 3, maxPlayers: 6, playTimeMinutes: 120, weight: 1.8, description: "Publisher's DescriptionGo down in the dungeon. Kill everything you meet. Backstab your friends and steal their stuff. Grab the treasure and run.\n\nAdmit it. You love it.\n\nThis award-winning card game, designed by Steve Jackson, captures the essence of the dungeon experience... with none of that stupid roleplaying stuff. You and your friends compete to kill monsters and grab magic items. And what magic items! Don the Horny Helmet and the Boots of Butt-Kicking. Wield the Staff of Napalm... or maybe the Chainsaw of Bloody Dismemberment. Start by slaughtering the Potted Plant and the Drooling Slime, and work your way up to the Plutonium Dragon...\n\nAnd it's illustrated by John Kovalic! Fast-playing and silly, Munchkin can reduce any roleplaying group to hysteria. And, while they're laughing, you can steal their stuff.\n\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\tOtherPart of the Munchkin series.\n\nMunchkin is a satirical card game based on the clich&eacute;s and oddities of Dungeons and Dragons and other role-playing games. Each player starts at level 1 and the winner is the first player to reach level 10. Players can acquire familiar D&D style character classes during the game which determine to some extent the cards they can play.\n\nThere are two types of cards - treasure and encounters. Each turn the current players 'kicks down the door' - drawing an encounter card from the deck. Usually this will involve battling a monster. Monsters have their own levels and players must try and overcome it using the levels, weapons and powers they have acquired during the game or run away. Other players can chose to help the player or hinder by adding extra monsters to the encounter. Defeating a monster will usually result in drawing treasure cards and acquiring levels.  Being defeated by a monster results in \"bad stuff\" which usually involves losing levels and treasure.\n\nIn May 2010, Steve Jackson Games made the \"big announcement.\" Many rules and cards were changed. See The Great 2010 Munchkin Changeover for details. Of note to Munchkin fans, the Kneepads of Allure card, which had been removed in the 14th printing, was added back to the game but modified to be less powerful.\n\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\tSequels:\n    The Good, the Bad, and the Munchkin\n    Munchkin Apocalypse\n    Munchkin Axe Cop\n    Munchkin Bites!\n    Munchkin Booty\n    Munchkin Conan\n    Munchkin Cthulhu\n    Munchkin Fu\n    Munchkin Impossible\n    Munchkin Legends\n    Munchkin Pathfinder\n    Munchkin Zombies\n    Star Munchkin\n    Super Munchkin\n\n\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\tRelated Board Games\n    Munchkin Quest\n\n\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\tOnline play\n     Vassal does not support Munchkin anymore. Former link: Vassal Module\n\n\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\tPegasus Expansions\n    Munchkin Sammlerbox\n    Munchkin Sammlerkoffer\n    Munchkin Promotional Bookmarks\n    Munchkin Weihnachtsedition - The same as Munchkin, but with a promotional button that grants the wearer extra treasure (when worn in December). \n\n\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\tOnline PlaythroughThere's a great YouTube playthrough with Will Wheaton and Steve Jackson (yes, the Steve Jackson) found here LINK", mechanics: ["Handkartenmanagement", "Race", "Take That", "Variable Spielerfähigkeiten"] },
  { title: "Exploding Kittens", imageUrl: "https://cf.geekdo-images.com/N8bL53-pRU7zaXDTrEaYrw__original/img/0ciN1VZYifUd0qIDO0e8cGXmiss=/0x0/filters:format(png)/pic2691976.png", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 15, weight: 1.1, description: "Exploding Kittens is a kitty-powered version of Russian Roulette. Players take turns drawing cards until someone draws an exploding kitten and loses the game. The deck is made up of cards that let you avoid exploding by peeking at cards before you draw, forcing your opponent to draw multiple cards, or shuffling the deck.\n\nThe game gets more and more intense with each card you draw because fewer cards left in the deck means a greater chance of drawing the kitten and exploding in a fiery ball of feline hyperbole.", mechanics: ["Handkartenmanagement", "Hot Potato", "Spielerausscheidung", "Risikomanagement", "Set Collection", "Take That"] },
  { title: "Betrayal at House on the Hill", imageUrl: "https://cf.geekdo-images.com/lqmt2Oti_qJS65XqHcB8AA__original/img/7R6yYk8A2eUMmSDaxGjae5SceGI=/0x0/filters:format(png)/pic5146864.png", minPlayers: 3, maxPlayers: 6, playTimeMinutes: 60, weight: 2.4, description: "Verrat im House on the Hill sorgt schnell für Spannung und Aufregung, während die Spieler ein Spukhaus nach ihrem eigenen \"Design\" erkunden und auf Geister und erschreckende Omen treffen, die ihr Schicksal vorhersagen.\n\nBetrayal at House on the Hill ist ein Fliesenspiel, mit dem Spieler das Spukhaus Raum für Raum, Fliesen für Fliesen auslegen und jedes Mal ein neues Spielbrett erstellen können. Das Spiel ist für drei bis sechs Personen konzipiert, von denen jede einen von sechs möglichen Charakteren spielt.\n\nDie Spieler erkunden das Spukhaus, sammeln Gegenstände und entdecken Geheimnisse, bis einer der Charaktere einen Spuk auslöst und ein Monster den Rest der Gruppe jagt. Die unschuldigen Mitglieder der Gruppe müssen das Monster in ihrer Mitte besiegen, bevor das Monster sie erwischt!\n\nMit 50 möglichen Treffpunkten und variablen Charakteren pro Spiel hat das Spiel eine großartige Wiederspielbarkeit.", mechanics: ["Würfelglück", "Map Addition", "Modularer Spielplan", "Spielerausscheidung", "Role Playing", "Geschichten erzählen", "Teamspiel", "Traitor Game", "Variable Spielerfähigkeiten"] },
  { title: "Arkham Horror", imageUrl: "https://upload.wikimedia.org/wikipedia/en/e/ed/Arkham_Horror_revised_box.jpg", minPlayers: 1, maxPlayers: 8, playTimeMinutes: 240, weight: 3.2, description: "Ein kooperatives Horror-Abenteuerspiel im Lovecraft-Universum, in dem Ermittler versuchen, Portale zu schließen, bevor ein Großer Alter erwacht.", mechanics: ["Kooperativ", "Würfelglück", "Kartenmanagement"] },
  { title: "Eldritch Horror", imageUrl: "https://cf.geekdo-images.com/oxdsZKIX5_3ovDo38EIaeg__original/img/vxK08kQAEn5qPbejK2CUTyWOsig=/0x0/filters:format(jpeg)/pic1872452.jpg", minPlayers: 1, maxPlayers: 8, playTimeMinutes: 240, weight: 3.3, description: "Across the globe, ancient evil is stirring. Now, you and your trusted circle of colleagues must travel around the world, working against all odds to hold back the approaching horror. Foul monsters, brutal encounters, and obscure mysteries will take you to your limit and beyond. All the while, you and your fellow investigators must unravel the otherworldy mysteries scattered around the globe in order to push back the gathering mayhem that threatens to overwhelm humanity. The end draws near! Do you have the courage to prevent global destruction?\n\nEldritch Horror is a co-operative game of terror and adventure in which one to eight players take the roles of globetrotting investigators working to solve mysteries, gather clues, and protect the world from an Ancient One – that is, an elder being intent on destroying our world. Each Ancient One comes with its own unique decks of Mystery and Research cards, which draw you deeper into the lore surrounding each loathsome creature. Discover the true name of Azathoth or battle Cthulhu on the high seas.\n\nWhile the tasks on these Mystery cards (along with the locations of otherworldly gates, menacing monsters, and helpful clues) will often inform both your travel plans and the dangers you confront, you can find adventure anywhere in the world...even where you least expect it. It is during the Encounter Phase of each turn that players resolve combat or, alternatively, build their investigators' personal stories by reading an encounter narrative from one of several types of Encounter cards. You might go head to head with a monster in Istanbul or find yourself in a tough spot with the crime syndicate in a major city. Maybe you will embark on an expedition to the Pyramids or research a clue you uncover in the unnamed wilderness. You may even find your way through a gate and explore a dimension beyond time and space.\n\nShould you fail an encounter, the cost is steep. If you are fortunate, you will merely incur physical or mental trauma. However, you might also be compelled to take a Condition card, which represents a specific injury or restriction gained throughout your journey, such as a Leg Injury or Amnesia. You could find yourself getting in over your head to acquire assets and receive a Debt condition – or maybe you'll owe a favor to something far more insidious than a debt collector, and enter into a Dark Pact! Whatever your condition, you would be wise to find a resolution with haste; many conditions have a \"reckoning effect\" which, if triggered, ensure a much more sinister fate.\n\nAll the while, the arrival of the Ancient One approaches. Its malign influence is manifested in Eldritch Horror as you draw Mythos Cards, which govern the appearance of otherworldly gates, fearsome monsters, and other ominous elements. Mythos cards keep your investigators under pressure, introducing new threats, even as the arrival of the Great Old One draws nearer! Since the investigators draw a new Mythos card each round, they're certain to have their hands full battling foul creatures and following up on strange rumors, even as they work to solve their three all-important mysteries.\n\nWith twelve unique investigators, two hundred-fifty tokens, and over three hundred cards, Eldritch Horror presents an epic, world-spanning adventure with each and every game.", mechanics: ["Aktionspunkte", "Kooperativ", "Würfelglück", "Events", "Pick-up and Deliver", "Bewegung entlang von Punkten", "Resource to Move", "Role Playing", "Solospiel", "Stat Check Resolution", "Variable Spielerfähigkeiten", "Variable Set-up"] },
  { title: "Mansions of Madness", imageUrl: "https://cf.geekdo-images.com/JtjGOgkaIxnLUeoV56cWFQ__original/img/47Cef6w56t2Vomn6bO8aT5p1ZiI=/0x0/filters:format(jpeg)/pic814011.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 180, weight: 3.2, description: "Description from the publisher:\n\nHorrific monsters and spectral presences lurk in manors, crypts, schools, monasteries, and derelict buildings near Arkham, Massachusetts. Some spin dark conspiracies while others wait for hapless victims to devour or drive insane. It&rsquo;s up to a handful of brave investigators to explore these cursed places and uncover the truth about the living nightmares within.\n\nDesigned by Corey Konieczka, Mansions of Madness is a macabre game of horror, insanity, and mystery for two to five players. Each game takes place within a pre-designed story that provides players with a unique map and several combinations of plot threads. These threads affect the monsters that investigators may encounter, the clues they need to find, and which climactic story ending they will ultimately experience. One player takes on the role of the keeper, controlling the monsters and other malicious powers within the story. The other players take on the roles of investigators, searching for answers while struggling to survive with their minds intact.\n\nDo you dare enter the Mansions of Madness?", mechanics: ["Area Movement", "Würfelglück", "Handkartenmanagement", "Modularer Spielplan", "Pick-up and Deliver", "Role Playing", "Scenario / Mission / Campaign Game", "Teamspiel", "Variable Spielerfähigkeiten"] },
  { title: "Descent: Journeys in the Dark", imageUrl: "https://cf.geekdo-images.com/915Abv-1k4_f_-__SkXybg__original/img/LEJxK0iifCkmJcX0uytGCk72v8M=/0x0/filters:format(jpeg)/pic249300.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 240, weight: 3.3, description: "Descent: Journeys in the Dark is a \"one vs. many\" game in which up to four players will choose characters with a wide assortment of skills and innate abilities to be the heroes who will explore dungeons in search of treasure and adventure, while one player will take on the role of the Overlord and will control the dungeon's many traps, puzzles, and monsters.\n\nThe heroes' goal will be to cooperatively conquer the dungeon, seize its many treasures, and achieve other objectives as set by the scenario. If the heroes cooperate and achieve their goals, they will all win. The Overlord's objective is simply to use all the means at their disposal - from deadly traps to ferocious monsters - to kill the heroes. Each hero has a certain Conquest Point value to the party and if too many Conquest Points are lost through hero death, the party loses and the Overlord wins.\n\nRe-implemented by:\n\n    Descent: Journeys in the Dark (Second Edition) (2012)", mechanics: ["Würfelglück", "Bewegung auf Gitterfeld", "Modularer Spielplan", "Role Playing", "Teamspiel", "Variable Spielerfähigkeiten"] },
  { title: "Small World", imageUrl: "https://cf.geekdo-images.com/aoPM07XzoceB-RydLh08zA__original/img/bYLzrwZO9u-3h2wyU-PHc8aTOY4=/0x0/filters:format(jpeg)/pic428828.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 80, weight: 2.3, description: "In Small World, players vie for conquest and control of a world that is simply too small to accommodate them all.\n\nDesigned by Philippe Keyaerts as a fantasy follow-up to his award-winning Vinci, Small World is inhabited by a zany cast of characters such as dwarves, wizards, amazons, giants, orcs, and even humans, who use their troops to occupy territory and conquer adjacent lands in order to push the other races off the face of the earth.\n\nPicking the right combination from the 14 different fantasy races and 20 unique special powers, players rush to expand their empires - often at the expense of weaker neighbors. Yet they must also know when to push their own over-extended civilization into decline and ride a new one to victory!\n\nOn each turn, you either use the multiple tiles of your chosen race (type of creatures) to occupy adjacent (normally) territories - possibly defeating weaker enemy races along the way, or you give up on your race letting it go \"into decline\". A race in decline is designated by flipping the tiles over to their black-and-white side.\n\nAt the end of your turn, you score one point (coin) for each territory your races occupy. You may have one active race and one race in decline on the board at the same time. Your occupation total can vary depending on the special abilities of your race and the territories they occupy. After the final round, the player with the most coins wins.\n\nClarifications: available in a pinned forum post.", mechanics: ["Gebietskontrolle", "Area Movement", "Würfelglück", "Hidden Victory Points", "Increase Value of Unchosen Resources", "Variable Spielerfähigkeiten", "Variable Set-up", "Victory Points as a Resource"] },
  { title: "Ticket to Ride: Europe", imageUrl: "https://cf.geekdo-images.com/EQJZDO1Jq8KL-HxmWLwL-Q__original/img/LOC8D0q01ZRvZ6v1n7l8Zueos-E=/0x0/filters:format(jpeg)/pic9580918.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 60, weight: 1.9, description: "Ticket to Ride: Europe takes you on a new train adventure across Europe. From Edinburgh to Constantinople and from Lisbon to Moscow, you'll visit great cities of turn-of-the-century Europe. Like the original Ticket to Ride, the game remains elegantly simple, can be learned in 5 minutes, and appeals to both families and experienced gamers. Ticket to Ride: Europe is a complete, new game and does not require the original version.\n\nMore than just a new map, Ticket to Ride: Europe features brand new gameplay elements. Tunnels may require you to pay extra cards to build on them, Ferries require locomotive cards in order to claim them, and Stations allow you to sacrifice a few points in order to use an opponent's route to connect yours. The game also includes larger format cards and Train Station game pieces.\n\nThe overall goal remains the same: collect and play train cards in order to place your pieces on the board, attempting to connect cities on your ticket cards. Points are earned both from placing trains and completing tickets but uncompleted tickets lose you points. The player who has the most points at the end of the game wins.\n\nCopyright 2002-2014 Days of Wonder, inc.\n\nPart of the Ticket to Ride series.", mechanics: ["Connections", "Contracts", "End Game Bonuses", "Handkartenmanagement", "Streckenbau", "Open Drafting", "Risikomanagement", "Set Collection"] },
  { title: "Star Wars: Rebellion", imageUrl: "https://cf.geekdo-images.com/7SrPNGBKg9IIsP4UQpOi8g__original/img/GKueTbkCk2Ramf6ai8mDj-BP6cI=/0x0/filters:format(jpeg)/pic4325841.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 240, weight: 3.8, description: "Star Wars: Rebellion is a board game of epic conflict between the Galactic Empire and Rebel Alliance for two to four players.\n\nExperience the Galactic Civil War like never before. In Rebellion, you control the entire Galactic Empire or the fledgling Rebel Alliance. You must command starships, account for troop movements, and rally systems to your cause. Given the differences between the Empire and Rebel Alliance, each side has different win conditions, and you'll need to adjust your play style depending on who you represent:\n\n     As the Imperial player, you can command legions of Stormtroopers, swarms of TIEs, Star Destroyers, and even the Death Star. You rule the galaxy by fear, relying on the power of your massive military to enforce your will. To win the game, you need to snuff out the budding Rebel Alliance by finding its base and obliterating it. Along the way, you can subjugate worlds or even destroy them.\n     As the Rebel player, you can command dozens of troopers, T-47 airspeeders, Corellian corvettes, and fighter squadrons. However, these forces are no match for the Imperial military. In terms of raw strength, you'll find yourself clearly overmatched from the very outset, so you'll need to rally the planets to join your cause and execute targeted military strikes to sabotage Imperial build yards and steal valuable intelligence. To win the Galactic Civil War, you'll need to sway the galaxy's citizens to your cause. If you survive long enough and strengthen your reputation, you inspire the galaxy to a full-scale revolt, and you win.\n\n\nFeaturing more than 150 plastic miniatures and two game boards that account for thirty-two of the Star Wars galaxy's most notable systems, Rebellion features a scope that is as large and sweeping as any Star Wars game before it.\n\nYet for all its grandiosity, Rebellion remains intensely personal, cinematic, and heroic. As much as your success depends upon the strength of your starships, vehicles, and troops, it depends upon the individual efforts of such notable characters as Leia Organa, Mon Mothma, Grand Moff Tarkin, and Emperor Palpatine. As civil war spreads throughout the galaxy, these leaders are invaluable to your efforts, and the secret missions they attempt will evoke many of the most inspiring moments from the classic trilogy. You might send Luke Skywalker to receive Jedi training on Dagobah or have Darth Vader spring a trap that freezes Han Solo in carbonite!", mechanics: ["Gebietskontrolle", "Area Movement", "Card Play Conflict Resolution", "Contracts", "Delayed Purchase", "Würfelglück", "Die Icon Resolution", "Events", "Handkartenmanagement", "Hidden Movement", "Income", "Once-Per-Game Abilities", "Tags", "Take That", "Teamspiel", "Variable Spielerfähigkeiten", "Variable Set-up", "Worker Placement, Different Worker Types"] },
  { title: "Twilight Struggle", imageUrl: "https://cf.geekdo-images.com/pNCiUUphnoeWOYfsWq0kng__original/img/Iae47UtAd_RXVd5tJ3YzbDHOv4E=/0x0/filters:format(jpeg)/pic3530661.jpg", minPlayers: 2, maxPlayers: 2, playTimeMinutes: 180, weight: 3.6, description: "Now the trumpet summons us again, not as a call to bear arms, though arms we need; not as a call to battle, though embattled we are – but a call to bear the burden of a long twilight struggle. – John F. Kennedy\n\nIn 1945, unlikely allies toppled Hitler's war machine, while humanity's most devastating weapons forced the Japanese Empire to its knees in a storm of fire. Where once there stood many great powers, there then stood only two. Unlike the titanic struggles of the preceding decades, this conflict would be waged not primarily by soldiers and tanks, but by spies and politicians, scientists and intellectuals, artists and traitors.\n\nTwilight Struggle is a two-player game simulating the forty-five year dance of intrigue, prestige, and occasional flares of warfare between the Soviet Union and the United States. The game begins amidst the ruins of Europe as the two new \"superpowers\" scramble over the wreckage of the Second World War, and ends in 1989.\n\nTwilight Struggle inherits its fundamental systems from We the People and Hannibal: Rome vs. Carthage. It is a quick-playing, low-complexity game in that tradition. The game map is a world map of the period, where players move units and exert influence in attempts to gain allies and control for their superpower. Decision-making is a challenge; how to best use one's cards and units given consistently limited resources? Event cards add detail and flavor to the game.\n\nThere are several ways to achieve an automatic victory in Twilight Struggle. But, If neither side has achieved victory of any kind by the end of turn 10, the points are totaled and the player with the most points wins.", mechanics: ["Action / Event", "Advantage Token", "Gebietskontrolle", "Campaign / Battle Card Driven", "Würfelglück", "Events", "Handkartenmanagement", "Simulation", "Gleichzeitige Aktionswahl", "Stat Check Resolution", "Sudden Death Ending", "Tug of War", "Variable Spielerfähigkeiten", "Variable Set-up"] },
  { title: "Through the Ages", imageUrl: "https://upload.wikimedia.org/wikipedia/en/f/f5/Through_the_Ages%2C_A_Story_of_Civilization_board_game_box_cover.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 240, weight: 4.4, description: "Ein Zivilisationsaufbauspiel, in dem Spieler über Jahrtausende hinweg Technologien, Wunder und Militär entwickeln.", mechanics: ["Worker Placement", "Kartenmanagement", "Zivilisationsaufbau"] },
  { title: "Great Western Trail", imageUrl: "https://cf.geekdo-images.com/u1l0gH7sb_vnvDvoO_QHqA__original/img/2zv_XMQoPFWk9Dn0oS4JY1IeFzw=/0x0/filters:format(jpeg)/pic4887376.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 150, weight: 3.7, description: "America in the 19th century: You are a rancher and repeatedly herd your cattle from Texas to Kansas City, where you send them off by train. This earns you money and victory points. Needless to say, each time you arrive in Kansas City, you want to have your most valuable cattle in tow. However, the \"Great Western Trail\" not only requires that you keep your herd in good shape, but also that you wisely use the various buildings along the trail. Also, it might be a good idea to hire capable staff: cowboys to improve your herd, craftsmen to build your very own buildings, or engineers for the important railroad line.\n\nIf you cleverly manage your herd and navigate the opportunities and pitfalls of Great Western Trail, you surely will gain the most victory points and win the game.\n\n—description from the publisher", mechanics: ["Contracts", "Deck, Bag, and Pool Building", "Handkartenmanagement", "Income", "Ownership", "Rondel", "Set Collection", "Track Movement", "Variable Set-up"] },
  { title: "Viticulture", imageUrl: "https://cf.geekdo-images.com/WrnWFA1Sysm3-nQyBe1sUA__original/img/cGg9S0AH41VxczdybvFsb81AKWw=/0x0/filters:format(jpeg)/pic2619743.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 90, weight: 2.9, description: "In Viticulture, the players find themselves in the roles of people in rustic, pre-modern Tuscany who have inherited meager vineyards. They have a few plots of land, an old crushpad, a tiny cellar, and three workers. They each have a dream of being the first to call their winery a true success.\n\nThe players are in the position of determining how they want to allocate their workers throughout the year. Every season is different on a vineyard, so the workers have different tasks they can take care of in the summer and winter. There's competition over those tasks, and often the first worker to get to the job has an advantage over subsequent workers.\n\nFortunately for the players, people love to visit wineries, and it just so happens that many of those visitors are willing to help out around the vineyard when they visit as long as you assign a worker to take care of them. Their visits (in the form of cards) are brief but can be very helpful.\n\nUsing those workers and visitors, players can expand their vineyards by building structures, planting vines (vine cards), and filling wine orders (wine order cards). Players work towards the goal of running the most successful winery in Tuscany.", mechanics: ["Contracts", "Handkartenmanagement", "Income", "Race", "Turn Order: Progressive", "Arbeitereinsatz"] },
  { title: "Tzolk'in: The Mayan Calendar", imageUrl: "https://cf.geekdo-images.com/kXf7mDyDYuHg6oe8yTUIEA__original/img/f6-Au0KTnNR4nugSu2U-wPNbZCU=/0x0/filters:format(jpeg)/pic4604439.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 90, weight: 3.7, description: "Tzolkin: The Mayan Calendar presents a new game mechanism: dynamic worker placement. Players representing different Mayan tribes place their workers on giant connected gears, and as the gears rotate they take the workers to different action spots.\n\nDuring a turn, players can either (a) place one or more workers on the lowest visible spot of the gears or (b) pick up one or more workers. When placing workers, they must pay corn, which is used as a currency in the game. When they pick up a worker, they perform certain actions depending on the position of the worker. Actions located \"later\" on the gears are more valuable, so it's wise to let the time work for you – but players cannot skip their turn; if they have all their workers on the gears, they have to pick some up. \n\nThe game ends after one full revolution of the central Tzolkin gear. There are many paths to victory. Pleasing the gods by placing crystal skulls in deep caves or building many temples are just two of those many paths...", mechanics: ["Bias", "End Game Bonuses", "Once-Per-Game Abilities", "Track Movement", "Turn Order: Claim Action", "Arbeitereinsatz"] },
  { title: "Caverna: The Cave Farmers", imageUrl: "https://cf.geekdo-images.com/EAqbd46lFxo-7GumlO8U4w__original/img/oNM6bkDbjww-7nKZX-WYYmPxRws=/0x0/filters:format(jpeg)/pic5598833.jpg", minPlayers: 1, maxPlayers: 7, playTimeMinutes: 210, weight: 3.8, description: "Following along the same lines as its predecessor (Agricola), Caverna: The Cave Farmers is a worker-placement game at heart, with a focus on farming. In the game, you are the bearded leader of a small dwarf family that lives in a little cave in the mountains. You begin the game with a farmer and his spouse, and each member of the farming family represents an action that the player can take each turn. Together, you cultivate the forest in front of your cave and dig deeper into the mountain. You furnish the caves as dwellings for your offspring as well as working spaces for small enterprises.\n\nIt's up to you how much ore you want to mine. You will need it to forge weapons that allow you to go on expeditions to gain bonus items and actions. While digging through the mountain, you may come across water sources and find ore and ruby mines that help you increase your wealth. Right in front of your cave, you can increase your wealth even further with agriculture: You can cut down the forest to sow fields and fence in pastures to hold your animals. You can also expand your family while running your ever-growing farm. In the end, the player with the most efficiently developed home board wins.\n\nYou can also play the solo variant of this game to familiarize yourself with the 48 different furnishing tiles for your cave.\n\nCaverna: The Cave Farmers, which has a playing time of roughly 30 minutes per player, is a complete redesign of Agricola that substitutes the card decks from the former game with a set of buildings while adding the ability to purchase weapons and send your farmers on quests to gain further resources. Designer Uwe Rosenberg says that the game includes parts of Agricola, but also has new ideas, especially the cave part of your game board, where you can build mines and search for rubies. The game also includes two new animals: dogs and donkeys.", mechanics: ["Automatic Resource Growth", "Increase Value of Unchosen Resources", "Solospiel", "Plättchen platzieren", "Turn Order: Claim Action", "Arbeitereinsatz"] },
  { title: "Le Havre", imageUrl: "https://cf.geekdo-images.com/y7Rqd3S6J7vyVhicR1bqTQ__original/img/tQFXv1w2R-J-1cjyaKG9LAS2UOs=/0x0/filters:format(jpeg)/pic6091101.jpg", minPlayers: 1, maxPlayers: 5, playTimeMinutes: 150, weight: 3.7, description: "In Le Havre, a player's turn consists of two parts: First, distribute newly supplied goods onto the offer spaces; then take an action. As an action, players may choose either to take all goods of one type from an offer space or to use one of the available buildings. Building actions allow players to upgrade goods, sell them or use them to build their own buildings and ships. Buildings are both an investment opportunity and a revenue stream, as players must pay an entry fee to use buildings that they do not own. Ships, on the other hand, are primarily used to provide the food that is needed to feed the workers.\n\nAfter every seven turns, the round ends: players' cattle and grain may multiply through a Harvest, and players must feed their workers. After a fixed number of rounds, each player may carry out one final action, and then the game ends. Players add the value of their buildings and ships to their cash reserves. The player who has amassed the largest fortune is the winner.", mechanics: ["Automatic Resource Growth", "End Game Bonuses", "Increase Value of Unchosen Resources", "Loans", "Ownership", "Solospiel", "Arbeitereinsatz"] },
  { title: "Power Grid", imageUrl: "https://cf.geekdo-images.com/yd6LuatytHRhcFCxCf-EEg__original/img/OS13C6W4i1XW__wWVVVaqF7BV0c=/0x0/filters:format(jpeg)/pic4459753.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 120, weight: 3.2, description: "Power Grid is the updated release of the Friedemann Friese crayon game Funkenschlag. It removes the crayon aspect from network building in the original edition, while retaining the fluctuating commodities market like Crude: The Oil Game and an auction round intensity reminiscent of The Princes of Florence.\n\nThe objective of Power Grid is to supply the most cities with power when someone's network gains a predetermined size.  In this new edition, players mark pre-existing routes between cities for connection, and then bid against each other to purchase the power plants that they use to power their cities.\n\nHowever, as plants are purchased, newer, more efficient plants become available, so by merely purchasing, you're potentially allowing others access to superior equipment.\n\nAdditionally, players must acquire the raw materials (coal, oil, garbage, and uranium) needed to power said plants (except for the 'renewable' windfarm/ solar plants, which require no fuel), making it a constant struggle to upgrade your plants for maximum efficiency while still retaining enough wealth to quickly expand your network to get the cheapest routes.\n\n☛ Power Grid FAQ - Please read this before posting a rules question!  Many questions are asked over and over in the forums... If you have a question about a specific expansion, please check the rules forum or FAQ for that particular expansion.", mechanics: ["Auction / Bidding", "Auction: Turn Order Until Pass", "Catch the Leader", "Income", "Market", "Streckenbau", "Turn Order: Stat-Based", "Variable Set-up"] },
  { title: "Kingdom Death: Monster", imageUrl: "https://cf.geekdo-images.com/LenzJBOHboAGU0cUIqAZPQ__original/img/-dnx4zkvdOn3CMVHpXIfESazj40=/0x0/filters:format(jpeg)/pic2931007.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 180, weight: 4.3, description: "Kingdom Death: Monster is a fully cooperative tabletop hobby game experience.  Set in a unique nightmarish world devoid of most natural resources, you control a settlement at the dawn of its existence. Fight monsters, craft weapons and gear, and develop your settlement to ensure your survival from generation to generation.\n\nCampaign System\nEmbark alone or with up to 3 friends (5 with game variant) on a 5-30-lantern-year campaign, with each year consisting of a cycle of hunt, showdown, and settlement phases. The settlement phase is an intricate civilization building game in which you spend very limited resources to build buildings, research new technologies, train your warriors, and set up your strategy for survival.  During the hunt, you'll encounter a series of stories in a \"choose your own adventure\" style journey through various events and encounters.  Finally, when you meet the monster you're pursuing, you'll engage it in an a massive arena-style battle where only one party is going to survive.  If your party lives, you'll be able to bring the spoils back home to use in expanding your settlement.\n\nMonster AI System\nEach of the 7 monsters included are controlled by their own pair of decks that scale to 3 levels of difficulty (except for the final encounter, which has only 1 level and it's HARD!). Every encounter, even with the same monster, is highly variable and no two showdowns will resolve the same way. Players will have to plan their gear and keep their minds sharp to prevail.\n\nGear System\nIn Kingdom Death: Monster, survivors will craft gear from resources earned from defeating monsters or found on their hunt. Each survivor has a 3x3 gear grid. Selection and arrangement of your gear cards is critical, as many provided bonuses and activate special rules when aligned correctly.\n\nStory Event System\n40+ Story Events plus over 100 hunt encounters will shape and guide your campaign. Story Events detail important evolutions in your civilization, introduce new monsters, and provide rich detail for your campaign.  Some will trigger automatically as you progress through the campaign, but most will be entirely based on choices players make.\n\nStory Events cover everything from setting up and fighting a monster to key events that happen within the overall story. Some are triggered directly from the timeline and others from choices you make in game.", mechanics: ["Kooperativ", "Critical Hits and Failures", "Würfelglück", "Events", "Bewegung auf Gitterfeld", "Narrative Choice / Paragraph", "Paper-and-Pencil", "Musterbildung", "Role Playing", "Scenario / Mission / Campaign Game", "Solospiel", "Square Grid", "Geschichten erzählen", "Tech Trees / Tech Tracks"] },
  { title: "Blood Rage", imageUrl: "https://cf.geekdo-images.com/HkZSJfQnZ3EpS214xtuplg__original/img/Myy6IPDJDzLoPdXrPXVZcddBQoQ=/0x0/filters:format(jpeg)/pic2439223.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 90, weight: 2.9, description: "\"Leben ist Kampf; Kampf ist Ruhm; Ruhm ist ALLES\"\n\nIn Blood Rage kontrollieren die Spieler die Krieger, den Anführer und das Schiff ihres eigenen Wikinger-Clans. Ragnarök ist gekommen und es ist das Ende der Welt! Es ist die letzte Chance der Wikinger, in einer Flamme des Ruhms unterzugehen und sich ihren Platz in Walhalla an Odins Seite zu sichern! Als Wikinger kannst du einen von vielen Wegen zum Ruhm gehen. Du kannst: in das Land eindringen und es für seine Belohnungen plündern; deine Gegner im Kampf vernichten: Missionen erfüllen: die Werte deines Clans erhöhen: oder sogar glorreich im Kampf oder von Ragnarök, dem ultimativen unausweichlichen Untergang, sterben.\n\nDie meisten Spielerstrategien orientieren sich an den Karten, die zu Beginn jeder der drei Spielrunden (oder Altersgruppen) gezogen werden. Diese \"Geschenke der Götter\" gewähren dir zahlreiche Segnungen für deinen Clan, darunter: erhöhte Wikinger-Stärke und hinterhältige Kampfstrategien, Upgrades für deinen Clan oder sogar die Hilfe legendärer Kreaturen aus der nordischen Mythologie. Sie können auch verschiedene Quests beinhalten, von der Beherrschung bestimmter Provinzen bis hin zur Entsendung vieler deiner Wikinger nach Walhalla. Die meisten dieser Karten sind auf einen der nordischen Götter ausgerichtet, was auf die Art von Strategie hindeutet, die sie unterstützen. Zum Beispiel gibt Thor mehr Ruhm für den Sieg im Kampf. Heimdall gewährt dir Weitsicht und Überraschungen. Tyr stärkt dich im Kampf, während der Trickster Loki dich tatsächlich für das Verlieren von Schlachten belohnt oder den Gewinner bestraft.\n\nDie Spieler müssen ihre Strategien während der Entwurfsphase sorgfältig auswählen, aber auch bereit sein, sich anzupassen", mechanics: ["Aktionspunkte", "Gebietskontrolle", "Area Movement", "Card Play Conflict Resolution", "Closed Drafting", "Contracts", "Handkartenmanagement", "Interrupts", "Map Reduction", "Merkfähigkeit", "Gleichzeitige Aktionswahl", "Take That", "Turn Order: Progressive"] },
  { title: "Rising Sun", imageUrl: "https://cf.geekdo-images.com/iwevA6XmiNLHn1QnGUucqw__original/img/pKJ1XyLN4hvHim5eRj2VJHijv1E=/0x0/filters:format(jpeg)/pic3880340.jpg", minPlayers: 3, maxPlayers: 5, playTimeMinutes: 120, weight: 3.3, description: "The great and forgotten Kami have returned from the underworld, displeased with the affairs of the Empire&rsquo;s present Shōgun. At the start of spring in the Great New Year, the Kami have gathered their sacred clans with one quest: reclaim the lands of Nippon and return them to their honorable, spiritual traditions. However, each clan is bound by their own proud traditions to a unique vision for this great return and must wage a powerful diplomatic war across eight provinces. Alliances must be forged, betrayal is inevitable, honorable standing rises and falls. Political mandates must be navigated and devastating war must be fought, each won by expert skill and cunning negotiation. And only one may stand victorious at the coming of winter. You, honorable Shōgun, lead one of these great clans. Do you have the strength of honor, virtue, and spirit, as well as the mastery of steel necessary to deliver on this ancient promise?\n\nRising  Sun is a board game for 3 to 5 players set in legendary feudal Japan. Each player chooses a Clan and competes to lead theirs to victory by accumulating Victory Points over the course of the Seasons. Each Clan possesses a unique ability and differs in Seasonal Income, Starting Honor Rank, and Home Province.\nOver the course of the game, players will forge and break alliances, choose political actions, worship the gods, customize their clans, and position their figures around Japan. In the process, Honor is a palpable element in Rising Sun: Having high Honor gives several advantages, while having low Honor may grant the allegiance of the darker elements of the world. But above all, Honor settles all disputes: Whenever there is a tie, the tied player with the highest Honor wins.\n\nIn Rising  Sun, players are encouraged to use diplomacy, negotiation, and even bribery to further their cause. Players can make deals at any point in the game but no deals are truly binding.\nVictory Points can be gained in several ways, from winning battles, to harvesting the right provinces, to playing to the Virtues accumulated by your Clan.\n\nThe game is played over the course of 4 rounds or Seasons: Spring, Summer, and then Autumn; when  Winter  comes,  the  game  draws to a close and players calculate bonuses to decide who is the winner. \nEach Season is divided into five phases: \n1) Seasonal Setup because every Season has a certain Season deck with different cards, \n2) Tea Ceremony in which players sit down and negotiate their Alliances for the Season, \n3) Political Phase during which players will select Political Mandates to prepare their Clans and position their forces,\n4) War Phase, during which players battle over several Provinces, and \n5) Seasonal Cleanup.\n\nAs already mentioned, the start of the Winter Season signifies the end of the game. Peace falls over the land as it gets covered in white snow, and a new Emperor will rise under the power of the great Kami.", mechanics: ["Action Drafting", "Alliances", "Gebietskontrolle", "Area Movement", "Auction: Sealed Bid", "Betting and Bluffing", "Closed Drafting", "End Game Bonuses", "Follow", "Force Commitment", "Verhandlung", "Set Collection", "Gleichzeitige Aktionswahl", "Take That", "Variable Phase Order", "Variable Spielerfähigkeiten", "Variable Set-up"] },
  { title: "Cthulhu Wars", imageUrl: "https://cf.geekdo-images.com/o7tGTkPv322I-qCHuisP3g__original/img/71_5dM41youEYIsVgC3rEwINb08=/0x0/filters:format(png)/pic9616343.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 120, weight: 3.1, description: "Cthulhu Wars is a strategy boardgame in which the players take the part of alien races and gods taken from the Cthulhu mythos created by H. P. Lovecraft. The game is physically large, and includes sixty-four  figurines of the cultists, monsters, aliens, and Great Old Ones that range in height from approximately 20 mm to nearly 180 mm.\n\nThe game takes place on a map of Earth. Each player takes the part of one of four factions included in the base game. At the start of a turn, players Gather Power, then, during a series of Action Rounds, they spend this Power to accomplish various tasks, such as recruiting Cultists, moving units, engaging in battle, summoning monsters, building Gates, casting spells, and Awakening their Great Old One. When all players run out of Power, the Action phase ends and the next turn begins. Victory is determined by accumulating points on the Doom Track. The first player to 30 is the lone victor *if* they have unlocked all six of their spell books.\n\nDriving the strategy are a player's wish to expand their power base, and their need to accomplish six tasks to acquire their faction's spell books. Each faction has a unique set of monsters, spell books, and special abilities, and has different requirements to acquire its spell books. All factions have multiple strategies open to them.\n\nThe base game supports 2-4 players (the map supports 5 players), but with new factions and maps released as expansions it can support up to 8 players.", mechanics: ["Aktionspunkte", "Gebietskontrolle", "Area Movement", "Würfelglück", "Variable Spielerfähigkeiten"] },
  { title: "War of the Ring", imageUrl: "https://upload.wikimedia.org/wikipedia/en/7/7e/Warofthering.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 180, weight: 3.9, description: "Ein episches Strategiespiel nach Tolkiens Der Herr der Ringe, in dem die Freien Völker gegen die Streitkräfte Saurons antreten.", mechanics: ["Asymmetrie", "Gebietskontrolle", "Kartenmanagement"] },

  // Batch 3
  { title: "A Game of Thrones: The Board Game", imageUrl: "https://cf.geekdo-images.com/M_7UvwZvuxBVjxdadsa5AA__original/img/3tv6H7jX5T9rqwuI84YZKZDBGcw=/0x0/filters:format(jpeg)/pic1077906.jpg", minPlayers: 3, maxPlayers: 6, playTimeMinutes: 240, weight: 3.7, description: "Spielbeschreibung des Herausgebers:\n\nKönig Robert Baratheon ist tot und die Länder von Westeros bereiten sich auf den Kampf vor.\n\nIn der zweiten Ausgabe von A Game of Thrones: The Board Game übernehmen drei bis sechs Spieler die Rollen der großen Häuser der Sieben Königreiche von Westeros, während sie durch Diplomatie und Kriegsführung um die Kontrolle des Eisernen Throns kämpfen. A Game of Thrones basiert auf der Bestseller-Serie A Song of Ice and Fire von George R.R. Martin und ist ein episches Brettspiel, in dem es mehr als militärische Macht braucht, um zu gewinnen. Wirst du die Macht mit Gewalt übernehmen, honigsüße Worte verwenden, um dich auf den Thron zu zwingen, oder die Stadtbewohner auf deine Seite ziehen? Durch strategische Planung, meisterhafte Diplomatie und cleveres Kartenspiel verbreiten Sie Ihren Einfluss auf Westeros!\n\nZu Beginn des Spiels erhält jeder Spieler eine Armee aus Lakaien-, Ritter-, Belagerungsmaschinen- und Schiffseinheiten sowie eine Reihe von Ordensmarken und anderen notwendigen Komponenten. Jeder Spieler erhält auch ein Deck mit einzigartigen Hauskarten, die als Anführer in Kämpfen gegen rivalisierende Häuser verwendet werden.\n\nJede Runde im Spiel besteht aus drei Phasen: der Westeros-Phase, der Planungsphase und der Aktionsphase. Die Westeros-Phase steht für besondere Ereignisse und alltägliche Aktivitäten in Westeros. Es gibt drei verschiedene Westeros-Decks, und jedes weist auf eine andere globale Aktion hin, die möglicherweise alle Spieler betrifft.\n\nDie Planungsphase ist vielleicht die wichtigste. Hier weisen Sie allen Ihren Einheiten heimlich Bestellungen zu, indem Sie eine", mechanics: ["Advantage Token", "Alliances", "Gebietskontrolle", "Area Movement", "Auction / Bidding", "Auction: Sealed Bid", "Card Play Conflict Resolution", "Events", "Handkartenmanagement", "Income", "Verhandlung", "Order Counters", "Spielerausscheidung", "Gleichzeitige Aktionswahl", "Sudden Death Ending", "Turn Order: Auction", "Variable Spielerfähigkeiten"] },
  { title: "Battlestar Galactica: The Board Game", imageUrl: "https://cf.geekdo-images.com/5Q2w2rFJiFI_uV89KP6ECg__original/img/MYuRAKLRAGlIQTph2XKWjzqT7sQ=/0x0/filters:format(jpeg)/pic354500.jpg", minPlayers: 3, maxPlayers: 6, playTimeMinutes: 180, weight: 3.3, description: "Battlestar Galactica: Das Brettspiel ist ein Spiel des Misstrauens, der Intrigen und des Überlebenskampfes. Basierend auf der Sci-Fi Channel-Serie versetzt Battlestar Galactica: The Board Game die Spieler in die Rolle eines von zehn ihrer Lieblingscharaktere aus der Serie. Jeder spielbare Charakter hat seine eigenen Fähigkeiten und Schwächen und muss alle zusammenarbeiten, damit die Menschheit eine Hoffnung auf Überleben hat. Allerdings stehen ein oder mehrere Spieler in jedem Spiel heimlich auf der Seite der Zylonen. Die Spieler müssen versuchen, den Verräter zu entlarven, während Treibstoffmangel, Lebensmittelkontaminationen und politische Unruhen die Flotte auseinanderzureißen drohen.\n\nNach dem zylonischen Angriff auf die Kolonien sind die zerschlagenen Überreste der Menschheit auf der Flucht und suchen ständig nach dem nächsten Wegweiser auf der Straße zur Erde. Sie sehen sich der Bedrohung durch einen Angriff der Zylonen von außen und Verrat und Krise von innen ausgesetzt. Die Menschheit muss zusammenarbeiten, wenn sie eine Hoffnung auf Überleben haben soll...aber wie können sie, wenn einer von ihnen tatsächlich ein zylonischer Agent sein kann?\n\nBattlestar Galactica: Das Brettspiel ist ein semi-kooperatives Spiel. Die Spieler wählen aus Piloten, politischen Führern, militärischen Führern oder Ingenieuren, um die Galactica zu besetzen. Sie erhalten zu Beginn des Spiels auch eine Treuekarte, um festzustellen, ob sie ein Mensch oder ein Zylon sind, zusammen mit einer Auswahl an Fertigkeitskarten, die auf ihren Charakterfähigkeiten basieren.\n\nDie Spieler können sich dann entweder auf der Galactica, auf der Colonial 1 oder in einer Viper bewegen und Aktionen ausführen. Sie müssen Fertigkeitskarten sammeln, zylonische Schiffe abwehren und", mechanics: ["Area Movement", "Kooperativ", "Würfelglück", "Handkartenmanagement", "Verdeckte Rollen", "Once-Per-Game Abilities", "Role Playing", "Semi-Cooperative Game", "Teamspiel", "Traitor Game", "Variable Spielerfähigkeiten", "Variable Set-up", "Abstimmung"] },
  { title: "Dead of Winter", imageUrl: null, minPlayers: 2, maxPlayers: 5, playTimeMinutes: 120, weight: 3.1, description: "Semi-kooperatives Survival-Spiel, in dem eine Gruppe Überlebender eine Zombie-Apokalypse bewältigen muss, während jeder Spieler auch geheime persönliche Ziele verfolgt.", mechanics: ["Kooperativ", "Verräter-Mechanik", "Ressourcenmanagement"] },
  { title: "Zombicide", imageUrl: "https://cf.geekdo-images.com/ZqjfzvtaTIT5FYp1D2CfKw__original/img/Arh3sc5cBx5FYg92vCvwtx-lKJw=/0x0/filters:format(jpeg)/pic1196191.jpg", minPlayers: 1, maxPlayers: 6, playTimeMinutes: 60, weight: 2.5, description: "Zombicide is a collaborative game in which players take the role of a survivor – each with unique abilities – and harness both their skills and the power of teamwork against the hordes of unthinking undead! Zombies are predictable, stupid but deadly, controlled by simple rules and a deck of cards. Unfortunately for you, there are a LOT more zombies than you have bullets.\n\nFind weapons, kill zombies. The more zombies you kill, the more skilled you get; the more skilled you get, the more zombies appear. The only way out is zombicide!\n\nPlay ten scenarios on different maps made from the included modular map tiles, download new scenarios from the designer's website, or create your own!\n\n\n     This is just a great game for zombie lovers!\n\n\nIntegrates with:\n\n    Zombicide Season 2: Prison Outbreak\n    Zombicide Season 3: Rue Morgue\n\n\nUPC 817009014248", mechanics: ["Aktionspunkte", "Kooperativ", "Würfelglück", "Bewegung auf Gitterfeld", "Handkartenmanagement", "Modularer Spielplan", "Spielerausscheidung", "Scenario / Mission / Campaign Game", "Handel", "Variable Spielerfähigkeiten"] },
  { title: "This War of Mine: The Board Game", imageUrl: "https://cf.geekdo-images.com/gQOQW7p1RWHzY54Lrs-_pA__original/img/PSC8BO2njNcBJhxvi0IV5Jb5hgo=/0x0/filters:format(jpeg)/pic3315915.jpg", minPlayers: 1, maxPlayers: 6, playTimeMinutes: 120, weight: 3.3, description: "This War Of Mine: The Board Game is the tabletop adaptation of the award-winning video game that pictures the drama of civilians trapped in a war-torn city. You will enter this experience as a group of civilians trapped in a besieged and conflict-ridden city, enduring many hardships that often test the essence of humanity. During your struggle as the survivors, you will experience dramas connected with making extremely difficult decisions and choices and have to face the consequences of your actions sooner or later.\n\nTWOM: The Board Game features a multiplayer experience for up to 6 players, as well as a solo variant. You will be able to personify one of the well-known characters from video game and face hundreds of new challenges and difficult choices. The boardgame significantly broadens the original game&rsquo;s universe and emphasizes the depth of plot, yet its main focus will be on human interactions driven by survival instinct and group decision-making.  TWOM: The Board Game is an instant play game, with no need for reading the manual before starting the adventure.\n\nDuring day time you will take shelter in a ruined tenement house, which you will care about and manage by: removing rubble, searching through various rooms (often behind barricaded doors), you will build beds, improvised workshops, stoves, tools, water filters, small animal traps, you will cultivate an improvised vegetable garden, fix the tenements&rsquo; shelled facilities, reinforce the security of your shelter and should winter come, you&rsquo;ll try to keep it warm.\n\nUpon nightfall your main duties will consist of guarding your shelter and what little possessions you can accumulate against bandits and raiders. Those in your group fit for such a task will use the cover of the night to carefully explore dozens of the ever-changing locations scattered throughout the dangerous city in search of all the things that a person needs to survive (materials, food, meds, equipment, etc.). On your way you will meet tens of characters, each with a unique story (residents of the locations you visit, thieves, bandits, soldiers, war victims, refugees, neighbors, traders and members of local communities), each encounter is a potential, unique adventure. To guide you through all these events you will have the special SCRIPTS mechanism, responsible for implementing the deep and complex story and a coherent plot (each game will be unique and different than the previous).\n\nYour goal is to survive until the cessation of war hostilities. However, survival itself will often prove not to be enough. The price each of you will decide to pay, might be too high in the final outcome. So the goal is really to survive in a way that will let you live on with the decisions you made. The EPILOGUES mechanism will kick in here.", mechanics: ["Aktionspunkte", "Kooperativ", "Würfelglück", "Events", "Bewegung auf Gitterfeld", "Narrative Choice / Paragraph", "Risikomanagement", "Role Playing", "Scenario / Mission / Campaign Game", "Simulation", "Solospiel", "Geschichten erzählen", "Variable Spielerfähigkeiten", "Arbeitereinsatz"] },
  { title: "Nemesis", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/8/83/Playing_board_game_-_Play_213_1681550178485.jpg", minPlayers: 1, maxPlayers: 5, playTimeMinutes: 120, weight: 3.9, description: "Science-Fiction-Horrorspiel auf einem havarierten Raumschiff, in dem Spieler mit versteckten Zielen kooperieren und gegen tödliche Alien-Kreaturen ums Überleben kämpfen.", mechanics: ["Semi-Kooperativ", "Verräter-Mechanik", "Bluffen"] },
  { title: "Mysterium", imageUrl: "https://upload.wikimedia.org/wikipedia/en/5/5e/Mysterium_board_game_cover.jpg", minPlayers: 2, maxPlayers: 7, playTimeMinutes: 42, weight: 1.9, description: "Kooperatives Krimispiel, bei dem ein stummer Geist seinen Mitspielern mit surrealen Traumkarten Hinweise gibt, um einen Mordfall aufzuklären.", mechanics: ["Kooperativ", "Deduktion", "Kartenmanagement"] },
  { title: "Sherlock Holmes Consulting Detective", imageUrl: "https://upload.wikimedia.org/wikipedia/en/3/34/Sherlock_Holmes_-_Consulting_Detective_Coverart.png", minPlayers: 1, maxPlayers: 8, playTimeMinutes: 90, weight: 2.1, description: "Kooperatives Ermittlungsspiel, bei dem Spieler als Detektive Londons Straßen und Zeitungsartikel durchsuchen, um knifflige Kriminalfälle zu lösen.", mechanics: ["Kooperativ", "Deduktion", "Storytelling"] },
  { title: "Pandemic Legacy: Season 1", imageUrl: "https://cf.geekdo-images.com/-Qer2BBPG7qGGDu6KcVDIw__original/img/PlzAH7swN1nsFxOXbfUvE3TkE5w=/0x0/filters:format(png)/pic2452831.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 60, weight: 2.8, description: "Pandemic Legacy is a co-operative campaign game, with an overarching story arc played through 12-24 sessions, depending on how well your group does at the game. At the beginning, the game starts in a very similar fashion as basic Pandemic, in which your team of disease-fighting specialists races against the clock to travel around the world, treating disease hot spots while researching cures for each of four plagues before they get out of hand.\n\nDuring a player's turn, they have four actions available, with which they may travel around in the world in various ways (sometimes needing to discard a card), build structures like research stations, treat diseases (removing one cube from the board; if all cubes of a color have been removed, the disease has been eradicated), trade cards with other players, or find a cure for a disease (requiring five cards of the same color to be discarded while at a research station). Each player has a unique role with special abilities to help them at these actions.\n\nAfter a player has taken their actions, they draw two cards. These cards can include epidemic cards, which will place new disease cubes on the board, and can lead to an outbreak, spreading disease cubes even further. Outbreaks additionally increase the panic level of a city, making that city more expensive to travel to.\n\nEach month in the game, you have two chances to achieve that month's objectives. If you succeed, you win and immediately move on to the next month. If you fail, you have a second chance, with more funding for beneficial event cards.\n\nDuring the campaign, new rules and components will be introduced. These will sometimes require you to permanently alter the components of the game; this includes writing on cards, ripping up cards, and placing permanent stickers on components. Your characters can gain new skills, or detrimental effects. A character can even be lost entirely, at which point it's no longer available for play.\n\nPart of the Pandemic series", mechanics: ["Aktionspunkte", "Kooperativ", "Handkartenmanagement", "Legacy-Spiel", "Multi-Use Cards", "Bewegung entlang von Punkten", "Scenario / Mission / Campaign Game", "Set Collection", "Tags", "Handel", "Variable Spielerfähigkeiten"] },
  { title: "Clank!: A Deck-Building Adventure", imageUrl: "https://cf.geekdo-images.com/DPjV1iI0ygo5Bl3XLNRiIg__original/img/cXqOdM3BLyIeRt0GP3M3V--gF1M=/0x0/filters:format(jpeg)/pic4449526.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 60, weight: 2.2, description: "Burgle your way to adventure in the deck-building board game Clank! Sneak into an angry dragon's mountain lair to steal precious artifacts. Delve deeper to find more valuable loot. Acquire cards for your deck and watch your thievish abilities grow. Be quick and be quiet. One false step and CLANK! Each careless sound draws the attention of the dragon, and each artifact stolen increases its rage. You can enjoy your plunder only if you make it out of the depths alive!\n\nClank! is a deck-building game. Each player has their own deck, and building yours up is part of playing the game. You start each of your turns with five cards in your hand, and you'll play them all in any order you choose. Most cards will generate resources, of which there are three different kinds:\n\n\n    Skill, which is used to acquire new cards for your deck.\n    Swords, which are used to fight the monsters that infest the dungeon.\n    Boots, which are used to move around the board.\n\n\nEvery time you acquire a new card, you put it face up in your discard pile. Whenever you need to draw a card and find your deck empty, you shuffle your discard pile and turn it face down to form a new deck. With each shuffle, your newest cards become part of a bigger and better deck! Each player starts with the same cards in their deck, but they&rsquo;ll acquire different cards during their turns. Because cards can do many different things, each player&rsquo;s deck (and strategy) will become more and more different as the game unfolds.\n\nDuring the game, you have two goals:\n\n    Retrieve an Artifact token and escape the dragon by returning to the place you started, outside of the dungeon.\n    Accumulate enough points with your Artifact and other loot to beat out your opponents and earn the title of Greatest Thief in the Realm!", mechanics: ["Aktionspunkte", "Deck, Bag, and Pool Building", "Delayed Purchase", "End Game Bonuses", "Events", "Movement Points", "Open Drafting", "Spielerausscheidung", "Bewegung entlang von Punkten", "Risikomanagement", "Take That", "Variable Set-up", "Victory Points as a Resource"] },
  { title: "Yokohama", imageUrl: "https://cf.geekdo-images.com/3edsEXwH21uaO8HXXdD1Dg__original/img/O-03BIpt7yhPbsffYjDwZc68zbQ=/0x0/filters:format(png)/pic7745916.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 90, weight: 3.3, description: "Once Yokohama was just a fishing village, but now at the beginning of the Meiji era it's becoming a harbor open to foreign countries and one of the leading trade cities of Japan. As a result, many Japanese products such as copper and raw silk are collected in Yokohama for export to other countries. At the same time, the city is starting to incorporate foreign technology and culture, with even the streets becoming more modernized. In the shadow of this development was the presence of many Yokohama merchants.\n\nIn YOKOHAMA, each player is a merchant in the Meiji period, trying to gain fame from a successful business, and to do so they need to build a store, broaden their sales channels, learn a variety of techniques, and (of course) respond to trade orders from abroad.", mechanics: ["Contracts", "End Game Bonuses", "Bewegung auf Gitterfeld", "Modularer Spielplan", "Streckenbau", "Set Collection", "Variable Set-up", "Arbeitereinsatz", "Worker Placement, Different Worker Types"] },
  { title: "Tokaido", imageUrl: "https://cf.geekdo-images.com/7kLkx3k3ovL8fP-2krPqwA__original/img/NWuaZkfygEeQ7nvi0Ih7_FW9jO0=/0x0/filters:format(jpeg)/pic8758132.jpg", minPlayers: 1, maxPlayers: 5, playTimeMinutes: 45, weight: 1.7, description: "In Tokaido, each player is a traveler crossing the \"East sea road\", one of the most magnificent roads of Japan. While traveling, you will meet people, taste fine meals, collect beautiful items, discover great panoramas, and visit temples and wild places but at the end of the day, when everyone has arrived at the end of the road you'll have to be the most initiated traveler – which means that you'll have to be the one who discovered the most interesting and varied things.\n\nThe potential action spaces in Tokaido are laid out on a linear track, with players advancing down this track to take actions. The player who is currently last on the track takes a turn by advancing forward on the track to their desired action and taking that action, so players must choose whether to advance slowly in order to get more turns, or to travel more rapidly to beat other players to their desired action spaces.\n\nThe action spaces allow a variety of actions that will score in different, but roughly equal, ways. Some action spaces allow players to collect money, while others offer players a way to spend that money to acquire points.  Other action spaces allow players to engage in various set collections that score points for assembling those sets.  Some action spaces simply award players points for stopping on them, or give the player a randomly determined action from all of the other types.\n\nAll of the actions in Tokaido are very simple, and combined with a unique graphic design, Tokaido offers players a peaceful zen mood in its play.", mechanics: ["End Game Bonuses", "Set Collection", "Solospiel", "Track Movement", "Turn Order: Time Track", "Variable Spielerfähigkeiten", "Arbeitereinsatz"] },
  { title: "Photosynthesis", imageUrl: "https://cf.geekdo-images.com/HhkYuVxMy-XrRCBWmZ78Eg__original/img/V6bgfuxV2jfmRbz9pJVyK01x6dI=/0x0/filters:format(jpeg)/pic3364832.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 60, weight: 2.3, description: "The sun shines brightly on the canopy of the forest, and the trees use this wonderful energy to grow and develop their beautiful foliage. Sow your crops wisely and the shadows of your growing trees could slow your opponents down, but don't forget that the sun revolves around the forest. Welcome to the world of Photosynthesis, the green strategy board game!", mechanics: ["Aktionspunkte", "Gebietskontrolle", "Bias", "End Game Bonuses", "Hexagon Grid", "Income", "Turn Order: Progressive"] },
  { title: "Cascadia", imageUrl: "https://cf.geekdo-images.com/MjeJZfulbsM1DSV3DrGJYA__original/img/B374C04Eip7fmQBGJzgiOTp-jyQ=/0x0/filters:format(jpeg)/pic5100691.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 45, weight: 1.8, description: "Cascadia is a puzzly tile-laying and token-drafting game featuring the habitats and wildlife of the Pacific Northwest.\n\nIn the game, you take turns building out your own terrain area and populating it with wildlife. You start with three hexagonal habitat tiles (with the five types of habitat in the game), and on a turn you choose a new habitat tile that's paired with a wildlife token, then place that tile next to your other ones and place the wildlife token on an appropriate habitat. (Each tile depicts 1-3 types of wildlife from the five types in the game, and you can place at most one token on a habitat.) Four tiles are on display, with each tile being paired at random with a wildlife token, so you must make the best of what's available — unless you have a nature token to spend so that you can pick your choice of each item.\n\nIdeally you can place habitat tiles to create matching terrain that reduces fragmentation and creates wildlife corridors, mostly because you score for the largest area of each type of habitat at game's end, with a bonus if your group is larger than each other player's. At the same time, you want to place wildlife tokens so that you can maximize the number of points scored by them, with the wildlife goals being determined at random by one of the four scoring cards for each type of wildlife. Maybe hawks want to be separate from other hawks, while foxes want lots of different animals surrounding them and bears want to be in pairs. Can you make it happen?", mechanics: ["Chaining", "End Game Bonuses", "Hexagon Grid", "Line of Sight", "Open Drafting", "Musterbildung", "Solospiel", "Plättchen platzieren", "Variable Set-up"] },
  { title: "Calico", imageUrl: "https://cf.geekdo-images.com/qGkU6XsF1448F_A4P8TY5Q__original/img/sm-qIkkIoKuYRUgkfP6kkXTm1QY=/0x0/filters:format(jpeg)/pic8124431.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 45, weight: 2.2, description: "Calico is a puzzly tile-laying game of quilts and cats.\n\nIn Calico, players compete to sew the coziest quilt as they collect and place patches of different colors and patterns. Each quilt has a particular pattern that must be followed, and players are also trying to create color and pattern combinations that are not only aesthetically pleasing, but also able to attract the cuddliest cats!\n\nTurns are simple. Select a single patch tile from your hand and sew it into your quilt, then draw another patch into your hand from the three available. If you are able to create a color group, you may sew a button onto your quilt. If you are able to create a pattern combination that is attractive to any of the cats, it will come over and curl up on your quilt! At the end of the game, you score points for buttons, cats, and how well you were able to complete your unique quilt pattern.\n\n—description from the publisher", mechanics: ["Enclosure", "End Game Bonuses", "Grid Coverage", "Hexagon Grid", "Open Drafting", "Musterbildung", "Set Collection", "Solospiel", "Plättchen platzieren"] },
  { title: "Parks", imageUrl: null, minPlayers: 1, maxPlayers: 5, playTimeMinutes: 60, weight: 2, description: "Wanderspiel durch die US-Nationalparks, bei dem Spieler auf einem gemeinsamen Pfad vorrücken, Ressourcen sammeln und Erinnerungsstücke einlösen.", mechanics: ["Worker Placement", "Set Collection", "Kartenmanagement"] },
  { title: "Patchwork", imageUrl: null, minPlayers: 2, maxPlayers: 2, playTimeMinutes: 30, weight: 1.6, description: "Zwei-Personen-Puzzlespiel, bei dem Spieler Stoffstücke effizient auf ihr eigenes Quilt-Brett legen, um Knöpfe zu sammeln und Lücken zu vermeiden.", mechanics: ["Puzzle", "Legespiel", "Tetris-Mechanik"] },
  { title: "Kingdomino", imageUrl: "https://cf.geekdo-images.com/c0m3gwZTcfKoLI63ASio8g__original/img/HT6NQPT0cSFcZXjSewtjTO_NBAE=/0x0/filters:format(png)/pic8443569.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 25, weight: 1.2, description: "Kingdomino is a tile-laying game in which players take the role of monarchs expanding their kingdoms by claiming and arranging lands. Over the course of the game, players build a compact kingdom from forests, lakes, wheat fields, grasslands, swamps, and mines, carefully connecting matching terrain types while planning for valuable crown symbols that increase the prestige of their territories.\n\nEach round, players place the domino they selected on the previous turn, following placement rules that require at least one matching terrain connection (or connection to the starting castle tile). After placing a domino, they choose a new one from the available row for a future turn. The order in which dominoes are chosen also determines the turn order for the next round, creating a balance between claiming the most desirable tiles and securing an earlier turn.\n\nAt the end of the game, players score each connected territory by multiplying its number of squares by the number of crowns within that territory. Territories without crowns score no points. The player with the highest total score wins, with ties broken first by the size of the largest territory, then by the total number of crowns.\n\n—description from the publisher", mechanics: ["Enclosure", "Matching", "Open Drafting", "Plättchen platzieren", "Turn Order: Claim Action"] },
  { title: "Queendomino", imageUrl: "https://cf.geekdo-images.com/_6VtTmeI4e7cORxFWRC7Og__original/img/Uem_ewrSp4uzwG19S2CSnHwrmEU=/0x0/filters:format(png)/pic3672901.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 25, weight: 2.1, description: "Description from the publisher:\n\nBuild up the most prestigious kingdom by claiming wheat fields, forests, lakes, grazing grounds, marshes, and mountains. Your knights will bring you riches in the form of coins — and if you make sure to expand the towns on your lands, you will make new buildings appear, giving you opportunities for new strategies. You may win the Queen's favors ... but always be aware of the dragon!\n\nQueendomino is a game completely independent from Kingdomino, while offering a choice of more complex challenges. Two to four players can play Queendomino independently, but also in connection with Kingdomino, allowing for games with 7x7 grids for four players, or for up to six players if you stick to 5x5 grids.", mechanics: ["Enclosure", "Market", "Open Drafting", "Musterbildung", "Plättchen platzieren", "Turn Order: Claim Action"] },
  { title: "Azul: Summer Pavilion", imageUrl: "https://cf.geekdo-images.com/843kZ6WR0HfyXWEybA6L7A__original/img/VtYGvhy_YCSw14FpV8FGzv0eMe4=/0x0/filters:format(jpeg)/pic4930887.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 45, weight: 2.1, description: "Um die Wende des 16. Jahrhunderts beauftragte König Manuel I. Portugals größte Handwerker mit dem Bau grandioser Gebäude. Nach der Fertigstellung der Paläste von Evora und Sintra versuchte der König, einen Sommerpavillon zu bauen, um die berühmtesten Mitglieder der königlichen Familie zu ehren. Diese Konstruktion war für die talentiertesten Handwerker gedacht — deren Fähigkeiten dem Glanz entsprechen, den die königliche Familie verdient. Leider starb König Manuel I., bevor der Bau überhaupt begann.\n\nIn Azul: Summer Pavilion kehren die Spieler nach Portugal zurück, um die Aufgabe zu erfüllen, die nie begonnen hat. Als Meisterhandwerker müssen Sie die besten Materialien verwenden, um den Sommerpavillon zu schaffen, während Sie sorgfältig vermeiden, Vorräte zu verschwenden. Nur die Besten werden sich der Herausforderung stellen, die portugiesische Königsfamilie zu ehren.\n\nAzul: Der Sommerpavillon dauert sechs Runden. In jeder Runde ziehen die Spieler Steine und legen sie dann auf ihr individuelles Spielerbrett, um Punkte zu sammeln. Jede der sechs Farben der Steine ist während einer der Runden ein Wild-Symbol.\n\nZiehe zu Beginn jeder Runde zufällig Steine aus dem Beutel, um jede der fünf, sieben oder neun Fabriken mit jeweils vier Steinen zu füllen. Zeichne nach Bedarf Kacheln, um die zehn Vorratsräume auf dem zentralen Bewertungsbrett wieder aufzufüllen. Die Spieler ziehen dann abwechselnd Steine. Du kannst wählen, alle Steine einer nicht wilden Farbe in einer Fabrik zu nehmen und sie neben deinem Brett zu platzieren. Wenn sich irgendwelche wilden Steine in dieser Fabrik befinden, musst du einen von ihnen nehmen. Legen Sie alle verbleibenden Kacheln in die Mitte des Tisches. Alternativ können Sie alle Kacheln", mechanics: ["End Game Bonuses", "Open Drafting", "Musterbildung", "Set Collection", "Plättchen platzieren", "Turn Order: Claim Action"] },
  { title: "Azul: Stained Glass of Sintra", imageUrl: "https://cf.geekdo-images.com/RrYR1xB8H7D1B5GwNV8jgQ__original/img/unI8OEWp9Fdv3D_dLahPPdLG1qc=/0x0/filters:format(jpeg)/pic4212417.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 45, weight: 2, description: "Azul: Buntglas von Sintra fordert die Spieler auf, sorgfältig Glasscheiben auszuwählen, um ihre Fenster zu vervollständigen, ohne dabei Vorräte zu beschädigen oder zu verschwenden. Die Fensterscheiben sind doppelseitig und bieten den Spielern ein dynamisches Spielerbrett, das eine nahezu unendliche Variabilität bietet!\n\nDas Gameplay ist ähnlich wie bei Azul.  Die Spieler ziehen farbige Glasplättchen auf ihr Spielbrett. Später in der Runde erhalten die Spieler Punkte, je nachdem, wie sie ihre Fensterscheiben-Teile platziert haben. Zusätzliche Punkte werden für bestimmte Muster und abschließende Sätze erzielt.  Am Ende jeder Runde gibt es auch eine neue Farbbonus-Mechanik für eine zusätzliche Bewertungsstrategie. Das Spiel endet nach 6 Runden. Der Spieler mit den meisten Punkten am Ende des Spiels gewinnt.\n\nAzul: Buntglas von Sintra hat neue Komponenten, darunter lichtdurchlässige Fensterscheibenteile, einen Turm für weggeworfene Glasscheiben sowie doppelseitige Spielertafeln und Fensterscheiben.\n\n-Beschreibung des Verlages", mechanics: ["End Game Bonuses", "Modularer Spielplan", "Open Drafting", "Musterbildung", "Set Collection", "Plättchen platzieren", "Turn Order: Claim Action"] },
  { title: "Sagrada", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/4/4e/A_nearly_complete_window_in_Sagrada.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 30, weight: 1.9, description: "Würfel-Legespiel, bei dem Spieler bunte Würfel nach Farb- und Wertregeln anordnen, um ein Kirchenfenster im Stil der Sagrada Família zu gestalten.", mechanics: ["Legespiel", "Würfelglück", "Drafting"] },
  { title: "Santorini", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/e/ec/Santorini_game_render.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 20, weight: 1.7, description: "Abstraktes Bauspiel, bei dem Spieler Türme errichten und ihre Figuren darauf bewegen, um als Erste die dritte Ebene eines Gebäudes zu erreichen.", mechanics: ["Abstraktes Spiel", "Bauen", "Taktik"] },
  { title: "Onitama", imageUrl: "https://cf.geekdo-images.com/GJKuOCy5HGAYgVH_Rei5mA__original/img/oRsIxp72iv58128KFdqvjG6Gz64=/0x0/filters:format(jpeg)/pic7070194.jpg", minPlayers: 2, maxPlayers: 2, playTimeMinutes: 20, weight: 1.7, description: "Onitama is a two-player, perfect information abstract game with a random starting set-up. On a 5x5 board, both players start with five pawns on their side, with the main pawn in the middle.\n\nEach player has two open cards that each display a possible move for any of her pieces. There is a fifth card that cannot be used by either player. On a player's turn, she chooses one of her cards, moves one of her pieces according to the chosen card, then replaces the card she used with the fifth card. The other player then chooses one of his cards, moves accordingly, and exchanges that card with this fifth card — which is, of course, the card the first player just used.\n\nMoving onto one of the opponent's pawns removes that pawn from the game. Taking the opponent's main pawn, or moving your main pawn into your opponent's main pawn's starting space, wins you the game.", mechanics: ["Bewegung auf Gitterfeld", "Handkartenmanagement", "Pattern Movement", "Square Grid", "Static Capture"] },
  { title: "Hive", imageUrl: "https://cf.geekdo-images.com/fQe85tsBZoH6ibPnm1k1UA__original/img/eqUVrCJKcMBGBhw4Gfc9_9JabYE=/0x0/filters:format(jpeg)/pic791151.jpg", minPlayers: 2, maxPlayers: 2, playTimeMinutes: 20, weight: 2.3, description: "Hive is a strategic game for two players that is not restricted by a board and can be played anywhere on any flat surface. Hive is made up of twenty two pieces, eleven black and eleven white, resembling a variety of creatures each with a unique way of moving.\n\nWith no setting up to do, the game begins when the first piece is placed down. As the subsequent pieces are placed this forms a pattern that becomes the playing surface (the pieces themselves become the board). Unlike other such games, the pieces are never eliminated and not all have to be played. The object of the game is to totally surround your opponent's queen, while at the same time trying to block your opponent from doing likewise to your queen. The player to totally surround his opponent's queen wins the game.\n\n&bull;&bull;&bull;\n\nHive FAQ - please read before posting questions in the forum!", mechanics: ["Enclosure", "Bewegung auf Gitterfeld", "Hexagon Grid", "Pattern Movement", "Pieces as Map", "Three Dimensional Movement", "Plättchen platzieren"] },

  // Batch 4
  { title: "Ingenious", imageUrl: "https://cf.geekdo-images.com/_qEEUfI9DxtfVxYCerAvsQ__original/img/2s1PbJDhGgIHkdF_-_S3dmcTW_8=/0x0/filters:format(jpeg)/pic7633115.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 45, weight: 1.9, description: "In Ingenious, a.k.a. Einfach Genial, players take turns placing colored domino-style tiles on a game board, scoring for each line of colored symbols that they enlarge. The trick, however, is that a player's score is equal to their worst-scoring color, not their best, so they need to score for all colors instead of specializing in only one or two.\n\nIn more detail, the game includes 120 domino-style tiles, each consisting of two conjoined hexes; each hex has one of six colors in it, with most tiles having different-colored hexes. Each player has a rack with six tiles on it, and on a turn a player places one tile from their rack onto two hexes of the game board. For each hex on this tile, they score one point in that color for each hex of the same color that lies adjacent to it and each hex in a straight line from it. If a player brings the score of a color to 18, they immediately take another turn. At the end of their turn, they refill their rack to six tiles. (Before refilling their rack, if they have no tiles on it that contain hexes in their lowest-scoring color, they can discard all of their tiles, then draw six new tiles from the bag.)\n\nWhen no more tiles can be placed on the game board or when one player scores 18 in each color, the game ends. Players then compare their lowest scores, and whoever has the highest low score wins.\n\nIngenious includes rules for solitaire and team play; in the latter case, two teams of two play, with each player not being able to see their partner's tiles and teams keeping a combined score that maxes out at 36 instead of 18.", mechanics: ["Handkartenmanagement", "Hexagon Grid", "Highest-Lowest Scoring", "Musterbildung", "Teamspiel", "Plättchen platzieren"] },
  { title: "Qwirkle", imageUrl: "https://cf.geekdo-images.com/k7zHj8j_a6uUAtXUt5Fvuw__original/img/FNi6yap-UmVKX8X6rj0A_YW2q8Y=/0x0/filters:format(jpeg)/pic309353.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 45, weight: 1.6, description: "The abstract game of Qwirkle consists of 108 wooden blocks with six different shapes in six different colors. There is no board, players simply use an available flat surface.\n\nPlayers begin the game with six blocks. The start player places blocks of a single matching attribute (color or shape but not both) on the table. Thereafter, a player adds blocks adjacent to at least one previously played block. The blocks must all be played in a line and match, without duplicates, either the color or shape of the previous block.\n\nPlayers score one point for each block played plus all blocks adjacent. It is possible for a block to score in more than one direction. If a player completes a line containing all six shapes or colors, an additional six points are scored. The player then refills his hand to six blocks.\n\nThe game ends when the draw bag is depleted and one player plays all of his remaining blocks, earning a six point bonus. The player with the high score wins.", mechanics: ["Handkartenmanagement", "Musterbildung", "Square Grid", "Plättchen platzieren"] },
  { title: "Carcassonne: Hunters and Gatherers", imageUrl: "https://cf.geekdo-images.com/NSD4L9c-rY5OOlJYFlQ2Wg__original/img/pBCT2KKOuuSrj4OI5gybXzySnRo=/0x0/filters:format(png)/pic5647234.png", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 40, weight: 1.9, description: "Carcassonne: Hunters and Gatherers is a standalone game in the Carcassonne series set in the stone age.\n\nAs in other Carcassonne games, players take turns placing tiles to create the landscape and placing meeples to score points from the map they're creating. The player with the most points at the end of the game wins.\n\nInstead of cities, roads, and farms, Carcassonne: Hunters and Gatherers has forests, rivers, lakes, and meadows. Players' meeples can represent hunters (when placed in the meadows), gatherers (in a forest), or fishermen (on a river segment). They also have huts, which can be placed on rivers or lakes to get fish from the entire river system.\n\nIt includes many of the familiar mechanics from Carcassonne with a few new rules, including:\n- A player who completes a forest with a gold nugget in it gets to immediately draw and place 1 of 12 bonus (menhir) tiles.\n- A meadow is worth 2 points for every animal in it, except tigers, which negate certain other animals.\n- A river segment is worth the number of tiles in the segment plus the number of fish in the lakes at each end.\n- A fishing hut scores at the end of the game and is worth the number of fish in all the lakes connected by rivers.\n\nThe Devir edition includes (the relevant part of) the Carcassonne: King & Scout expansion\n\nIn the 2020 edition \n- Some of The Scout special tiles are transformed into menhir tiles of which there are more now.\n- A deer scores 1 point, an aurochs 2 points and a mammoth 3 points on meadows. \n- Rivers score for fish in the river segments as well, not only the fish in the lakes at each end. Fishing huts likewise.\n- Players each get 3 huts instead of just 2.", mechanics: ["Gebietskontrolle", "Enclosure", "Kill Steal", "Map Addition", "Musterbildung", "Square Grid", "Plättchen platzieren"] },
  { title: "Catan: Cities & Knights", imageUrl: "https://cf.geekdo-images.com/CQHOCJI6EFUUsQiGXS9oHg__original/img/o2_Y3Gog9AWWCnEN8MJTuyteZHc=/0x0/filters:format(jpeg)/pic8828016.jpg", minPlayers: 3, maxPlayers: 4, playTimeMinutes: 150, weight: 2.9, description: "Adds several new aspects to Settlers of Catan but the two major ones are creating knights to protect the land from invading barbarians and building city improvements that confer benefits upon that city's owner. Adds tactical complexity to the game and game length.\n\nBelongs to the Catan Series.\n\nThe game changes the base game in three main ways:\n\nFirst, there are 3 new commodities in the game, distinct from resources - paper, cloth, and coins, which can be acquired from Forest, Meadow, and Mountain spaces, respectively. Cities that would normally produce two of one of those resources instead produce 1 resource and 1 of the corresponding commodity. (To make commodities easier to obtain, each player starts the game with 1 city and 1 settlement on the board.) These commodities allow players to build city improvements that confer various advantages and eventually points.\n\nSecond, the deck of development cards is replaced by three different decks, each corresponding to one of the commodities. Building city improvements gives players a chance to draw these cards with every roll of the dice. Building more improvements will increase these chances, but cards cannot be bought directly in any way. These cards are similar to the development cards in the base game, but with a wider range of effects. (Some cards are balanced better as well - the new Resource Monopoly card, for example, can take no more than 2 of the named resource from any one player.)\n\nFinally, players can also build knights on the island along their network of roads. These knights can be used to claim certain intersections and move the Robber (taking the place of Soldier cards), but are also used to defend the island from periodic barbarian attacks. If the island is successfully defended, the player(s) with the most knights are rewarded. If not, the player(s) with the fewest knights each have a city downgraded to a settlement.", mechanics: ["Würfelglück", "Handkartenmanagement", "Merkfähigkeit", "Modularer Spielplan", "Streckenbau", "Handel"] },
  { title: "Catan: Seafarers", imageUrl: "https://cf.geekdo-images.com/v8ll_1CxVGP-KN-NqkoQsg__original/img/HQqjNMRHo7Nxuoa72J5yyIq-NCY=/0x0/filters:format(jpeg)/pic8828019.jpg", minPlayers: 3, maxPlayers: 4, playTimeMinutes: 90, weight: 2.4, description: "This is an expansion for CATAN. Players can build shipping lanes, which are very similar to roads. Additionally, the game comes with many different water-hex-heavy variant setups. The English version (CATAN Studio) should only be used with the English base game, instead of the German one (Kosmos), because of matching components. The Kosmos German version should only be used with the German base game. Additionally, several different editions exist; 5th edition is the most recent. Editions should only be used with same edition, otherwise the purchase of adapter kit is required.\n\nPart of the Catan Series.\n\nThis game requires CATAN.  Ideally, using the same publisher and edition of the game.", mechanics: ["Würfelglück", "Handkartenmanagement", "Merkfähigkeit", "Modularer Spielplan", "Streckenbau", "Handel"] },
  { title: "Risk", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/8/8c/Amsterdam_-_Risk_players_-_1136_%28cropped%29.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 120, weight: 2.2, description: "Klassisches Kriegs- und Eroberungsspiel, bei dem Spieler mit Armeen auf einer Weltkarte um Territorien kämpfen und Kontinente erobern.", mechanics: ["Gebietskontrolle", "Würfelglück", "Bluffen"] },
  { title: "Monopoly", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/7/78/Monopoly_board_on_white_bg.jpg", minPlayers: 2, maxPlayers: 8, playTimeMinutes: 120, weight: 1.7, description: "Bekanntes Wirtschaftsspiel, bei dem Spieler Straßen und Grundstücke kaufen, Häuser bauen und Miete kassieren, um ihre Gegner in den Bankrott zu treiben.", mechanics: ["Würfelglück", "Handel", "Wirtschaftssimulation"] },
  { title: "Cluedo", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/4/4c/Cluedo_Clue_pack_logo.png", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 45, weight: 1.9, description: "Detektiv-Gesellschaftsspiel, bei dem die Spieler durch Ausschlussverfahren herausfinden müssen, wer mit welcher Waffe in welchem Raum den Mord begangen hat.", mechanics: ["Deduktion", "Bluffen", "Würfelglück"] },
  { title: "Scrabble", imageUrl: "https://cf.geekdo-images.com/mVmmntn2oQd0PfFrWBvwIQ__original/img/11jrKPiOVTNl5NwX83KGtTZEq40=/0x0/filters:format(jpeg)/pic404651.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 90, weight: 2.1, description: "In this classic word game, players use their seven drawn letter-tiles to form words on the gameboard. Each word laid out earns points based on the commonality of the letters used, with certain board spaces giving bonuses.  But a word can only be played if it uses at least one already-played tile or adds to an already-played word.  This leads to slightly tactical play, as potential words are rejected because they would give an opponent too much access to the better bonus spaces.\n\nSkip-a-cross was licensed by Selchow & Righter and manufactured by Cadaco. Both games have identical rules but Skip-a-cross has tiles and racks made of cardboard instead of wood. The game was also published because not enough Scrabble games were manufactured to meet the demand.", mechanics: ["End Game Bonuses", "Handkartenmanagement", "Spelling", "Square Grid", "Plättchen platzieren"] },
  { title: "Trivial Pursuit", imageUrl: "https://cf.geekdo-images.com/Z13eXn3ddB2wsW9bmBSq9g__original/img/rH-_V-sC2nwl1My7wnOVNAK5Ebc=/0x0/filters:format(jpeg)/pic9613440.jpg", minPlayers: 1, maxPlayers: 6, playTimeMinutes: 45, weight: 0, description: "Entertain your brain with fascinating facts in this Trivial Pursuit game - updated with exciting fresh features!\n\nIncludes 1,200 intriguing trivia questions in 6 classic categories.\n\nNow players have even more chances to earn wedges with fresh spaces that let them choose from 2 questions, select ANY category, beat others to All-Play answers, or steal a question an opponent missed!\n\nPlay individually or in teams, and be the first player or team to collect 6 different color wedges and answer the final question correctly to win!\n\nOr play everyone versus the deck and collect a card for every correctly guessed answer to earn a rank!\n\n—description from the publisher", mechanics: ["Kooperativ", "Questions and Answers", "Würfeln und Ziehen", "Set Collection", "Solospiel", "Teamspiel"] },
  { title: "Uno", imageUrl: "https://cf.geekdo-images.com/-DHiHBBSnvaLu0Do8CIykQ__original/img/fRfoyWezpQsumExNKVxf1cwtJfg=/0x0/filters:format(jpeg)/pic8204165.jpg", minPlayers: 2, maxPlayers: 10, playTimeMinutes: 30, weight: 1.1, description: "Players race to empty their hands and catch opposing players with cards left in theirs, which score points. In turns, players attempt to play a card by matching its color, number, or word to the topmost card on the discard pile. If unable to play, players draw a card from the draw pile, and if still unable to play, they pass their turn. Wild and special cards spice things up a bit.\n\nUNO is a commercial version of Crazy Eights, a public domain card game played with a standard deck of playing cards.\n\nThis entry includes all themed versions of UNO that do not include new cards.", mechanics: ["Handkartenmanagement", "Lose a Turn", "Matching", "Take That"] },
  { title: "Skip-Bo", imageUrl: "https://cf.geekdo-images.com/aaUJua2zRXA6lqbVbNcBGg__original/img/dWxG7nwxGBijXQ1849TFwtym06I=/0x0/filters:format(jpeg)/pic8204244.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 20, weight: 1.2, description: "Each player is dealt a stockpile of 30 cards. The winner will be whoever manages to empty their stockpile first. Cards are played onto four shared building piles in numerical sequence from 1 to 12. On each turn, a player draws until they have five cards in their hand, and then plays cards from: their hand, a top card of their discard piles, or their stockpile. At the end of their turn, a player must discard onto one of their four personal discard piles. Strategy involves the organizing of cards into the discard piles, care in not setting up the next players for good plays, knowing when to play from which option, and especially the timing of playing a valuable \"Skip-bo\" wildcard.\n\nSkip-bo is based on Traditional Card Games: Spite and Malice.", mechanics: ["Handkartenmanagement"] },
  { title: "Phase 10", imageUrl: "https://cf.geekdo-images.com/jvHGs95ShI8VEhDBdxKs6w__original/img/xzQGx7DR_4w0co_tte0KhCqZqcA=/0x0/filters:format(png)/pic7621070.png", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 45, weight: 1.2, description: "A rummy-type card game where players compete to be the first to finish completing all ten phases.  Phases include collecting runs of numbers, collecting certain number of a given color cards, etc.  The first player to finish completing the 10th phase wins.  In case of ties, the player with the fewest number of points wins.", mechanics: ["Melding and Splaying", "Set Collection"] },
  { title: "Rummikub", imageUrl: "https://cf.geekdo-images.com/LeaLDlTTmeN639MfuflcMw__original/img/fusGQFpm4srwqhM8CDlEDzh0NyQ=/0x0/filters:format(jpeg)/pic2286966.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 60, weight: 1.7, description: "Rummikub is similar to several central European card games which are played with two decks of playing cards, including Machiavelli and Vatikan. Ephraim Hertzano invented the tile game Rummikub in the 1940s when card-playing was outlawed under the Communist regime. After World War II, Hertzano immigrated to British Mandate of Palestine (now Israel) and developed the first sets with his family. Over the years, the Hertzano family licensed it to other countries and Rummikub became Israel's best-selling export game.\n\nHertzano's Official Rummikub Book, published in 1978, describes three different versions of the game: American, Sabra, and International. Modern Rummikub sets include only the Sabra version rules, with no mention of the others, and there are variations in the rules between publishers.\n\nIn Turkey, the game is known as Okey and is widely played by families at gatherings or at local cafes.\n\nLike Rummy that you play with cards, you try to get rid of all your tiles by forming numbers into runs of 3 tiles or more, or 3 to 4 of a kind. The colors of the numbers on the tiles are like card suits. This game may start rather uneventfully, but when the players start putting more and more tiles in play, the options for your upcoming turns can become more complex, challenging, and exciting (from areyougame.com).", mechanics: ["Set Collection", "Plättchen platzieren"] },
  { title: "Yahtzee", imageUrl: "https://cf.geekdo-images.com/dp-pJkUemCjhrwi9QItrPA__original/img/eeYPdva8ti4Hi2PYxkTLRPrtfKk=/0x0/filters:format(jpeg)/pic378237.jpg", minPlayers: 2, maxPlayers: 10, playTimeMinutes: 30, weight: 1.2, description: "Yahtzee is a classic dice game played with 5 dice.  Each player's turn consists of rolling the dice up to 3 times in hope of making 1 of 13 categories.  Examples of categories are 3 of a kind, 4 of a kind, straight, full house, etc.  Each player tries to fill in a score for each category, but this is not always possible.  When all players have entered a score or a zero for all 13 categories, the game ends and total scores are compared.\n\nThe traditional (public domain) game Yacht predates the trademarked game, and has slightly different scoring.\n\nThere are four basic scoring difference between the tradition game Yacht and Yahtzee.  They are:  1) Yacht has no Three of a Kind category, 2) there are no bonuses in Yacht, 3) there are no Joker rules in Yacht, and 4) the Full House category is scored as the sum of the dice.  The other scoring rules are identical between the two games.\n\nTravel versions of the game use a device that keeps the dice captured within compartments of a plastic box and allows players to \"lock\" a particular die between rolls.", mechanics: ["Würfelglück", "Paper-and-Pencil", "Risikomanagement", "Re-rolling and Locking", "Set Collection"] },
  { title: "Taboo", imageUrl: "https://cf.geekdo-images.com/TdOB9V-wTf0LenXk8QWo-A__original/img/mhYaJYFxGrVZaP7ZL08ZuFJj5Ak=/0x0/filters:format(jpeg)/pic8377520.jpg", minPlayers: 4, maxPlayers: 10, playTimeMinutes: 20, weight: 1.2, description: "In the party game Taboo, you're trying to give clues to your teammates so that they'll guess a particular word, but you can't say just anything you like. Some clues are off limits!\n\nWhen you're the active player, hold the deck of cards so that you and the opposing team can see the top card. At the top of the card is the word your teammate must say to score the card, and you can anything you want to help them figure out what to guess other than the word itself (duh!) or the five words/phrases listed on the bottom of the card.\n\nFor example, can you get your teammates to say \"bacon\" without saying \"pig\", \"eggs\", \"breakfast\", \"sausage\", or \"eat\"? If you do, you score the card, then move on to the next card, trying to guess as many cards as possible before time runs out. However, if you say a taboo word (or make gestures), the opposing team will buzz a buzzer and score the card themselves.\n\nHow well can you describe things without breaking the taboo?", mechanics: ["Communication Limits", "Teamspiel"] },
  { title: "Pictionary", imageUrl: "https://cf.geekdo-images.com/YfUxodD7JSqYitxvjXB69Q__original/img/YRJAlLzkxMuJHVPsdnBLNFpoODA=/0x0/filters:format(png)/pic5147022.png", minPlayers: 3, maxPlayers: 16, playTimeMinutes: 90, weight: 1.2, description: "Pictionary is a fast-paced party game of sketching and guessing, often compared to Charades, but with drawings instead of physical acting. Players divide into teams and take turns drawing clues from prompt cards while their teammates race against the timer to guess the correct answer.\n\nSome rounds are designated &ldquo;All Play,&rdquo; where multiple teams compete simultaneously to guess the same prompt, while other rounds feature solo team turns. Answers range in difficulty, and while artistic skill can help, imagination, communication, and quick thinking matter far more.\n\nA game board is used to track progress, adding a light strategic element to the competitive fun. First released in 1985, Pictionary became a massive hit and has remained a staple of the party game genre ever since.", mechanics: ["Drawing", "Würfeln und Ziehen", "Teamspiel"] },
  { title: "Codenames: Duet", imageUrl: "https://cf.geekdo-images.com/VG31TvBpKngZ8ztV-N4Dcg__original/img/w-FZ84fzPZSNCI1HtrsTOfLT2B4=/0x0/filters:format(png)/pic8911183.png", minPlayers: 2, maxPlayers: 2, playTimeMinutes: 30, weight: 1.4, description: "Codenames Duet keeps the basic elements of Codenames — give one-word clues to try to get someone to identify your agents among those on the table — but now you're working together as a team to find all of your agents. (Why you don't already know who your agents are is a question that Congressional investigators will get on your back about later!)\n\nTo set up play, lay out 25 word cards in a 5&times;5 grid. Place a key card in the holder so that each player sees one side of the card. Each player sees a 5&times;5 grid on the card, with nine of the squares colored green (representing your agents) and three squares colored black (representing assassins). Three of the nine squares on each side are also green on the other side, one assassin is black on both sides, one is green on the other side and the other is an innocent bystander on the other side.\n\nCollectively, you need to reveal all fifteen agents — without revealing an assassin — before time runs out in order to win the game. Either player can decide to give the first one-word clue to the other player, along with a number. Whoever receives the clue places a finger on a card to identify that agent. If correct, they can attempt to identify another one. If they identify a bystander, then their guessing time ends. If they identify an assassin, you both lose! Unlike regular Codenames, they can keep guessing as long as they keep identifying an agent each time; this is useful for going back to previous clues and finding ones they missed earlier. After the first clue is given, players alternate giving clues.", mechanics: ["Communication Limits", "Kooperativ", "Merkfähigkeit"] },
  { title: "Decrypto", imageUrl: null, minPlayers: 3, maxPlayers: 8, playTimeMinutes: 45, weight: 1.9, description: "Team-Spionagespiel, bei dem Spieler codierte Hinweise geben, damit das eigene Team Zahlencodes entschlüsselt, während das gegnerische Team versucht mitzuhören.", mechanics: ["Wortassoziation", "Bluffen", "Teamspiel"] },
  { title: "Wavelength", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/b/b0/The_Wavelength_party_game_box_and_elements_01.jpg", minPlayers: 2, maxPlayers: 12, playTimeMinutes: 45, weight: 1.4, description: "Partyspiel, bei dem ein Spieler versucht, sein Team über einen verdeckten Zeiger auf einer Skala zwischen zwei Gegensätzen zu lenken, indem er passende Hinweise gibt.", mechanics: ["Kommunikation", "Teamspiel", "Assoziation"] },
  { title: "The Mind", imageUrl: "https://cf.geekdo-images.com/q_JGK291hrhnhiRB0667oA__original/img/8VjZEG278faO9JZwzce3v3EKssI=/0x0/filters:format(png)/pic3979766.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 20, weight: 1.1, description: "The Mind is more than just a game. It's an experiment, a journey, a team experience in which you can't exchange information, yet will become one to defeat all the levels of the game.\n\nIn more detail, the deck contains cards numbered 1-100, and during the game you try to complete 12, 10, or 8 levels of play with 2, 3, or 4 players. In a level, each player receives a hand of cards equal to the number of the level: one card in level 1, two cards in level 2, etc. Collectively you must play these cards into the center of the table on a single discard pile in ascending order but you cannot communicate with one another in any way as to which cards you hold. You simply stare into one another's eyes, and when you feel the time is right, you play your lowest card. If no one holds a card lower than what you played, great, the game continues! If someone did, all players discard face up all cards lower than what you played, and you lose one life.\n\nYou start the game with a number of lives equal to the number of players. Lose all your lives, and you lose the game. You start with one shuriken as well, and if everyone wants to use a shuriken, each player discards their lowest card face up, giving everyone information and getting you closer to completing the level. As you complete levels, you might receive a reward of a shuriken or an extra life. Complete all the levels, and you win!\n\nFor an extra challenge, play The Mind in extreme mode with all played cards going onto the stack face down. You don't look at the cards played until the end of a level, losing lives at that time for cards played out of order.", mechanics: ["Communication Limits", "Kooperativ", "Handkartenmanagement"] },
  { title: "The Crew: The Quest for Planet Nine", imageUrl: "https://cf.geekdo-images.com/98LnQShydr11OBKS46xY-Q__original/img/Q-ZkgnuBu9OTBr7J3qnqPjqamAE=/0x0/filters:format(jpeg)/pic5687013.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 20, weight: 2, description: "In the co-operative trick-taking game The Crew: The Quest for Planet Nine, the players set out as astronauts on an uncertain space adventure. What are the rumors regarding the unknown planet about? The eventful journey through space extends over 50 exciting missions. But this game can only be defeated by meeting common individual tasks of each player. In order to meet the varied challenges communication is essential in the team. But this is more difficult than expected in space.\n\nWith each mission the game becomes more difficult. After each mission the game can be paused and continued later. During each mission it is not the number of tricks but the right tricks at the right time that count.\n\nThe team completes a mission only if every single player is successful in fulfilling their tasks.\n\nThe game comes with 50 missions, with three additional missions published in spielbox 2/2020.", mechanics: ["Communication Limits", "Kooperativ", "Handkartenmanagement", "Scenario / Mission / Campaign Game", "Trick-taking"] },
  { title: "Hanabi", imageUrl: "https://cf.geekdo-images.com/JDVksMwfcqoem1k_xtZrOA__original/img/5vNHZiTEhK4aRDuGXv5KImp9cmQ=/0x0/filters:format(jpeg)/pic2007286.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 25, weight: 1.7, description: "Hanabi—named for the Japanese word for \"fireworks\"—is a cooperative game in which players try to create the perfect fireworks show by placing the cards on the table in the right order. (In Japanese, hanabi is written as 花火; these are the ideograms flower and fire, respectively.)\n\nThe card deck consists of five different colors of cards, numbered 1–5 in each color. For each color, the players try to place a row in the correct order from 1–5. Sounds easy, right? Well, not quite, as in this game you hold your cards so that they're visible only to other players. To assist other players in playing a card, you must give them hints regarding the numbers or the colors of their cards. Players must act as a team to avoid errors and to finish the fireworks display before they run out of cards.\n\nAn extra suit of cards, rainbow colored, is also provided for advanced or variant play.\n\nHanabi was originally published as part of Hanabi & Ikebana.", mechanics: ["Communication Limits", "Kooperativ", "Handkartenmanagement", "Merkfähigkeit", "Ordering", "Set Collection"] },
  { title: "Forbidden Island", imageUrl: "https://cf.geekdo-images.com/JgAkEBUaiHOsOS94iRMs2w__original/img/H5d4I5z_HSpPEu7EAl0DqLt9_pM=/0x0/filters:format(jpeg)/pic646458.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 30, weight: 1.7, description: "Forbidden Island is a cooperative board game - everyone must work together to win the game. Players take turns moving their pawns around the 'island', which is built by arranging the tiles before play begins. As the game progresses, more and more island tiles sink, becoming unavailable, and the pace increases. Players use strategies to keep the island from sinking, while trying to collect treasures and items. As the water level rises, it gets more difficult- sacrifices must be made.\n\nPlayer move around the tiles, using their individual strengths to shore up tiles and explore for treasure.  If the water level gets too high, the island floods and everyone loses.  But, if all 4 Treasures have been captured AND all players are at Fools' Landing AND someone has a Helicopter Lift card to save the team, everyone wins!\n\nWith multiple levels of difficulty, different characters to choose from (each with a special ability of their own), many optional island formats and game variations available, Forbidden Island has huge replay value. The game can be played by as few as two players and up to four (though it can accommodate five). More players translates into a faster and more difficult game, though the extra help can make all the difference.", mechanics: ["Aktionspunkte", "Kooperativ", "Events", "Bewegung auf Gitterfeld", "Handkartenmanagement", "Map Reduction", "Modularer Spielplan", "Pick-up and Deliver", "Set Collection", "Solospiel", "Square Grid", "Plättchen platzieren", "Variable Spielerfähigkeiten"] },
  { title: "Forbidden Desert", imageUrl: "https://cf.geekdo-images.com/OU26qQZoHJodxSFKiR5IzA__original/img/8smpJMuHROyrbu8FP-EOLXjEi0w=/0x0/filters:format(jpeg)/pic1528722.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 45, weight: 2, description: "Gear up for a thrilling adventure to recover a legendary flying machine buried deep in the ruins of an ancient desert city. You'll need to coordinate with your teammates and use every available resource if you hope to survive the scorching heat and relentless sandstorm. Find the flying machine and escape before you all become permanent artifacts of the forbidden desert!\n\nIn Forbidden Desert, a thematic sequel to Forbidden Island, players take on the roles of brave adventurers who must throw caution to the wind and survive both blistering heat and blustering sand in order to recover a legendary flying machine buried under an ancient desert city. While featuring co-operative gameplay similar to Forbidden Island, Forbidden Desert is a fresh, new game based around an innovative set of mechanisms such as an ever-shifting board, individual resource management, and a unique method for locating the flying machine parts.", mechanics: ["Aktionspunkte", "Bias", "Kooperativ", "Bewegung auf Gitterfeld", "Handkartenmanagement", "Map Deformation", "Modularer Spielplan", "Pick-up and Deliver", "Solospiel", "Square Grid", "Plättchen platzieren", "Variable Spielerfähigkeiten"] },

  // Batch 5
  { title: "Flash Point: Fire Rescue", imageUrl: "https://cf.geekdo-images.com/v6bTbxeprDFj1nN4AenvjA__original/img/ri91i22ujLCZqxXKhFIdVDPGe8Y=/0x0/filters:format(jpeg)/pic1129370.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 45, weight: 2.2, description: "The call comes in... \"911, what is your emergency?\"  On the other end is a panicked response of \"FIRE!\" Moments later you don the protective suits that will keep you alive, gather your equipment and rush to the scene of a blazing inferno. The team has only seconds to assess the situation and devise a plan of attack – then you spring into action like the trained professionals that you are. You must face your fears, never give up, and above all else work as a team because the fire is raging, the building is threatening to collapse, and lives are in danger.\n\nYou must succeed. You are the brave men and women of fire rescue; people are depending on you. This is what you do every day.\n\nFlash Point: Fire Rescue is a cooperative game of fire rescue.\n\nThere are two versions of game play in Flash Point, a basic game and expert game.\nIn both variants, players are attempting to rescue 7 of 10 victims from a raging building fire.\nAs the players attempt to rescue the victims, the fire spreads to other parts of the building, causing structural damage and possibly blocking off pathways through the building.  Each turn a player may spend action points to try to extinguish fires, move through the building, move victims out of the building or perform various special actions such as moving emergency vehicles.  If 4 victims perish in the blaze or the building collapses from taking too much structural damage, the players lose.  Otherwise, the players win instantly when they rescue a 7th victim.\n\nThe expert variant included in the game adds thematic elements such as flash over, combustible materials, random setup, and variations on game difficulty from novice to heroic.  The game includes a double sided board with two different building plans and several expansion maps are available.", mechanics: ["Aktionspunkte", "Kooperativ", "Würfelglück", "Bewegung auf Gitterfeld", "Pick-up and Deliver", "Simulation", "Solospiel", "Square Grid", "Variable Spielerfähigkeiten"] },
  { title: "Pandemic: Iberia", imageUrl: "https://cf.geekdo-images.com/yAhmRtAw66-IOg4C22m9bA__original/img/5-_AFNTEq5mcUgw5iddXTyIz4Ho=/0x0/filters:format(jpeg)/pic6834208.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 45, weight: 2.6, description: "Welcome to the Iberian Peninsula! Set in 1848, Pandemic Iberia asks you to take on the roles of nurse, railwayman, rural doctor, sailor, and more to find the cures to malaria, typhus, the yellow fever, and cholera.\n\nFrom Barcelona to Lisboa, you will need to travel by carriage, by boat, or by train to help the Iberian populace. While doing so, distributing purified water and developing railways will help you slow the spread of diseases in this new version of Pandemic.\n\nDiscover a unique part of the world during a historically significant time period: the construction of the first railroad in the Iberian Peninsula during the Spring of Nations.\n\nThe game comes with two variants that can be added :\n\n     Influx of Patients : the cubes, representing patients, will tend to flock to hospitals to try to get cured. Hospitals also are a bit more powerful.\n     Historical Diseases : instead of being generic, each disease has a specific power to better represent what it is (Malaria, Cholera, Yellow Fever etc.)\n\n\nPart of the Pandemic series.", mechanics: ["Aktionspunkte", "Kooperativ", "Handkartenmanagement", "Streckenbau", "Bewegung entlang von Punkten", "Set Collection", "Solospiel", "Handel", "Variable Spielerfähigkeiten"] },
  { title: "Spirit Island", imageUrl: "https://cf.geekdo-images.com/kjCm4ZvPjIZxS-mYgSPy1g__original/img/9uLd9C3XAvInLCLhAoXqKVk56zs=/0x0/filters:format(jpeg)/pic7013651.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 120, weight: 4.1, description: "In the most distant reaches of the world, magic still exists, embodied by spirits of the land, of the sky, and of every natural thing. As the great powers of Europe stretch their colonial empires further and further, they will inevitably lay claim to a place where spirits still hold power - and when they do, the land itself will fight back alongside the islanders who live there.\n\nSpirit Island is a complex and thematic co-operative game about defending your island home from colonizing Invaders. Players are different spirits of the land, each with its own unique elemental powers. Every turn, players simultaneously choose which of their power cards to play, paying energy to do so. Using combinations of power cards that match a spirit's elemental affinities can grant free bonus effects. Faster powers take effect immediately, before the Invaders spread and ravage, but other magics are slower, requiring forethought and planning to use effectively. In the Spirit phase, spirits gain energy, and choose how / whether to Grow: to reclaim used power cards, to seek new power, or to spread their presence into new areas of the island.\n\nThe Invaders expand across the island map in a semi-predictable fashion. Each turn they explore into some lands (portions of the island); the next turn, they build in those lands, forming towns and cities. The turn after that, they ravage there, bringing blight to the land and attacking any native islanders present. The islanders fight back against the Invaders when attacked, and lend the spirits some other aid, but may not always do so exactly as you'd hoped. Some Powers work through the islanders, helping them, for example, to drive out the Invaders or clean the land of blight.\n\nThe game escalates as it progresses: spirits spread their presence to new parts of the island and seek out new and more potent powers, while the Invaders step up their colonization efforts. Each turn represents 1-3 years of alternate history. At game start, winning requires destroying every last explorer, town and city on the board - but as you frighten the Invaders more and more, victory becomes easier: they'll run away even if explorers or even towns and cities remain. Defeat comes if any spirit is destroyed, if the island is overrun by blight, or if the Invader deck is depleted before achieving victory.\n\nThe game includes different adversaries to fight against (eg., a Swedish Mining Colony, or a Remote British Colony). Each changes play in different ways, and offers a different path of difficulty boosts to keep the game challenging as you gain skill.", mechanics: ["Action Retrieval", "Gebietskontrolle", "Automatic Resource Growth", "Campaign / Battle Card Driven", "Kooperativ", "Deck, Bag, and Pool Building", "Handkartenmanagement", "Modularer Spielplan", "Gleichzeitige Aktionswahl", "Solospiel", "Tags", "Variable Spielerfähigkeiten", "Variable Set-up"] },
  { title: "Root: The Underworld Expansion", imageUrl: "https://cf.geekdo-images.com/LzZVgiX-d1nA_MSmZmH5tA__original/img/QjducX9OMQbVZf6ei1bhuKRWlAs=/0x0/filters:format(jpeg)/pic4608840.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 90, weight: 3.7, description: "New factions and battlefields join the world of Root!\n\nThe Underworld Expansion includes:\n\n    The Great Underground Duchy: an imperial faction that mixes the flexibility of the Marquise with the escalating Eyrie Dynasties.\n    The Corvid Conspiracy: a secretive faction that hatches plots directly into the hands of their opponents.\n    Two new maps: dig tunnels on the mountain map or fight to control the ferry on the lake map.\n\n\n—description from the publisher", mechanics: ["Action Queue", "Gebietskontrolle", "Betting and Bluffing", "Würfelglück", "Handkartenmanagement", "King of the Hill", "Bewegung entlang von Punkten", "Variable Spielerfähigkeiten"] },
  { title: "Terra Mystica", imageUrl: "https://cf.geekdo-images.com/bre12I1YiXkZr7elvriz4A__original/img/_dZS7fVfdc4DhJPbqnDpwTT4uF0=/0x0/filters:format(jpeg)/pic5375624.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 150, weight: 4, description: "In the land of Terra Mystica dwell 14 different peoples in seven landscapes, and each group is bound to its own home environment, so to develop and grow, they must terraform neighboring landscapes into their home environments in competition with the other groups.\n\nTerra Mystica is a full information game, without any luck, that rewards strategic planning. Each player governs one of the 14 groups. With subtlety and craft, the player must attempt to rule as great an area as possible and to develop that group's skills. There are also four religious cults in which you can progress. To do all that, each group has special skills and abilities.\n\nTaking turns, the players execute their actions on the resources they have at their disposal. Different buildings allow players to develop different resources. Dwellings allow for more workers. Trading houses allow players to make money. Strongholds unlock a group's special ability, and temples allow you to develop religion and your terraforming and seafaring skills. Buildings can be upgraded: Dwellings can be developed into trading houses; trading houses can be developed into strongholds or temples; one temple can be upgraded to become a sanctuary. Each group must also develop its terraforming skill and its skill with boats to use the rivers. The groups in question, along with their home landscape, are:\n\n\n    Desert (Fakirs, Nomads)\n    Plains (Halflings, Cultists)\n    Swamp (Alchemists, Darklings)\n    Lake (Mermaids, Swarmlings)\n    Forest (Witches, Auren)\n    Mountain (Dwarves, Engineers)\n    Wasteland (Giants, Chaos Magicians)\n\n\nProximity to other groups is a double-edged sword in Terra Mystica. Being close to other groups gives you extra power, but it also means that expanding is more difficult...\n\nTerra Mystica FAQ", mechanics: ["Chaining", "End Game Bonuses", "Hexagon Grid", "Income", "Increase Value of Unchosen Resources", "Streckenbau", "Tech Trees / Tech Tracks", "Turn Order: Pass Order", "Variable Spielerfähigkeiten", "Variable Set-up", "Victory Points as a Resource"] },
  { title: "Barrage", imageUrl: "https://cf.geekdo-images.com/jEPmWvvYpqkWrKOzqIHFsg__original/img/rkHKwkUqpQC7PAGG7n2gbrcQiUY=/0x0/filters:format(png)/pic4336469.png", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 180, weight: 4.1, description: "In den dystopischen 1930er Jahren brachte die industrielle Revolution die Ausbeutung fossiler Ressourcen an ihre Grenzen, und jetzt ist das Einzige, was mächtig genug ist, um den Durst nach Macht der massiven Maschinen und des unaufhaltsamen technischen Fortschritts zu stillen, die unbegrenzte Wasserkraft der Flüsse.\n\nSperrfeuer ist ein strategisches Ressourcenmanagement-Spiel, in dem die Spieler darum kämpfen, ihre majestätischen Dämme zu bauen, sie zu erhöhen, um ihre Speicherkapazität zu erhöhen, und die gesamte potenzielle Energie durch Drucktunnel zu liefern, die mit den Energieturbinen ihrer Kraftwerke verbunden sind.\n\nJeder Spieler repräsentiert eines der vier internationalen Unternehmen, die Maschinen, innovative Patente und brillante Ingenieure sammeln, um die besten Standorte für die Sammlung und Nutzung des Wassers einer umkämpften Alpenregion zu finden, die von Flüssen durchzogen wird.\n\nIn fünf Runden müssen die Spieler die Leistungsanforderungen erfüllen, die durch eine gemeinsame wettbewerbsfähige Leistungsspur repräsentiert werden, und spezifische Anforderungen von persönlichen Verträgen erfüllen. Gleichzeitig versuchen sie durch die Platzierung einer begrenzten Anzahl von Ingenieuren, ihre Maschinen zu verbessern, um neue und effizientere Baumaßnahmen zu erwerben und spezielle Gebäude mit einzigartigem Effekt zu bauen und zu aktivieren, um ihre eigene Entwicklungsstrategie voranzutreiben.", mechanics: ["Contracts", "End Game Bonuses", "Income", "Streckenbau", "Ownership", "Solospiel", "Turn Order: Stat-Based", "Variable Spielerfähigkeiten", "Variable Set-up", "Arbeitereinsatz"] },
  { title: "Anachrony", imageUrl: "https://cf.geekdo-images.com/31quLNzteInnevVRAABoow__original/img/3KfMPSj7jjhG0g5lQBsO-bn67D0=/0x0/filters:format(jpeg)/pic3499707.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 120, weight: 4, description: "Es ist das späte 26. Jahrhundert. Die Erde erholt sich von einer katastrophalen Explosion, die vor Jahrhunderten die Mehrheit der Bevölkerung auslöschte und den größten Teil der Oberfläche aufgrund unirdischer Wetterbedingungen unbewohnbar machte. Die überlebenden Menschen organisierten sich nach vier radikal unterschiedlichen Ideologien, den sogenannten Pfaden, um die Welt nach eigenem Gutdünken wieder aufzubauen: Harmonie, Dominanz, Fortschritt und Erlösung. Anhänger der vier Pfade leben in einem zerbrechlichen Frieden, aber in fast völliger Isolation nebeneinander. Ihr einziger Treffpunkt ist die letzte große Stadt der Erde, die heute nur noch als Hauptstadt bekannt ist.\n\nDurch die Verstärkung der mysteriösen Zeitspalten, die sich nach der Katastrophe öffneten, ist jeder Pfad in der Lage, zu bestimmten Momenten in seiner Vergangenheit zurückzukehren. Dies kann ihren Fortschritt erheblich beschleunigen, aber zu viel Einmischung kann das Zeit-Raum-Kontinuum gefährden. Aber Fortschritt ist wichtiger als je zuvor: Wenn man der mysteriösen Nachricht glauben will, die durch den Zeitspalt eintrifft, zeichnet sich eine noch schrecklichere Katastrophe am Horizont ab: Ein Asteroid mit der mysteriösen Substanz Neutronium steuert auf die Erde zu. Noch seltsamer ist, dass die Wissenschaftler zeigen, dass die Energiesignatur des Asteroiden mit der Explosion vor Jahrhunderten übereinstimmt...\n\nAnachrony verfügt über ein einzigartiges zweistufiges Arbeitsvermittlungssystem. Um in die Hauptstadt zu reisen oder sich in die zerstörten Gebiete zu wagen, brauchen die Spieler nicht nur verschiedene Spezialisten (Ingenieure, Wissenschaftler, Administratoren und Genies), sondern auch Exosuits, um", mechanics: ["Contracts", "Würfelglück", "Die Icon Resolution", "End Game Bonuses", "Events", "Map Reduction", "Open Drafting", "Set Collection", "Solospiel", "Turn Order: Claim Action", "Variable Spielerfähigkeiten", "Variable Set-up", "Arbeitereinsatz", "Worker Placement, Different Worker Types"] },
  { title: "On Mars", imageUrl: "https://cf.geekdo-images.com/Nm0Iw8NoiM9V8IsifimGBw__original/img/GNjjsgxq7wYO9pSIteDJe6Sxt00=/0x0/filters:format(jpeg)/pic4357658.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 150, weight: 4.6, description: "Following the success of unmanned rover missions, the United Nations established the Department of Operations and Mars Exploration (D.O.M.E.). The first settlers arrived on Mars in the year 2037 and in the decades after establishment of Mars Base Camp, private exploration companies began work on the creation of a self-sustaining colony. As chief astronaut for one of these enterprises, you want to be a pioneer in the development of the biggest, most advanced colony on Mars by achieving both D.O.M.E. mission goals as well as your company&rsquo;s private agenda.  In the beginning, you will be dependent on supplies from Earth and will have to travel often between the Mars Space Station and the planet's surface. As the colony expands over time, you will shift your activities to construct mines, power generators, water extractors, greenhouses, oxygen factories, and shelters. Your goal is to develop a self-sustaining colony independent of any terrestrial organization. This will require understanding the importance of water, air, power, and food — the necessities for survival. Do you dare take part in humankind&rsquo;s biggest challenge?\n\nOn Mars is played over several rounds, each consisting of two phases - the Colonization Phase ​and the Shuttle Phase​.\n\nDuring the Colonization Phase, each player takes a turn during which they take actions. The available actions depend on the side of the board they are on. If you are in orbit, you can take blueprints, buy and develop technologies, and take supplies from the Warehouse. If you are on the surface of the planet, you can construct buildings with your bots, upgrade these buildings using blueprints, take scientists and new contracts, welcome new ships, and explore the planet&rsquo;s surface with your rover. In the Shuttle Phase, players may travel between the colony and the Space Station in orbit.\n\nAll buildings on Mars have a dependency on each other and some are required for the colony to grow. Building shelters for Colonists to live in requires oxygen; generating oxygen requires plants; growing plants requires water; extracting water from ice requires power; generating power requires mining minerals; and mining minerals requires Colonists. Upgrading the colony&rsquo;s ability to provide each of these resources is vital. As the colony grows, more shelters are needed so that the Colonists can survive the inhospitable conditions on Mars.\n\nDuring the game, players are also trying to complete missions. Once a total of three missions have been completed, the game ends. To win the game, players must contribute to the development of the first colony on Mars. This is represented during the game by players gaining Opportunity Points (OP). The player with the most OP at the end of the game is declared the winner.", mechanics: ["Contracts", "Delayed Purchase", "End Game Bonuses", "Hexagon Grid", "Income", "Movement Points", "Set Collection", "Solospiel", "Tech Trees / Tech Tracks", "Plättchen platzieren", "Variable Phase Order", "Arbeitereinsatz"] },
  { title: "Lisboa", imageUrl: "https://cf.geekdo-images.com/OrHS8_a1CqSGiXeTfCk0Wg__original/img/hVArRkZYHiPTGTfi0DPR58i4o44=/0x0/filters:format(jpeg)/pic3209553.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 120, weight: 4.6, description: "Lisboa is a game about the reconstruction of Lisboa after the great earthquake of 1755.\n\nOn November 1, 1755, Lisbon suffered an earthquake of an estimated magnitude of 8.5–9.0, followed by a tsunami and three days of fires. The city was almost totally destroyed. The Marques of Pombal — Sebasti&atilde;o Jos&eacute; de Carvalho e Melo — was the then Minister of Foreign Affairs and the King put him in charge of the reconstruction of Lisbon. The Marques of Pombal gathered a team of engineers and architects and you, the players, are members of the nobility; members who will use your influence in the reconstruction and business development of the new city. You will work with the architects to build Lisbon anew, with the Marquis to develop commerce and with the King to open all the buildings, but the true reason you do all this is not for greatness or fame or even fortune, but for the most important thing of all in that time: wigs.\n\nLisboa is played on a real map of downtown Lisbon. During the planning of the downtown project, the type of business permitted in each street was previously determined. The economic motor is driven by the wealth of the royal treasure and this treasure is controlled by player actions during the game, making each game a totally different experience. The game ends after a fixed number of rounds and whoever gathers the most wigs by the end of the game wins.\n\nLisboa is played in rounds. Each round, all players play one turn. They may place one card on their display or replace one card from this display. During the game, players schedule hearings to get character favors, such as commerce, construction, and openings. The iconic buildings score the stores and stores provide income to the players. Players need to manage influence, construction licenses, store permits, church power, workers and money, with the workers' cost being dependent on the prestige of the players.", mechanics: ["Gebietskontrolle", "Handkartenmanagement", "Multi-Use Cards", "Open Drafting", "Set Collection", "Solospiel", "Plättchen platzieren"] },
  { title: "Brass: Lancashire", imageUrl: "https://cf.geekdo-images.com/tHVtPzu82mBpeQbbZkV6EA__original/img/3ffdJj5Pz6HQrg09Kh8ecTen-TY=/0x0/filters:format(jpeg)/pic3469216.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 120, weight: 3.8, description: "Brass: Lancashire — first published as Brass — is an economic strategy game that tells the story of competing cotton entrepreneurs in Lancashire during the industrial revolution. You must develop, build and establish your industries and network so that you can capitalize on demand for iron, coal and cotton. The game is played over two halves: the canal phase and the rail phase. To win the game, score the most victory points (VPs), which are counted at the end of each phase. VPs are gained from your canals, rails, and established (flipped) industry tiles. Each round, players take turns according to the turn order track, receiving two actions to perform any of the following:\n\n\n    Build an industry tile\n    Build a rail or canal\n    Develop an industry\n    Sell cotton\n    Take a loan\n\n\nAt the end of your turn, you replace the two cards you played with two more from the deck. Turn order is determined by how much money a player spent on the previous turn, the lowest spender going first. This turn order mechanism opens some strategic options for players going later in the turn order, allowing for the possibility of back-to-back turns.\n\nAfter all the cards have been played the first time (with the deck size being adjusted for the number of players), the canal phase ends and a scoring round commences. After scoring, all canals and all of the lowest level industries are removed from the game, after which new cards are dealt and the rail phase begins. During this phase, players may now occupy more than one location in a city and double-connection builds (though expensive) are possible. At the end of the rail phase, another scoring round takes place, then a winner is crowned.\n\nThe cards limit where you can build your industries, sell cotton or build connections (though any card can be used to 'develop'). This leads to a strategic timing/storing of cards. Resources are common so that if you build a rail line (which requires coal) you have to use the coal from the nearest source, which may be an opponent's coal mine, which in turn gets that coal mine closer to scoring (i.e., being utilized).\n\nBrass: Lancashire, the 2018 edition from Roxley Games, reboots the original Warfrog Games edition of Brass with new artwork and components, as well as a few rules changes:\n\n\n     The virtual link rules between Birkenhead have been made optional.\n     The three-player experience has been brought closer to the ideal experience of four players by shortening each half of the game by one round and tuning the deck and distant market tiles slightly to ensure a consistent experience.\n     Two-player rules have been created and are playable without the need of an alternate board.\n     The level 1 cotton mill is now worth 5 VP to make it slightly less terrible.", mechanics: ["Chaining", "End Game Bonuses", "Handkartenmanagement", "Income", "Loans", "Market", "Multi-Use Cards", "Streckenbau", "Ownership", "Tags", "Tech Trees / Tech Tracks", "Plättchen platzieren", "Turn Order: Stat-Based", "Variable Set-up"] },
  { title: "Concordia", imageUrl: "https://cf.geekdo-images.com/CzwSm8i7tkLz6cBnrILZBg__original/img/BhJ3sB3uk-eSdR1iW4EP3cu0Wi0=/0x0/filters:format(jpeg)/pic3453267.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 100, weight: 3, description: "Two thousand years ago, the Roman Empire ruled the lands around the Mediterranean Sea. With peace at the borders, harmony inside the provinces, uniform law, and a common currency, the economy thrived and gave rise to mighty Roman dynasties as they expanded throughout the numerous cities. Guide one of these dynasties and send colonists to the remote realms of the Empire; develop your trade network; and appease the ancient gods for their favor — all to gain the chance to emerge victorious!\n\nConcordia is a peaceful, strategy game of economic development in Roman times for 2-5 players aged 13 and up. Instead of looking to the luck of dice or cards, players must rely on their strategic abilities. Be sure to watch your rivals to determine which goals they are pursuing and where you can outpace them! In the game, colonists are sent out from Rome to settle down in cities that produce bricks, food, tools, wine, and cloth. Each player starts with an identical set of playing cards and acquires more cards during the game. These cards serve two purposes:\n\n\n    They allow a player to choose actions during the game.\n    They are worth victory points (VPs) at the end of the game. \n\n\nConcordia is a strategy game that requires advanced planning and consideration of your opponent's moves. Every game is different, not only because of the sequence of new cards on sale but also due to the modular layout of cities. (One side of the game board shows the entire Roman Empire with 30 cities for 3-5 players, while the other shows Roman Italy with 25 cities for 2-4 players.) When all cards have been sold or after the first player builds their 15th house, the game ends. The player with the most VPs from the gods (Jupiter, Saturnus, Mercurius, Minerva, Vesta, etc.) wins the game.", mechanics: ["Action Retrieval", "Advantage Token", "Auction: Dutch", "Deck, Bag, and Pool Building", "End Game Bonuses", "Handkartenmanagement", "Hidden Victory Points", "Investment", "Movement Points", "Streckenbau", "Open Drafting", "Bewegung entlang von Punkten", "Set Collection", "Variable Set-up"] },
  { title: "Roll for the Galaxy", imageUrl: "https://cf.geekdo-images.com/nhoyoLpYPC2b3UiJ5kJ0yg__original/img/LoETJCbq1HpSlhPLdci3qJekpwA=/0x0/filters:format(jpeg)/pic1473629.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 45, weight: 2.8, description: "Game description from the publisher:\n\nRoll for the Galaxy is a dice game of building space empires for 2–5 players. Your dice represent your populace, whom you direct to develop new technologies, settle worlds, and ship goods. The player who best manages his workers and builds the most prosperous empire wins!\n\nThis dice version of Race for the Galaxy takes players on a new journey through the Galaxy, but with the feel of the original game.", mechanics: ["Action Retrieval", "Contracts", "Deck, Bag, and Pool Building", "Würfelglück", "Die Icon Resolution", "Follow", "Handkartenmanagement", "Race", "Gleichzeitige Aktionswahl", "Tags", "Plättchen platzieren", "Variable Phase Order", "Variable Spielerfähigkeiten", "Variable Set-up", "Worker Placement with Dice Workers"] },
  { title: "Race for the Galaxy", imageUrl: "https://cf.geekdo-images.com/-DOqixs8uwKUvvWPKI4f9w__original/img/Vh-DCkTPa8OU45LaJdUywwhiYqE=/0x0/filters:format(jpeg)/pic5261714.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 60, weight: 3, description: "In Race for the Galaxy, players build galactic civilizations by playing cards representing worlds or technical and social developments.\n\nEach round, players secretly and simultaneously select an action card corresponding to one phase of a round. These phases let players draw cards, play cards, add goods to worlds, or consume goods for VP chips. Only the phases chosen will occur that round. Every player may act in a phase that occurs, but the players who chose that phase get a bonus.\n\nGame end is triggered either when a player has built a civilization of 12 cards or when the pool of VP chips is exhausted. Each player then totals the victory points in their tableau plus any VP chips earned during play.\n\nDetailed Overview\nRace for the Galaxy tells a story of galactic discovery and expansion through a single deck of cards. Every card in the deck represents either a world that you might settle or a development that you might implement. Cards placed into your tableau represent your current achievements -- worlds you have colonized, technology you now wield -- while cards in your hand represent the options currently available to you.\n\nTo play a card, discard the number of cards equal to its cost, representing other opportunities you must forgo to concentrate on your current course. Once in your tableau, a card provides special powers during the game and, at the end, its listed number of victory points. Many worlds, once placed, also produce goods that can be traded for more cards or consumed for VP chips.\n\nRace for the Galaxy is played in rounds. In each round, you and your opponents secretly select an action phase for the upcoming turn. You can choose to:\n&bull; Place a world in your tableau with settle or a development with develop.\n&bull; Produce goods on worlds with produce.\n&bull; Consume goods for VPs with consume.\n&bull; Add cards to your hand with explore or by trading a good.\n\nEach round, only those phases that are selected will occur -- but they'll occur for everyone. Selecting a phase both ensures that it occurs that round and gains the selecting player a bonus.\n\nRound follows round until someone builds their tableau to twelve cards, or until the last VP chip is claimed. The victor is the player with the most VPs.\n\n2018 UPDATE\nThe second edition of the game is improved for CVD (color blindness) and includes 5 revised cards from the original version and 6 New Worlds promo homeworlds. The promo homeworlds and first edition compatible Revised Cards are both available for purchase through the BGG store.\n\nUPC 655132003018", mechanics: ["End Game Bonuses", "Follow", "Handkartenmanagement", "Income", "Market", "Multi-Use Cards", "Gleichzeitige Aktionswahl", "Tags", "Variable Phase Order"] },
  { title: "San Juan", imageUrl: "https://cf.geekdo-images.com/kiD03bslLpN_0Qe1LJ8OGg__original/img/rFYh1En1BFLZ3n0Do-BwOnn7efU=/0x0/filters:format(jpeg)/pic174174.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 60, weight: 2.3, description: "San Juan is a card game based on Puerto Rico. The deck of 110 cards consists of production buildings (indigo, sugar, tobacco, coffee, and silver) and \"violet\" buildings that grant special powers or extra victory points. Cards from the hand can be either built or used as money to build something else; cards from the deck are used to represent goods produced by the production buildings, in which case they are left face-down. A seven-card hand limit is enforced once per round.\n\nIn each round (or governorship), each player in turn selects from one of the available roles, triggering an event that usually affects all players, such as producing goods or constructing buildings. The person who picks the role gets a privilege, such as producing more goods or building more cheaply.\n\nThough similar in concept to Puerto Rico, the game has many different mechanisms. In particular, the game includes no colonists and no shipping of goods; goods production and trading are normally limited to one card per phase; and trades cannot be blocked. Victory points are gained exclusively by building, and the game ends as soon as one player has put up twelve buildings.", mechanics: ["Action Drafting", "End Game Bonuses", "Follow", "Handkartenmanagement", "Market", "Multi-Use Cards", "Open Drafting", "Set Collection", "Turn Order: Progressive", "Variable Phase Order"] },
  { title: "El Grande", imageUrl: "https://cf.geekdo-images.com/RRKDHaYtFPHhczkUDcHOmg__original/img/E_QazS4f8ffj6oBcUl3C_VROCEw=/0x0/filters:format(jpeg)/pic7906240.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 120, weight: 2.9, description: "In this award-winning game, players take on the roles of Grandes in medieval Spain.  The king's power is flagging, and these powerful lords are vying for control of the various regions.  To that end, you draft caballeros (knights) into your court and subsequently move them onto the board to help seize control of regions.  After every third round, the regions are scored, and after the ninth round, the player with the most points is the winner.\n\nIn each of the nine rounds, you select one of your 13 power cards to determine turn order as well as the number of caballeros you get to move from the provinces (general supply) into your court (personal supply).\n\nA turn then consists of selecting one of five action cards which allow variations to the rules and additional scoring opportunities in addition to determining how many caballeros to move from your court to one or more of the regions on the board (or into the castillo - a secretive tower). Normally, you may only place your caballeros into regions adjacent to the one containing the king. The one hard and fast rule in El Grande is that nothing may move into or out of the king's region. One of the five action cards that is always available each round allows you to move the king to a new region. The other four action cards vary from round to round.\n\nThe goal is to have a caballero majority in as many regions (and the castillo) as possible during a scoring round. Following the scoring of the castillo, you place any cubes you had there into the region you secretly indicated on your region dial. Each region is then scored individually according to a table printed in that region. Two-point bonuses are awarded for having sole majority in the region containing your Grande and in the region containing the king.", mechanics: ["Action Drafting", "Gebietskontrolle", "Auction / Bidding", "Handkartenmanagement", "Open Drafting", "Selection Order Bid", "Gleichzeitige Aktionswahl", "Take That", "Turn Order: Auction"] },
  { title: "Tigris and Euphrates", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/e/e7/Deskohran%C3%AD_2008_0109.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 90, weight: 3.3, description: "Legespiel von Reiner Knizia im antiken Mesopotamien, bei dem Spieler Zivilisationen in vier Kategorien ausbalanciert entwickeln müssen, um Konflikte zu gewinnen.", mechanics: ["Legespiel", "Gebietskontrolle", "Mehrheitenbildung"] },
  { title: "Ra", imageUrl: "https://upload.wikimedia.org/wikipedia/en/5/53/Ra_game.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 60, weight: 2.3, description: "Auktionsspiel im alten Ägypten, in dem Spieler in mehreren Runden Plättchen ersteigern, um Sonnenlauf-Punkte in verschiedenen Kategorien zu sammeln.", mechanics: ["Bieten", "Setsammeln", "Zufallselement"] },
  { title: "Modern Art", imageUrl: "https://cf.geekdo-images.com/wLto-xaabHwKQe_Bc4iD1Q__original/img/s3Gai8XBTVfWFFlYpL4XF3kIlWU=/0x0/filters:format(png)/pic3458036.png", minPlayers: 3, maxPlayers: 5, playTimeMinutes: 45, weight: 2.3, description: "Buying and selling paintings can be a very lucrative business.  Five different artists have produced a bunch of paintings, and it's the player's task to be both the buyer and the seller, hopefully making a profit in both roles.  He does this by putting a painting from his hand up for auction each turn.  He gets the money if some other player buys it, but must pay the bank if he buys it for himself.  After each round, paintings are valued by the number of paintings of that type that were sold.  The broker with the most cash after four rounds is the winner.\n\nPart of the Knizia auction trilogy.", mechanics: ["Auction / Bidding", "Auction: English", "Auction: Once Around", "Auction: Sealed Bid", "Auction: Turn Order Until Pass", "Commodity Speculation", "Handkartenmanagement", "Victory Points as a Resource"] },
  { title: "Medici", imageUrl: "https://upload.wikimedia.org/wikipedia/en/9/9e/Medici_game.jpg", minPlayers: 3, maxPlayers: 6, playTimeMinutes: 45, weight: 2.1, description: "Auktionsspiel im Handelsmilieu der Renaissance, bei dem Spieler Warenschiffe ersteigern und beladen, um am Ende die wertvollste Fracht zu besitzen.", mechanics: ["Bieten", "Setsammeln", "Ressourcenmanagement"] },
  { title: "Bohnanza", imageUrl: "https://cf.geekdo-images.com/8SADtu_4zBH_UJrCo935Iw__original/img/RNuAr2CDbxE3XzeJVkxj4Df3eVM=/0x0/filters:format(jpeg)/pic6348964.jpg", minPlayers: 2, maxPlayers: 7, playTimeMinutes: 45, weight: 1.7, description: "Bohnanza ist das erste Spiel der Bohnanza-Spielefamilie und wurde in mehreren verschiedenen Ausgaben veröffentlicht, darunter eine Version mit Blumen aus dem Jahr 2023.\n\nDieser Eintrag listet ein paar verschiedene große Kartensätze für Bohnanza auf: das Basisspiel für 3-5 Spieler, das erweiterte Spiel mit dem gleichen Namen für 2-7 Spieler (dh erste Erweiterung enthalten) und Bohnanza Pocket.\n\nIm Spiel pflanzt du Bohnenkarten und erntest sie dann, um Münzen zu verdienen. Jeder Spieler beginnt mit einer Hand von zufälligen Bohnenkarten, und jede Karte hat eine Zahl darauf, die der Anzahl dieser Art von Bohnen im Deck entspricht. Im Gegensatz zu den meisten anderen Kartenspielen können Sie die Reihenfolge der Karten in der Hand nicht neu anordnen, also müssen Sie sie in der Reihenfolge verwenden, in der Sie sie vom Deck abgeholt haben — es sei denn, Sie können sie an andere Spieler tauschen, was das Herzstück des Spiels ist.\n\nIn einem Zug musst du die ersten ein oder zwei Karten in deiner Hand in die \"Felder\" vor dir legen. Jedes Feld kann nur eine Bohnensorte aufnehmen. Wenn Sie also eine Bohnensorte pflanzen müssen, die sich nicht auf einem Ihrer Felder befindet, müssen Sie ein Feld ernten, um Platz für den Neuankömmling zu schaffen. Das ist normalerweise nicht gut! Als nächstes decken Sie zwei Karten aus dem Deck auf, und Sie können diese Karten sowie jede Karte in Ihrer Hand gegen Karten von anderen Spielern eintauschen. Sie können sogar zukünftige Versprechungen für Karten machen, die Sie jetzt erhalten! Nachdem der Handel abgeschlossen ist — und alle Trades in einem Zug müssen den aktiven Spieler einbeziehen — beenden Sie Ihren Zug, indem Sie Karten vom Deck ziehen und sie hinten platzieren", mechanics: ["Handkartenmanagement", "Multi-Use Cards", "Verhandlung", "Resource Queue", "Set Collection", "Handel"] },
  { title: "6 Nimmt!", imageUrl: "https://cf.geekdo-images.com/WuOY1XAIJQ-RGAmT_apW_w__original/img/06TSBC2s-cwbxfPmy_pf7n5p-jM=/0x0/filters:format(jpeg)/pic8632998.jpg", minPlayers: 2, maxPlayers: 10, playTimeMinutes: 45, weight: 1.2, description: "In Take 5, alias 6 nimmt!, Kategorie 5 und viele andere Namen, möchten Sie so wenig Punkte wie möglich erzielen.\n\nUm das Spiel zu spielen, mischen Sie die 104 Zahlenkarten, legen vier Karten offen aus, um die vier Reihen zu beginnen, und verteilen dann zehn Karten an jeden Spieler. In jedem Zug wählen und enthüllen die Spieler gleichzeitig eine Karte aus ihrer Hand und fügen dann die Karten zu den Reihen hinzu, wobei die Karten in aufsteigender Reihenfolge basierend auf ihrer Anzahl platziert werden. Insbesondere wird jede Karte in der Reihe platziert, die mit der höchsten Zahl endet, die unter der Kartennummer liegt. Wenn die sechste Karte in einer Reihe platziert wird, beansprucht der Besitzer dieser Karte die anderen fünf Karten und die sechste Karte wird zur ersten Karte in seiner Reihe.\n\nZusätzlich zu einer Zahl von 1 bis 104 hat jede Karte einen Punktwert. Nach zehn Runden zählen die Spieler ihre Punktzahl und sehen, ob das Spiel endet. (Kategorie 5 endet, wenn ein Spieler zum Beispiel eine Punktzahl von mehr als 74 hat, während 6 nimmt! endet, wenn jemand 66 übertrifft.) In diesem Fall gewinnt der Spieler mit den wenigsten Punkten!\n\n6 nimmt! arbeitet mit 2-10 Spielern, und die Dynamik des Gameplays ändert sich, je mehr Spieler du hast. Eine Variante für das Spiel besteht darin, dass Sie nur die niedrigsten 34 Karten, 44 Karten, 54 Karten usw. (anstelle aller 104 Karten) verwenden, wenn Sie drei, vier, fünf usw. Spieler haben. Diese Änderung ermöglicht es Ihnen, genau zu wissen, welche Karten im Spiel sind, so dass Sie verfolgen können, welche Karten gespielt wurden und wissen, was Sie erwartet, so dass Sie (theoretisch) bessere Entscheidungen treffen können, welche Karte wann gespielt werden soll.", mechanics: ["Handkartenmanagement", "Ordering", "Risikomanagement", "Score-and-Reset Game", "Gleichzeitige Aktionswahl"] },
  { title: "No Thanks!", imageUrl: "https://cf.geekdo-images.com/JSAs8aMopjf8P9JXwTMV7w__original/img/pm0ioQ1vNabJExMgcXwB2oMIalY=/0x0/filters:format(png)/pic9005058.png", minPlayers: 3, maxPlayers: 7, playTimeMinutes: 20, weight: 1.1, description: "No Thanks! is a card game designed to be as simple as it is engaging.\n\nThe rules are simple.  Each turn, players have two options:\n\n    play one of their chips to avoid picking up the current face-up card\n    pick up the face-up card (along with any chips that have already been played on that card) and turn over the next card\n\n\nHowever, the choices aren't so easy as players compete to have the lowest score at the end of the game.  The deck of cards is numbered from 3 to 35, with each card counting for a number of points equal to its face value.  Runs of two or more cards only count as the lowest value in the run - but nine cards are removed from the deck before starting, so be careful looking for connectors.  Each chip is worth -1 point, but they can be even more valuable by allowing you to avoid drawing that unwanted card.\n\nThe first versions of the game supported up to five players, but the German 2011 edition supports up to seven (simply by increasing the number of chips).\n\nThis game was originally published in Germany in 2004 by Amigo as Geschenkt ...ist noch zu teuer!, meaning Even given as a gift, it is still too expensive!.  Amigo's 2006 international edition, titled No Merci! (a delightful multi-lingual pun), had rules in several languages, including English. The game has subsequently been released in other countries under an assortment of names. The German 2024 edition includes additional cards to allow for play with variant rules.", mechanics: ["Auction / Bidding", "Closed Economy Auction", "Risikomanagement", "Score-and-Reset Game", "Set Collection"] },
  { title: "For Sale", imageUrl: "https://cf.geekdo-images.com/dJh9HkZC346NgPTAicJq_A__original/img/6ib2NLakSlsf69WYwCOe9NNLcsc=/0x0/filters:format(jpeg)/pic1513085.jpg", minPlayers: 3, maxPlayers: 6, playTimeMinutes: 30, weight: 1.2, description: "For Sale is a quick, fun game nominally about buying and selling real estate. During the game's two distinct phases, players first bid for several buildings then, after all buildings have been bought, sell the buildings for the greatest profit possible.\n\nThe original Ravensburger/FX Schmid edition (1997/98) has slightly different rules than later English editions, and only 20 buildings instead of 30.\n The Überplay 2005 Edition has new art, rules and card distribution changes, and it accommodates 3-6 players.\n\nThe Gryphon 2009 Edition uses the &Uuml;berplay art for the faces of the property cards, while replacing most other art.  The rules are the same as the &Uuml;berplay edition, with the exception of the rounding rule (which was stated in different ways in different printings of the &Uuml;berplay edition).\n\nRounding rule\n\nThe rounding rule preferred by the designer Stefan Dorra is that players get back half of their bid rounded DOWN (not UP), as confirmed in correspondence with him here and here.  A history of how the rounding rule has changed in different editions is documented here.", mechanics: ["Auction / Bidding", "Auction: Sealed Bid", "Auction: Turn Order Until Pass", "Handkartenmanagement", "Selection Order Bid"] },
  { title: "Coloretto", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/8/85/Coloretto_01.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 30, weight: 1.2, description: "Kartenspiel, bei dem Spieler Farbkarten auf Fahrzeuge verteilen oder sich diese nehmen, um am Ende möglichst wertvolle Farbsammlungen zu besitzen.", mechanics: ["Setsammeln", "Bluffen", "Push your luck"] },
  { title: "Zombie Dice", imageUrl: "https://cf.geekdo-images.com/iPy584JMAJYrupqRdQp8gA__original/img/zPbWjPYgLscrjd96Uitf3GTPb34=/0x0/filters:format(jpeg)/pic4991962.jpg", minPlayers: 2, maxPlayers: 99, playTimeMinutes: 20, weight: 1.1, description: "Eat brains. Don't get shotgunned.\n\nIn Zombie Dice, you are a zombie. You want braaains – more brains than any of your zombie buddies. The 13 custom dice are your victims. Push your luck to eat their brains, but stop rolling before the shotgun blasts end your turn! Whoever collects 13 brains first wins. Each game takes 10 to 20 minutes and can be taught in a single round.\n\nEach turn, you take three dice from the box and roll them. A brain symbol is worth one point at the end of the round, while footsteps allow you to reroll this particular dice. Shotgun blasts on the other hand are rather bad, cause if you collect three shotgun blasts during your turn, it is over for you and you get no points. After rolling three dice, you may decide if you want to score your current brain collection or if you want to push your luck by grabbing new dice so you have three again and roll once more.", mechanics: ["Würfelglück", "Die Icon Resolution", "Risikomanagement", "Re-rolling and Locking"] },

  // Batch 6
  { title: "King of New York", imageUrl: "https://cf.geekdo-images.com/FGekxht_r5xqt8oSmQ9HZg__original/img/b5zgGvja0Qpte-Jqb5baQNWuG3c=/0x0/filters:format(jpeg)/pic2407103.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 40, weight: 1.9, description: "There's always something happening in the city that never sleeps. Maybe it's the lights, maybe it's the energy, or maybe it's the giant monsters trying to demolish the place!\n\nKing of New York is a standalone game from designer Richard Garfield that keeps the core ideas of King of Tokyo while introducing new ways to play. As in KoT, your goal is to be the first monster to collect 20 victory points (VPs) or to be the last monster standing. On your turn, you roll six dice up to three times, then carry out the actions on those dice. Claws cause damage to other monsters, hearts heal damage to yourself, and energy is stored up so that you can purchase power cards that provide unique effects not available to anyone else.\n\nWhat's new in King of New York is that you can now try to become a star in the big city; more specifically, you can achieve \"Fame\", which nets you VPs, but superstar status is fleeting, so enjoy your time in the spotlight.\n\nThe game board for King of New York is larger than in KoT with each monster occupying a district in the city and everyone trying to shine in Manhattan. When you attack, you can displace a monster in another district, whether to escape military forces or to find new smashing opportunities. Yes, smashing because you can now destroy buildings and get bonuses for doing so, but the more destruction you cause, the more intense the military response.\n\nThe monsters from King of New York can be used in KoT and vice versa, but the power cards are specific to this game.\n\nPart of the King of Tokyo series.", mechanics: ["Würfelglück", "Die Icon Resolution", "King of the Hill", "Open Drafting", "Spielerausscheidung", "Risikomanagement", "Re-rolling and Locking", "Tags", "Take That"] },
  { title: "Machi Koro", imageUrl: "https://cf.geekdo-images.com/_lI2eUDHfesfe5SswJiFAg__original/img/H4XHVffQ4SOxgWoG396I9LUrwg8=/0x0/filters:format(png)/pic4783831.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 30, weight: 1.5, description: "Welcome to the city of Machi Koro. You've just been elected Mayor. Congrats! Unfortunately, the citizens have some pretty big demands: jobs, a theme park, a couple of cheese factories, and maybe even a radio tower. A tough proposition since the city currently consists of a wheat field, a bakery, and a single die.\n\nArmed only with your trusty die and a dream, you must grow Machi Koro into the largest city in the region. You will need to collect income from developments, build public works, and steal from your neighbors' coffers. Just make sure they aren't doing the same to you!\n\nMachi Koro is a fast-paced game for 2-4 players. Each player wants to develop the city on their own terms in order to complete all of the landmarks under construction faster than their rivals. On their turn, each player rolls one or two dice. If the sum of the dice rolled matches the number of a building that a player owns, they get the effect of that building; in some cases, opponents will also benefit from your dice (just as you can benefit from theirs). Then, with money in hand, a player can build a landmark or a new building, ideally adding to the wealth of their city on future turns. The first player to construct all of their landmarks wins!", mechanics: ["Würfelglück", "Ownership", "Race", "Random Production"] },
  { title: "Sushi Go Party!", imageUrl: "https://cf.geekdo-images.com/2f9uTicUSXkdPp2Yks6zFw__original/img/WQcFmlhYBMIp8f6gNNVhnnue1w4=/0x0/filters:format(jpeg)/pic5885689.jpg", minPlayers: 2, maxPlayers: 8, playTimeMinutes: 20, weight: 1.3, description: "Sushi Go Party! expands Sushi Go! with a party platter of mega maki, super sashimi, and endless edamame. You still earn points by picking winning sushi combos, but now you can customize each game by choosing &agrave; la carte from a menu of more than twenty delectable dishes. What's more, up to eight players can join in on the sushi-feast. Let the good times roll!\n\n—description from the publisher", mechanics: ["Closed Drafting", "End Game Bonuses", "Handkartenmanagement", "Risikomanagement", "Score-and-Reset Game", "Set Collection", "Gleichzeitige Aktionswahl", "Variable Set-up"] },
  { title: "Fluxx", imageUrl: "https://upload.wikimedia.org/wikipedia/en/3/39/FluxxEN-DE-FU.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 30, weight: 1.3, description: "Ein Kartenspiel mit ständig wechselnden Regeln und Siegbedingungen, bei dem jede gespielte Karte das Spielgeschehen neu definiert.", mechanics: ["Kartenmanagement", "Regeländerung", "Chaos"] },
  { title: "Set", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/8/8f/Set-game-cards.png", minPlayers: 1, maxPlayers: 20, playTimeMinutes: 15, weight: 1.5, description: "Ein schnelles Mustererkennungsspiel, bei dem Spieler gleichzeitig nach Kartensätzen mit übereinstimmenden oder komplett unterschiedlichen Merkmalen suchen.", mechanics: ["Echtzeit", "Mustererkennung", "Kartenmanagement"] },
  { title: "Dobble", imageUrl: "https://cf.geekdo-images.com/hqDT4HbEb2eNCyMOeiGj-g__original/img/6w3wjI3YZOWa8XLxoKQqg3XnbN0=/0x0/filters:format(png)/pic6477003.png", minPlayers: 2, maxPlayers: 8, playTimeMinutes: 15, weight: 1, description: "Spot it!, a.k.a. Dobble, is a simple pattern recognition game in which players try to find an image shown on two cards.\n\nEach card in original Spot it! features eight different symbols, with the symbols varying in size from one card to the next. Any two cards have exactly one symbol in common. For the basic Spot it! game, reveal one card, then another. Whoever spots the symbol in common on both cards claims the first card, then another card is revealed for players to search, and so on. Whoever has collected the most cards when the 55-card deck runs out wins!\n\nRules for different games – each an observation game with a speed element – are included with Spot it!, with the first player to find a match either gaining or getting rid of a card. Multiple versions of Spot it! have been published, with images in each version ranging from Halloween to hockey to baseball to San Francisco.\n\nThe game is sold as Spot it! in the USA and Dobble in Europe, with slight differences between the two editions.\n\nNote: some versions have fewer cards and fewer symbols per card. (E.g. 30 cards with 6 symbols each.): Spot it! 1,2,3", mechanics: ["Hot Potato", "Pattern Recognition", "Speed Matching"] },
  { title: "Ubongo", imageUrl: "https://cf.geekdo-images.com/0wSuQbmk4nPwNytp9_zzPw__original/img/DccSEdsXQG65cfwPJjdrkJySojI=/0x0/filters:format(jpeg)/pic4597123.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 25, weight: 1.5, description: "In Ubongo, players compete to solve individual puzzles as quickly as they can to get first crack at the gems on hand for the taking.\n\nOriginal edition:\nThe game board consists of six rows, with twelve gems (of various colors) placed in these rows. At the start of play, each player places their pawn in front of one of those rows. Each player also takes twelve polyominoes — that is, pieces consisting of 2-5 squares in some configuration; players use these pieces each round to try to recreate shapes.\n\nAt the start of a round, each player receives a puzzle card that depicts a shape created by some number of squares; one side of this card depicts six rows of 3 pieces, the other side depicts six rows of 4 pieces, for a more difficult puzzle. When everyone is ready, someone rolls a die to determine which row of pieces each player can use to recreate the shape on their individual card. The race is timed by a sand timer, and the outcome of this race determines the action on the main playing board.\n\nWhoever first solves their puzzle in time gets to move their pawn up to three rows left or right, with the second player to finish moving two rows and the third player only one row. Players then collect two gems from the front of the row where their pawn is located, which means that the more rows you can move, the more control you have over which color gems you can collect. After collecting gems, each player receives a new puzzle card, and a new round begins.\n\nAfter nine rounds, the game ends and whoever has collected the most gems in a single color wins! If players tie, then those players compare who has the most gems in a second color, and so on.\n\n2015 edition:\nThe puzzle-part of the game remains the same, but the scoring track and system has been greatly changed, to be the same as in Ubongo Extreme. There are no pawns anymore, but instead the winner takes a 3-point gem plus a random gem, the second-place player takes a 1-point gem plus a random gem, and others who finish within time take just a random gem. Whoever scores the most gem-points after nine rounds wins the game.", mechanics: ["Grid Coverage", "Musterbildung", "Real-Time", "Set Collection"] },
  { title: "Rush Hour", imageUrl: "https://cf.geekdo-images.com/doS4gO8PNMurdfL4uUf5sA__original/img/BFdtZd7VLBPKRmg2VSCBhERBGHA=/0x0/filters:format(jpeg)/pic6945338.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 60, weight: 1.3, description: "This game page is NOT for the 1-player ThinkFun puzzle that is also named Rush Hour. It is a very different game. Please use the Outside the Scope of BGG page to share images of ThinkFun Rush Hour, and other 1-player ThinkFun puzzles. There is also a 2-player ThinkFun product called Rush Hour Shift that does have a game page.\n\nThe object of the game is to traverse the board from HOME to the OFFICE after dropping off one's commuters at their respective places of employment.\n\nYou start off with two commuters but may pick up extra ones before you're out of the Neighborhood Jaunt.  Next is either the Interstate 500 or Suburban Gauntlet.  After this is the Beltway Expressway, with a Car Pool Express Lane for the lucky bastards with three or more commuters on board.  Finally, there is the Inner City Maze.\n\nYou normally roll two dice, but some road signs reduce that number to one die.  Optional rules include Traffic Jams, Fender Benders, Public Parking, Double Parking and Baby Behind the Wheel.", mechanics: ["Würfeln und Ziehen"] },
  { title: "Labyrinth", imageUrl: "https://upload.wikimedia.org/wikipedia/en/d/dd/Amazing_Labyrinth_game_box.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 30, weight: 1.5, description: "Spieler verschieben Gangkarten in einem sich ständig verändernden Labyrinth, um Schätze einzusammeln, bevor die Gegner es tun.", mechanics: ["Legespiel", "Tile-Placement", "Taktik"] },
  { title: "Ricochet Robots", imageUrl: "https://cf.geekdo-images.com/3qg1xTP7ZZiu8OolGBYJ1w__original/img/wkfYHdMR_P05Mat4oTHa9cmRNCA=/0x0/filters:format(jpeg)/pic1766273.jpg", minPlayers: 1, maxPlayers: 99, playTimeMinutes: 30, weight: 2.4, description: "Ricochet Robots is less of a game and more of a puzzle, which explains why there's such an odd number of solutions possible. There's a four-piece modular board that forms a large room with walls spread around the board. There are also color-coded targets on boards. Placed on top of the surface are four robots. The idea for each turn/puzzle is to get the like-colored robot to a randomly selected target. The trick is that once a robot starts moving, it will continue to move until a wall or another robot stops it. Therefore, players are seeking a sequence of moves for the robots that will enable them to move the required robot to the target in the fewest moves.", mechanics: ["Bewegung auf Gitterfeld", "Modularer Spielplan", "Real-Time", "Square Grid", "Turn Order: Stat-Based", "Variable Set-up"] },
  { title: "Geistesblitz", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/9/98/Geistesblitz_03.jpg", minPlayers: 2, maxPlayers: 8, playTimeMinutes: 15, weight: 1.1, description: "Ein Reaktionsspiel, bei dem Spieler anhand von Farbe und Form auf einer Karte blitzschnell die richtige Figur ergreifen müssen.", mechanics: ["Reaktionsspiel", "Echtzeit", "Mustererkennung"] },
  { title: "Halli Galli", imageUrl: "https://cf.geekdo-images.com/gm-LiZvjkluOeKqPvuUjDg__original/img/LK1FFqGshBAiepAk37cyGEm3DI0=/0x0/filters:format(jpeg)/pic8223481.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 10, weight: 1, description: "Halli Galli is a speed action game in which players watch for sets of exactly five fruit. The deck contains 56 playing cards showing four kinds of fruit in groups of 1 to 5 and a bell of the type found at hotel reception desks.\n\nThe deck is distributed evenly between the players. All players hold their deck face down and take turns dealing one card face up in front of them. As each player reveals her next card, the instant you see a total of five of one kind of fruit on the table, hit the bell. If you're correct, you pick up all the played cards and put them into your deck; if you're wrong, you pay the other players one card each. When you run out of cards, you're out. When two players are left, they play until the bell is struck once more, then the game ends and the taller deck wins.\n\nKeep in mind that a five-of-a-kind can occur both when cards are revealed and when they're covered. If, for example, cards showing 3, 1 and 4 bananas are on the table and the 3 is then covered by a non-banana card, suddenly five bananas are showing and somebody better be reaching for the bell.", mechanics: ["Pattern Recognition", "Spielerausscheidung"] },
  { title: "Jungle Speed", imageUrl: "https://cf.geekdo-images.com/pb553nZgH3akaF24MzT7nA__original/img/YVxlSoQ5q-8w4FMn8hM6Gz4nCNg=/0x0/filters:format(jpeg)/pic4659199.jpg", minPlayers: 2, maxPlayers: 10, playTimeMinutes: 10, weight: 1.1, description: "In Jungle Speed, you must rely on your keen sense of observation and quick reflexes. It requires a steady hand -- which can be hard to maintain during the many fits of maniacal laughter! The wooden Totem sits in the middle of the table, waiting for the player with the fastest reflexes to snatch it up and win the game.\n\nEach player is dealt a hand of cards. In order to win you must be the first player to get rid of all of your cards. Each turn, all of the players reveal one of their cards. If two cards are identical, those players must make a grab for the Totem. The faster player then gives their cards to their unfortunate adversary.\n\nTo add to the difficulty, certain cards are almost identical, which can trick a hapless player into grabbing the Totem by mistake -- a grave error. Other cards force all players to make a grab at once, change the method of play, or otherwise add to the difficulty.\n\nJungle Jam, Медвед, and Prawo Dżungli are unauthorized reproductions of Jungle Speed/Arriba!", mechanics: ["Pattern Recognition", "Real-Time", "Speed Matching"] },
  { title: "The Resistance: Avalon", imageUrl: "https://cf.geekdo-images.com/LPa6rsGcv8S0-OeNjCOAEQ__original/img/AF8HHaIad1re-eg3kd9mlm2j_ss=/0x0/filters:format(jpeg)/pic1398895.jpg", minPlayers: 5, maxPlayers: 10, playTimeMinutes: 30, weight: 1.7, description: "The Resistance: Avalon pits the forces of Good and Evil in a battle to control the future of civilization. Arthur represents the future of Britain, a promise of prosperity and honor, yet hidden among his brave warriors are Mordred's unscrupulous minions. These forces of evil are few in number but have knowledge of each other and remain hidden from all but one of Arthur's servants. Merlin alone knows the agents of evil, but he must speak of this only in riddles. If his true identity is discovered, all will be lost.\n\nThe Resistance: Avalon is a standalone game, and while The Resistance is not required to play, the games are compatible and can be combined.", mechanics: ["Finale Ending", "Verdeckte Rollen", "Roles with Asymmetric Information", "Gleichzeitige Aktionswahl", "Teamspiel", "Traitor Game", "Variable Spielerfähigkeiten", "Abstimmung"] },
  { title: "Secret Hitler", imageUrl: "https://cf.geekdo-images.com/rAQ3hIXoH6xDcj41v9iqCg__original/img/7oKwNUYakx3-vHUBLHWVuFNKfl4=/0x0/filters:format(jpeg)/pic5164305.jpg", minPlayers: 5, maxPlayers: 10, playTimeMinutes: 45, weight: 1.7, description: "Secret Hitler is a dramatic game of political intrigue and betrayal set in 1930s Germany. Each player is randomly and secretly assigned to be a liberal or a fascist, and one player is Secret Hitler. The fascists coordinate to sow distrust and install their cold-blooded leader; the liberals must find and stop the Secret Hitler before it's too late. The liberal team always has a majority.\n\nAt the beginning of the game, players close their eyes, and the fascists reveal themselves to one another. Secret Hitler keeps his eyes closed, but puts his thumb up so the fascists can see who he is. The fascists learn who Hitler is, but Hitler doesn't know who his fellow fascists are, and the liberals don't know who anyone is.\n\nEach round, players elect a President and a Chancellor who will work together to enact a law from a random deck. If the government passes a fascist law, players must try to figure out if they were betrayed or simply unlucky. Secret Hitler also features government powers that come into play as fascism advances. The fascists will use those powers to create chaos unless liberals can pull the nation back from the brink of war.\n\nThe objective of the liberal team is to pass five liberal policies or assassinate Secret Hitler. The objective of the fascist team is to pass six fascist policies or elect Secret Hitler chancellor after three fascist policies have passed.", mechanics: ["Verdeckte Rollen", "Spielerausscheidung", "Teamspiel", "Traitor Game", "Abstimmung"] },
  { title: "Ultimate Werewolf", imageUrl: "https://cf.geekdo-images.com/pbX50vKkFCUBsK8DolVq_w__original/img/dE5Uc1WDKFFKKSxwPGzlMIWlSyo=/0x0/filters:format(png)/pic1878507.png", minPlayers: 5, maxPlayers: 30, playTimeMinutes: 90, weight: 1.2, description: "Ultimate Werewolf is an interactive game of deduction for two teams: Villagers and Werewolves. The Villagers don't know who the Werewolves are, and the Werewolves are trying to remain undiscovered while they slowly eliminate the Villagers one at a time. A Moderator (who isn't on a team) runs the game.\n\nUltimate Werewolf takes place over a series of game days and nights. Each day, the players discuss who among them is a Werewolf, and vote out a player. Each night, the Werewolves choose a player to eliminate, while the Seer learns if one player is a Werewolf or not. The game is over when either all the Villagers or all the Werewolves are eliminated.\n\nUltimate Werewolf, a new edition of the award-winning, best-selling werewolf title from B&eacute;zier Games, has been reimagined to allow new players to quickly get up and running, with a larger box, totally rewritten and simplified rules, and a guide for the included roles. With all-new art and a great new card design, it's the perfect way to introduce groups of 7-30 people to Werewolf.", mechanics: ["Verdeckte Rollen", "Role Playing", "Geschichten erzählen", "Teamspiel", "Traitor Game", "Variable Spielerfähigkeiten", "Abstimmung"] },
  { title: "Deception: Murder in Hong Kong", imageUrl: "https://cf.geekdo-images.com/1COY3oeK9aN2_XNimKaNww__original/img/ZzyzlO15ggCfkLg9ckeM4PWNePI=/0x0/filters:format(jpeg)/pic3033330.jpg", minPlayers: 4, maxPlayers: 12, playTimeMinutes: 20, weight: 1.6, description: "Deception: Murder in Hong Kong is a game of deduction and deception for 4-12 players that plays in about 20 minutes.\n\nIn the game, players take on the roles of investigators attempting to solve a murder case – but there's a twist. The killer is one of the investigators! Each player's role and team are randomly assigned at the start of play and include the unique roles of Forensic Scientist, Witness, Investigator, Murderer, and Accomplice. While the Investigators attempt to deduce the truth, the murderer's team must deceive and mislead. This is a battle of wits!\n\nThe Forensic Scientist has the solution but can express the clues only using special scene tiles while the investigators (and the murderer) attempt to interpret the evidence. In order to succeed, the investigators must not only deduce the truth from the clues of the Forensic Scientist, they must also see through the misdirection being injected into the equation by the Murderer and Accomplice!\n\nFind out who among you can cut through deception to find the truth and who is capable of getting away with murder!\n\nRoles\n\nForensic Scientist x1\nAs the game master, the Forensic Scientist holds the solution to the crime. They are responsible for assisting the Investigators in identifying the &ldquo;Key Evidence&rdquo; and &ldquo;Means of Murder.&rdquo; When an Investigator does that successfully, the crime is solved and the Forensic Scientist and the Investigators win the game.\n\nDuring the game, the Forensic Scientist is NOT allowed to hint to the solution with words, gestures, or eyes.\n\nMurderer x1\nWhen the crime takes place, the Murderer chooses 1 Clue card and 1 Means card as the solution to the crime. These will be the &ldquo;Key Evidence&rdquo; and &ldquo;Means of Murder&rdquo; respectively.\n\nThe Murderer tries to hide their role and look for a scapegoat. Even if they are identified, the Murderer still wins the game if no one correctly identifies both the &ldquo;Key Evidence&rdquo; and the &ldquo;Means of Murder&rdquo;.\n\nInvestigators x8\nTo solve the crime, the Investigators must analyze the hints given by the Forensic Scientist. As long as one of the Investigators correctly identifies both the &ldquo;Key Evidence&rdquo; and &ldquo;Means of Murder,&rdquo; the Murderer is arrested and the Investigators win the game (as does the Forensic Scientist).\n\nBear in mind that the Murderer (and sometimes Accomplice) is among the Investigators! The innocent Investigators must make a vigorous effort to defend themselves from false accusation.\n\nAccomplice x1\nThe Accomplice is an optional role for games with six or more players. The Accomplice knows who the Murderer is, as well as the solution to the crime. The Accomplice and Murderer both win if the Murderer gets away with his crime.\n\nWitness x1\nThe Witness is an optional role when playing with six or more players.* The Witness is an Investigator who has witnessed the culprits leaving the crime scene. They have no way of knowing which is the Murderer and which is the Accomplice and they do not know how the crime was committed.\n\nIf the Murderer is arrested but can identify the Witness, the Witness is considered to be killed, allowing the Murderer and the Accomplice to get away with murder and win the game.", mechanics: ["Communication Limits", "Deduction", "Events", "Finale Ending", "Verdeckte Rollen", "Roles with Asymmetric Information", "Geschichten erzählen", "Teamspiel", "Traitor Game", "Variable Set-up"] },
  { title: "Mysterium Park", imageUrl: "https://cf.geekdo-images.com/U2CYPYgIEC1cLF45Rh0UGw__original/img/472oJ1mqGHWxFxuOsnXFiZBshUc=/0x0/filters:format(jpeg)/pic5581038.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 45, weight: 1.4, description: "Welcome to Mysterium Park!  The park&rsquo;s former director has disappeared, but the investigation came to nothing. Since that night, weird things are happening on the fairground. As psychics, you&rsquo;re convinced that a ghost haunts this carnival. You&rsquo;re now intent on giving it a chance to reveal the truth.\n\nIn this cooperative stand-alone game, the ghost sends visions with illustrated cards. The psychics try to interpret them in order to rule out certain suspects and locations. Then, they&rsquo;ll seize their only chance to piece together what happened to the director. You have only six nights before the carnival leaves town. Open your minds and find the truth!\n\nSet in the lights of a 1950's US fairground, Mysterium Park shares the same core mechanism of Mysterium, though it is smaller and faster. Turns are quicker as players only have to guess who and where and they games ends after 6 rounds. Detectives can cooperate to make sure everyone is guessing correctly.\n\nThe detectives discuss what they think the clues point to and once they all agree they tell the cluemaster which column (I, II or III) shows the culprit and crime scene. If they are right everyone wins. If not, everyone loses.\n\n— description from the publisher", mechanics: ["Communication Limits", "Kooperativ", "Pattern Recognition", "Roles with Asymmetric Information", "Geschichten erzählen"] },
  { title: "Dixit Odyssey", imageUrl: "https://upload.wikimedia.org/wikipedia/en/7/7b/Dixitgame.jpg", minPlayers: 3, maxPlayers: 12, playTimeMinutes: 30, weight: 1.2, description: "Eine Erweiterung des Erzähl- und Assoziationsspiels Dixit für größere Gruppen, bei dem Spieler mit poetischen Hinweisen zu Traumbildern raten.", mechanics: ["Storytelling", "Bluffen", "Assoziation"] },
  { title: "Trapwords", imageUrl: "https://cf.geekdo-images.com/aU1dLvPuTgGY0NsFajD9HQ__original/img/Ca6SXTVgQ7PFf0mHrorNI8iZOxc=/0x0/filters:format(jpeg)/pic4327157.jpg", minPlayers: 4, maxPlayers: 8, playTimeMinutes: 45, weight: 1.4, description: "The game is for 2 teams, divided into two approximately equivalent number of players and takes about 30 minutes to play.\n\nIt could remind you of the classic word game known as Taboo, but this one has an interesting twist on gameplay – the opposing team is the one who chooses the words you cannot use. With you having no idea which words are \"traps\", it&rsquo;s like dancing on a minefield, when you&rsquo;re trying to describe your assigned word to the rest of the team.\n\nYou take the role of a group of adventurers crawling through a fantasy dungeon full of traps and curses, with a Boss waiting for you at the end.\nYou have to successfully guess a word that one of your teammates is trying to describe to you. Sounds simple, but it is made fiendishly difficult by not knowing which words you can't say. Because both teams are simultaneously preparing secret traps for each other, words that you can't use. And further you get, the more trapwords you might expect.\n\nLet's see the example of one possible turn when you are trying to give clues for the word \"Axe\":\n\nYou: \"It is a thing that a dwarf can…\"\nOpponents team: \"A-ha, dwarf! Gotcha!\"\nYou: \"How did you know that? Was it obvious I will use that?\"\n\nOr when you would try another approach it could look like this, the successful turn of your team:\n\nYou: \"This thing is used by a man with a beard, in a checkered shirt....\"\nOne of your teammates: \"A coffee maker?\"\n[Everyone laughs]\nYou: \"He uses it for work in nature.\"\nAnother teammate: \"A chainsaw!\"\nYou: \"He makes smaller pieces from a big plant with it.\"\nAny of your teammate: \"An axe!\"\nYou: \"Yes! Very good!\"\n\nCould you avoid your opponent's trapwords when you don't know what you can't say?", mechanics: ["Communication Limits", "Modularer Spielplan", "Teamspiel"] },
  { title: "The Fake Artist Goes to New York", imageUrl: null, minPlayers: 5, maxPlayers: 10, playTimeMinutes: 20, weight: 1.3, description: "Alle Spieler zeichnen reihum an einem gemeinsamen Bild mit, doch ein Spieler kennt das Motiv nicht und muss unentdeckt bleiben.", mechanics: ["Bluffen", "Zeichnen", "Soziale Deduktion"] },
  { title: "Telestrations", imageUrl: "https://cf.geekdo-images.com/Dd94J37Oi1tgL7HAAaOfAQ__original/img/SAMxnv21q2rwvViEOu2nti4H0Is=/0x0/filters:format(jpeg)/pic8855812.jpg", minPlayers: 4, maxPlayers: 8, playTimeMinutes: 30, weight: 1.1, description: "The award-winning party game Telestrations will get your family and friends laughing as they draw what they see, then guess what they saw for hours of hilarious miscommunication. All players simultaneously sketch, pass, and guess while revealing laugh-out-loud and unpredictable outcomes!", mechanics: ["Drawing", "Paper-and-Pencil"] },
  { title: "Doppelkopf", imageUrl: "https://cf.geekdo-images.com/VYuFYs6PFqns1oMPvGnyQQ__original/img/0LQ_qWW1R-tlHCbfSkza1bH_J_E=/0x0/filters:format(jpeg)/pic9214086.jpg", minPlayers: 3, maxPlayers: 6, playTimeMinutes: 120, weight: 2.9, description: "Somewhat complex card game with variable partnerships and several different solo game types. Extremely popular in Germany. Basic mechanic being collecting tricks where different cards score different amount of points.\nThe rule-set of gameplay differs in many regions of Germany. For example, some regions play with nines and some without, also many special points and solo games are variated in different regions.", mechanics: ["Alliances", "Predictive Bid", "Teamspiel", "Trick-taking"] },
  { title: "Skat", imageUrl: "https://upload.wikimedia.org/wikipedia/commons/2/27/Skat_Trick_Jacks.svg", minPlayers: 3, maxPlayers: 4, playTimeMinutes: 40, weight: 3, description: "Deutschlands bekanntestes Kartenspiel für drei Spieler, bei dem Reizen, Trumpfstrategie und Stichspiel über Sieg oder Niederlage entscheiden.", mechanics: ["Stichspiel", "Reizen", "Taktik"] },
  { title: "Elfenland", imageUrl: "https://cf.geekdo-images.com/Ea4jN5Ko5bPrXrU_AYhhzg__original/img/DEi0SFU6mAMZYycGTEJAV4ZBRVw=/0x0/filters:format(jpeg)/pic1798136.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 60, weight: 2.1, description: "Elfenland is a redesign of the original White Wind game Elfenroads.  The game is set in the mythical world of the elves.  A group of fledgling elves (the players) are charged with visiting as many of the twenty Elfencities as they can over the course of 4 rounds.  To accomplish the task they will use various forms of transportation such as Giant Pigs, Elfcarts, Unicorns, Rafts, Magic Clouds, Trollwagons, and Dragons.\n\nGameplay:  Players begin in the Elf capitol, draw one face down movement tile, and are dealt eight transport cards and a secret 'home' city card that they must reach at the end of the 4th round or lose points for each city space away from 'home' they are at the end of the game. Markers of each player's color are placed in each city on the board and are collected when the player visits that city (each counts as 1 point).\n  \n     The round proceeds in 2 stages.  The first part of the round consists of the drawing of Tiles showing the differing types of transport (except rafts) from a combination of face up and face down tiles (if a player doesn't like the 5 tiles that are face up; they can always draw blind from the face down tiles and hope to get one they need).  These transport tiles need to match the Transportation cards in your hand to use them most effectively.  After each player has a total of 4 tiles they take turns placing a tile on any one of the roads that run between the elf cities.  Only one transport tile may be placed on each road; so players may use other players tiles to travel if they have the matching cards in their hand.  This frequently causes a readjustment of planned travel routes as other players tiles can allow you to move farther or shorter than you had first thought.  Players can play their tiles to help themselves or hinder others by playing a slow mode of transport on another players (perceived) path.\n\nEach mode of transport has certain terrain it can travel through quickly or slowly, and those that it cannot. These are listed on the top of each transportation card by the number terrain symbols.  The number of terrain symbols equals how many matching cards you must play to move across a given tile in a given terrain.  For example, a Magic Cloud tile placed in a mountain would take one Magic cloud card to travel across (1 mountain symbol on card means Magic clouds are fast in mountains). If the same tile was placed on a road in forest terrain it would require 2 Magic Cloud cards to travel that route (2 Forest symbols on card means Magic Clouds are slow in Forest).  Magic Clouds cannot travel in desert terrain at all (no desert symbols on card). All modes of transport are different and Rafts can be used on rivers or lakes without needing tiles. Rafts go slow upstream (2 raft cards needed) and fast downstream (1 card needed).  The small lake requires 1 raft card to travel across and the larger lake requires 2 cards to travel across.  Players may keep one unused transport counter and up to 4 Transportation cards from one round to the next.\n\nThe second part of the round begins after all players have finished placing their transportation tiles for the round.  Each player plays his cards and moves his elf-boot around the board collecting his tokens from the cities visited.  If there is a Transport tile on a route and a player has no matching Transportation card he may 'Caravan' across it by playing any 3 Transportation cards from his hand.\n\nAs a bit of 'take that' each player has a trouble tile which can be placed next to any transportation tile during the first part of the round.  This counter means that in order to travel that path an additional card of the transport type must be played or 4 cards to 'Caravan'.\n\nVictory: if at the end of round 3 a player has visited all 20 cities he is the winner.  If not the game ends after round 4 when 'Home' cities are revealed and each player subtracts points for each city he is away from his 'home' subtracting that from his collected city tokens.  The person with the highest score wins.", mechanics: ["Handkartenmanagement", "Streckenbau", "Open Drafting", "Bewegung entlang von Punkten", "Programmed Movement", "Turn Order: Progressive"] },

  // Batch 7
  { title: "Diamant", imageUrl: null, minPlayers: 3, maxPlayers: 8, playTimeMinutes: 30, weight: 1.2, description: "Diamant (auch Incan Gold) ist ein Push-your-luck-Kartenspiel, bei dem Abenteurer eine Höhle erkunden und entscheiden müssen, wann sie mit ihren Schätzen fliehen, bevor Fallen sie um alles bringen.", mechanics: ["Push your luck", "Bluffen", "Kartenmanagement"] },
  { title: "Colt Express", imageUrl: "https://cf.geekdo-images.com/2HKX0QANk_DY7CIVK5O5fQ__original/img/okv8rhQupsrXsEJsovQ_BJV5hKA=/0x0/filters:format(jpeg)/pic2869710.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 40, weight: 1.8, description: "On the 11th of July, 1899 at 10 a.m., the Union Pacific Express has left Folsom, New Mexico, with 47 passengers on board. After a few minutes, gunfire and hurrying footsteps on the roof can be heard. Heavily armed bandits have come to rob honest citizens of their wallets and jewels. Will they succeed in stealing the suitcase holding the Nice Valley Coal Company's weekly pay, despite it having been placed under the supervision of Marshal Samuel Ford? Will these bandits hinder one another more than the Marshal since only the richest one of them can come out on top?\n\nIn Colt Express, you play a bandit robbing a train at the same time as other bandits, and your goal is to become the richest outlaw of the Old West. The game consists of five rounds, and each round has two phases:\n\n\n    Phase 1: Schemin' Each player plays 2-5 action cards on a common pile, with the cards being face up or face down depending on the type of the round. Instead of playing a card, a player can draw three cards from her deck.\n    Phase 2: Stealin' The action cards are carried out in the order they were played, with a player's best laid plans possibly not panning out due to mistakes and oversights!\n\n\nThe game takes place in a 3D train in which the bandits can move from one car to another, run on the roof, punch the other bandits, shoot them, rob the passengers, or draw the Marshal out of position. The train has as many cars as the number of players, and each car is seeded with gems, bags of loot or suitcases at the start of play.\n\nEach player starts a round with six cards in hand, with each card showing one of these actions. At the start of a round, a round card is revealed, showing how many cards will be played; whether they'll be played face up or face down, or individually or in pairs; and what action will occur at the end of the round (e.g., all bandits on top of the train move to the engine). You can pick up loot, gems or suitcases only by playing a \"steal\" card when you're in a train car that holds one of these items — but since everyone is planning to get these goods, you'll need to move, punch and shoot to get others out of your way. You can punch someone only in the same car as you, and when you do, the other bandit drops one of the goods he's collected and is knocked into an adjacent car.\n\nEach player's character has a special power, such as starting the round with an extra card, playing your first card face down, or pocketing a bag of loot when you punch someone instead of letting it hit the ground.\n\nYou can shoot someone in an adjacent car or (if you're running on top of the train) anyone in sight, and when you do, you give that player one of your six bullet cards; that card gets shuffled in the opponent's deck, possibly giving her a dead card in hand on a future turn and forcing her to draw instead of playing something. If the Marshal ends up in the same car as you, likely due to other bandits luring him through the train, he'll be happy to give you a bullet, too.\n\nAt the end of the game, whoever fired the most bullets receives a $1,000 braggart bonus, and whoever bagged the richest haul wins!", mechanics: ["Action Queue", "Handkartenmanagement", "Merkfähigkeit", "Programmed Movement", "Take That", "Turn Order: Progressive", "Variable Spielerfähigkeiten"] },
  { title: "Camel Up", imageUrl: "https://cf.geekdo-images.com/jVr1bGBQpshqVPcwvZ7CPg__original/img/GlPdJsTvSho-vqwOOYfC4zyvOa0=/0x0/filters:format(jpeg)/pic1918028.jpg", minPlayers: 2, maxPlayers: 8, playTimeMinutes: 30, weight: 1.5, description: "In Camel Up, up to eight players bet on five racing camels, trying to suss out which will place first and second in a quick race around a pyramid. The earlier you place your bet, the more you can win — should you guess correctly, of course. Camels don't run neatly, however, sometimes landing on top of another one and being carried toward the finish line. Who's going to run when? That all depends on how the dice come out of the pyramid dice shaker, which releases one die at a time when players pause from their bets long enough to see who's actually moving!\n\nPlayers roll all 5 dice to setup the start positions of the camels.  On each leg, players pick one betting card for each color camel, showing how many coins they will win/lose, depending on the camel's position after the leg.  The dice are then rolled in the pyramid dice roller, which allows one die to come out at a time and moves the matching color camel.  Players can also place oasis cards to earn extra coins.  After all 5 camels are moved, bets are resolved and a new leg start.  Play continues until a camel passes the finish line.\n\nOnce a camel crossess the finish line, all end of race bets are resolved and the player with the most coins wins.", mechanics: ["Betting and Bluffing", "End Game Bonuses", "Würfeln und Ziehen", "Track Movement", "Variable Set-up"] },
  { title: "Mysterium: Hidden Signs", imageUrl: null, minPlayers: 2, maxPlayers: 6, playTimeMinutes: 20, weight: 1.5, description: "Mysterium: Hidden Signs ist ein kooperatives Kartenspiel im Mysterium-Universum, bei dem ein stummer Geist den Ermittlern mit Symbolkarten Hinweise gibt, um einen Mordfall zu lösen.", mechanics: ["Kooperativ", "Deduktion", "Kartenmanagement"] },
  { title: "Takenoko", imageUrl: "https://cf.geekdo-images.com/uvz-5V6A2R6dp2oWIXmj_g__original/img/HxMG1z7bIVGCGPI6u6ciVO0Oubk=/0x0/filters:format(jpeg)/pic1912529.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 45, weight: 2, description: "A long time ago at the Japanese Imperial court, the Chinese Emperor offered a giant panda bear as a symbol of peace to the Japanese Emperor. Since then, the Japanese Emperor has entrusted his court members (the players) with the difficult task of caring for the animal by tending to his bamboo garden.\n\nIn Takenoko, the players will cultivate land plots, irrigate them, and grow one of the three species of bamboo (Green, Yellow, and Pink) with the help of the Imperial gardener to maintain this bamboo garden. They will have to bear with the immoderate hunger of this sacred animal for the juicy and tender bamboo. The player who manages his land plots best, growing the most bamboo while feeding the delicate appetite of the panda, will win the game.", mechanics: ["Aktionspunkte", "Contracts", "Würfelglück", "Die Icon Resolution", "End Game Bonuses", "Bewegung auf Gitterfeld", "Hexagon Grid", "Modularer Spielplan", "Streckenbau", "Musterbildung", "Race", "Set Collection", "Tags", "Plättchen platzieren"] },
  { title: "Century: Spice Road", imageUrl: "https://cf.geekdo-images.com/0_KEDk4lCvryf1Ju3YQJxA__original/img/zv58Iylm_N8nfVFgRkMVM0Q9Fh8=/0x0/filters:format(jpeg)/pic3339551.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 45, weight: 1.8, description: "Century: Spice Road is the first in a series of games that explores the history of each century with spice-trading as the theme for the first installment.  In Century: Spice Road, players are caravan leaders who travel the famed silk road to deliver spices to the far reaches of the continent for fame and glory. Each turn, players perform one of four actions:\n\n\n     Establish a trade route (by taking a market card)\n     Make a trade or harvest spices (by playing a card from hand)\n     Fulfill a demand (by meeting a victory point card's requirements and claiming it)\n     Rest (by taking back into your hand all of the cards you've played)\n\n\nThe last round is triggered once a player has claimed their fifth victory point card, then whoever has the most victory points wins.", mechanics: ["Action Retrieval", "Auction: Dutch", "Contracts", "Deck, Bag, and Pool Building", "End Game Bonuses", "Handkartenmanagement", "Increase Value of Unchosen Resources", "Open Drafting", "Set Collection", "Variable Set-up"] },
  { title: "Nusfjord", imageUrl: "https://cf.geekdo-images.com/nKYqNPEE94Zk_q5Vtk527w__original/img/Bf35-bzWhSF8jMq8pfzubBxuNlU=/0x0/filters:format(jpeg)/pic3729070.jpg", minPlayers: 1, maxPlayers: 5, playTimeMinutes: 100, weight: 2.9, description: "Nusfjord is a tranquil fishing village in the Lofoten archipelago in northern Norway. Fifty years ago, business was blooming when the codfish would come for spawning. Today, Nusfjord is more of a museum than a village, with less than a hundred people living there. Imagine how beautiful this place must be given that you must pay a fee to even look at the houses. Cruise ships used to pass by this long and now mostly abandoned island world.\n\nIn the time period in which the game Nusfjord is set, things looked quite different. Sailing ships dominate the fjord. The rocks around Nusfjord are covered in trees. As the owner of a major fishing company in Nusfjord on the Lofoten archipelago, your goal is to develop the harbor and the surrounding landscape, and to succeed you must enlarge your fleet, clear the forest, erect new buildings, and satisfy the local elders. Others do this as well, of course, so the competition is steep.\n\nAs with Agricola, Caverna, and Ora et Labora, Nusfjord has a worker placement mechanism, with each player starting with three workers that they place on a central board to trigger certain actions. Whether a player wants to clear a forest on their own board, buy a new cutter, or construct a building, they must place a worker on the appropriate space — which is possible only if room is available for this worker. Money is scarce, and one of the quicker and easier ways to get it is to place shares of your own company on the market. This risky action could be worthwhile because if you succeed in buying these shares yourself, you have usually won money and not suffered any disadvantages; however, if an opponent acquires these shares, then you must allow them to benefit from your hard-earned catches at sea. The village elders might want their own share of your catch as well, especially if you've visited them to take certain actions in the village, so if you don't take care, your catch could end up entirely in the hands of others and your camp will be empty.", mechanics: ["Open Drafting", "Turn Order: Claim Action", "Arbeitereinsatz"] },
  { title: "Grand Austria Hotel", imageUrl: "https://cf.geekdo-images.com/PJRaImV8iXGAq2L-6rrn-w__original/img/8DrrN_WD5-jXfWj7ZFr0A3eqKPM=/0x0/filters:format(jpeg)/pic2649931.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 120, weight: 3.2, description: "In the thick of the Viennese modern age, exquisite caf&eacute;s are competing for customers. Inspiring artists, important politicians, and tourists from all over the world are populating Vienna and in need of a hotel room. This is your opportunity to turn your little caf&eacute; into a world famous hotel. Hire staff, fulfill the wishes of your guests, and gain the emperor's favor. Only then will your caf&eacute; become the Grand Austria Hotel.\n\nThe start player rolls the dice, sorting them by the rolled number and placing them on the corresponding action spaces. On a turn, a player chooses one of the six actions and carries it out. The number of the available dice in the corresponding action spaces determines how much the player gets from the action. They then remove one of the dice and can carry out additional actions. With the different actions, a player can get the necessary drinks and dishes, prepare the rooms, or hire staff.\n\nBut no hotel can grow without guests. To choose wisely which guests to attract and to complete their orders brings some important bonus actions. The staff cards also have different advantages, but the game ends after seven rounds and no player can do everything they want, so whoever makes the right decisions and finds the best way to create bonus actions will win.\n\nWith 116 different cards and a new set-up in each game, Grand Austria Hotel provides a huge replay value. Each game stands on its own and demands new tactics and strategies.", mechanics: ["Action Drafting", "Contracts", "Würfelglück", "End Game Bonuses", "Handkartenmanagement", "Set Collection", "Turn Order: Progressive", "Variable Set-up"] },
  { title: "The Castles of Burgundy", imageUrl: "https://upload.wikimedia.org/wikipedia/en/d/dd/The_Castles_of_Burgundy_Box_cover.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 90, weight: 2.9, description: "The Castles of Burgundy ist ein Strategiespiel von Stefan Feld, in dem Spieler mit Würfeln Waren, Gebäude und Landschaftsplättchen erwerben, um ihr Fürstentum in Burgund auszubauen.", mechanics: ["Würfeleinsatz", "Legespiel", "Tableau Building"] },
  { title: "The Quacks of Quedlinburg", imageUrl: "https://cf.geekdo-images.com/B1bLRWzTASZ-xx9NoAE79A__original/img/HulJk6gFzp_bxl0wzc2XEMq8NLM=/0x0/filters:format(png)/pic8780293.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 45, weight: 1.9, description: "In Quacks, which was first released as The Quacks of Quedlinburg, players are charlatans — or quack doctors — each making their own secret brew by adding ingredients one at a time. Take care with what you add, though, for a pinch too much of this or that will spoil the whole mixture!\n\nEach player has their own bag of ingredient chips. During each round, they simultaneously draw chips from their bags and add them to their pots. The higher the face value of the drawn chip, the further it is placed in the pot's swirling pattern, increasing how much the potion will be worth. Push your luck as far as you can, but if you add too many cherry bombs, your pot will explode!\n\nAt the end of each round, players gain victory points and coins to spend on new ingredients, depending on how well they managed to fill up their pots. But players whose pots have exploded must choose points or coins — not both! The player with the most victory points at the end of nine rounds wins the game.", mechanics: ["Catch the Leader", "Deck, Bag, and Pool Building", "Delayed Purchase", "Würfelglück", "Die Icon Resolution", "Events", "Neighbor Scope", "Risikomanagement", "Score-and-Reset Game", "Gleichzeitige Aktionswahl", "Track Movement", "Variable Set-up"] },
  { title: "Kingdomino Origins", imageUrl: "https://cf.geekdo-images.com/MUM0pZVIb6ImCmuoE7g1tQ__original/img/ccWNQSEMtjdW1_khIJaGzOHHSc0=/0x0/filters:format(jpeg)/pic6249158.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 40, weight: 1.9, description: "Go back in time to the prehistoric era of Kingdomino!\n\nKingdomino Origins plays similarly to the original game, but introduces new components for additional actions and new ways to score points. Regions in your territory will earn you points if they contain fire. Fire is either part of your terrains or earned by adding dominoes with volcanoes. There are three game modes to play:\n\n\n    The first one introduces fire and volcanoes;\n    The second mode uses wooden resources;\n    And the third one features cavemen tokens.\n\n\nYou earn points by collecting resources, with additional points when you have the majority of a type of resources. These resources allow you to bring cavemen to your territory, and each type of caveman has its own way to give you points based on their position.\n\n—description from the publisher", mechanics: ["Enclosure", "Open Drafting", "Plättchen platzieren", "Turn Order: Claim Action"] },
  { title: "The Voyages of Marco Polo", imageUrl: "https://cf.geekdo-images.com/n1G7_aWToLAAB7Mqt8iwyA__original/img/VQddnfi_QO0r4GmUU3M8_-nuO3Q=/0x0/filters:format(png)/pic2461346.png", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 100, weight: 3.2, description: "In 1271, 17-year-old Marco Polo started on a journey to China with his father and older brother. After a long and grueling journey that led through Jerusalem and Mesopotamia and over the \"Silk Road\", they reached the court of Kublai Khan in 1275.\n\nIn The Voyages of Marco Polo, players recreate this journey, with each player having a different character from history with a special power in the game. The game is played over five rounds. Each round, the players roll their five personal dice and take turns performing actions by placing their dice onto the board. Players may choose from a variety of actions, each require the use of one or more dice: collecting resources or money, acquiring contracts, traveling on the map or using a special action granted by a city. When traveling, each player begins at Venice and can decide between several routes eastward, all the way to Beijing. When a player stops at a city, they place a trading post there, giving them access to extra actions or resources for the rest of the game. The higher the value of the dice used for an action, the better the options that may be chosen, but also the more money the player must pay if an opponent has already chosen the same action.\n\nAfter five rounds, the game ends with players receiving extra victory points for having trading posts in Beijing, fulfilling the most contracts, and having trading posts in the cities on secret goal cards that each player gets at the start of the game.\n\nThis game should not be confused with Marco Polo Expedition, which has the same German title.", mechanics: ["Contracts", "Würfelglück", "End Game Bonuses", "Bewegung entlang von Punkten", "Resource to Move", "Turn Order: Claim Action", "Variable Spielerfähigkeiten", "Variable Set-up", "Worker Placement with Dice Workers"] },
  { title: "Orléans", imageUrl: "https://cf.geekdo-images.com/nagl1li6kYt9elV9jbfVQw__original/img/Qn6vlBaTUaHNFsqohIUjd0EA4z0=/0x0/filters:format(jpeg)/pic6228507.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 90, weight: 3, description: "During the medieval goings-on around Orl&eacute;ans, you must assemble a following of farmers, merchants, knights, monks, etc. to gain supremacy through trade, construction and science in medieval France.\n\nIn Orl&eacute;ans, you will recruit followers and put them to work to make use of their abilities. Farmers and Boatmen supply you with money and goods; Knights expand your scope of action and secure your mercantile expeditions; Craftsmen build trading stations and tools to facilitate work; Scholars make progress in science; Traders open up new locations for you to use your followers; and last but not least, it cannot hurt to get active in monasteries since with Monks on your side you are much less likely to fall prey to fate.\n\nYou will always want to take more actions than possible, and there are many paths to victory. The challenge is to combine all elements as best as possible with regard to your strategy.", mechanics: ["Contracts", "Deck, Bag, and Pool Building", "End Game Bonuses", "Events", "Kill Steal", "Bewegung entlang von Punkten", "Gleichzeitige Aktionswahl", "Tech Trees / Tech Tracks", "Turn Order: Progressive", "Variable Set-up", "Worker Placement, Different Worker Types"] },
  { title: "Ora et Labora", imageUrl: null, minPlayers: 2, maxPlayers: 4, playTimeMinutes: 150, weight: 3.7, description: "Ora et Labora ist ein komplexes Aufbauspiel von Uwe Rosenberg, in dem Spieler eine Klostersiedlung mit Gebäuden, Produktionsketten und Rohstoffveredelung entwickeln.", mechanics: ["Worker Placement", "Ressourcenmanagement", "Tableau Building"] },
  { title: "Fields of Arle", imageUrl: "https://cf.geekdo-images.com/0w8go6cfvlpgJKydHUkDtA__original/img/322N77t8F7uTev-U_WCqX5uqmEE=/0x0/filters:format(png)/pic2225968.png", minPlayers: 1, maxPlayers: 2, playTimeMinutes: 120, weight: 3.8, description: "Welcome to Arle\nIn Fields of Arle, created by Uwe Rosenberg, one to two players live as farmers in the small and peaceful town of Arle in East Frisia. The flax grown in the land surrounding the village makes it a profitable place to work and live. Fields of Arle takes players through four and a half years of this era of prosperity, with different opportunities available as the seasons change. Farm the land to capitalize on the demand for flax, or find other ways to make the most of the small town&rsquo;s prosperity.\n\nWork the Land\nWhether you delve into flax farming or leverage other areas of expertise, always make sure that you have the land to build up your village. Construct dikes to keep the waters at bay and expand your fields. Dry out bogs to harvest peat and then clear the land for cultivation. Create more fields for your livestock, buildings, or future crops; after that, you can decide whether to house animals or cultivate a forest for timber. Perhaps you&rsquo;d like to take up some flax farming for yourself, or diversify and try out a little bit of everything.\n\nTools of the Trade\nAt the outset of each half year, you&rsquo;ll choose how you&rsquo;d like to spend that time working. There are many ways to build your fortune. Use the Master space to increase the tools at your disposal, focus on the Cattle Trainer to make the most of your livestock, or build up your fleet of vehicles and ship out goods. Taking stock of your progress differs depending on the season. You may milk your existing livestock or care for a bunch of newborn animals. You could harvest your flax in the fall, and shear your sheep in spring. At the end of each half year, you&rsquo;ll need to take stock of your progress by unloading your vehicles and feeding your family and animals, so keep an eye on the season and do your best to keep the farm growing and everyone well fed!\n\nTravel and Prosper\nOnce you&rsquo;ve made headway in clearing fields and stocking up goods, it's time to make your products available to potential buyers. The more vehicles you have, the more goods you can ship. Send things into the wide world to increase your Travel Experience and grant you points over the course of the four and a half years of the game. Build up your farm and your vehicles and get your goods out into the world to make the most of every season. There are many roads to success in Fields of Arle, so pick your path, work the land, and enjoy the friendly competition as you strive to make your fortune!\n\n- from the publisher's website", mechanics: ["Automatic Resource Growth", "Highest-Lowest Scoring", "Income", "Set Collection", "Solospiel", "Turn Order: Claim Action", "Turn Order: Progressive", "Arbeitereinsatz"] },
  { title: "At the Gates of Loyang", imageUrl: "https://cf.geekdo-images.com/xnC5RT14H1CgAueR7VTPzw__original/img/oAJwaxaPahA0xfYEWqf3V2xc9x0=/0x0/filters:format(jpeg)/pic3601060.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 120, weight: 3.1, description: "At the Gates of Loyang ist ein Handelsspiel, bei dem Sie Waren produzieren können, indem Sie sie pflanzen und später an Kunden verkaufen. Sie können die Fähigkeiten einiger Helfer nutzen, um Ihr Einkommen oder Ihre Produktion zu steigern.\n\nFelder, Kunden, Helfer und Marktstände werden durch Karten repräsentiert. Jeder Spieler erhält zwei dieser Karten pro Runde, die von einem Biet-/Ziehmechanismus verteilt werden, in dem Sie eine der Karten, die Sie ziehen, und eine der Karten eines öffentlichen Angebots erhalten, das von allen Spielern ausgefüllt wird. Zusätzlich zu diesen Karten erhältst du immer ein Feld pro Runde kostenlos.\n\nDie Platzierung einer Ware auf einem Feld füllt das komplette Feld mit Waren dieser Art. Jede Runde wird eine Einheit pro Feld geerntet. Nach dem Pflanzen, Ernten und Verteilen von Karten kann jeder Spieler so viele Aktionen ausführen, wie er möchte, nur begrenzt durch die Anzahl seiner Karten oder die Anzahl der Waren, die er besitzt. Am Ende seines Zuges kann er das verdiente Geld auf einer Scoring-Strecke investieren, wo frühes Geld mehr wert ist als spätes Geld. Das Spiel endet nach einer bestimmten Anzahl von Runden und der Spieler, der zuerst auf der Scoring-Strecke ist, gewinnt.\n\nOnline-Spiel\n\n     Yucata (rundenbasiert)", mechanics: ["Contracts", "Income", "Loans", "Market", "Open Drafting", "Solospiel", "Turn Order: Progressive"] },
  { title: "Stone Age", imageUrl: "https://cf.geekdo-images.com/elmZegVZ6gp4_5izUgxGQQ__original/img/cR92Dm6yQ3Lgxt1yR81zUb0ooqQ=/0x0/filters:format(jpeg)/pic1632539.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 90, weight: 2.5, description: "The \"Stone Age\" times were hard indeed. In their roles as hunters, collectors, farmers, and tool makers, our ancestors worked with their legs and backs straining against wooden plows in the stony earth. Of course, progress did not stop with the wooden plow. People always searched for better tools and more productive plants to make their work more effective.\n\nIn Stone Age, the players live in this time, just as our ancestors did. They collect wood, break stone and wash their gold from the river. They trade freely, expand their village and so achieve new levels of civilization. With a balance of luck and planning, the players compete for food in this pre-historic time.\n\nPlayers use up to ten tribe members each in three phases. In the first phase, players take turns placing their tribe members in regions of the board that they think will benefit them, including the hunt, the trading center, or the quarry. In the second phase, each player activates each of their staffed areas in whatever sequence they choose, in turn order. In the third phase, players must have enough food available to feed their populations, or they face losing resources or points.", mechanics: ["Action Retrieval", "Contracts", "Würfelglück", "End Game Bonuses", "Increase Value of Unchosen Resources", "Set Collection", "Turn Order: Progressive", "Arbeitereinsatz"] },
  { title: "Alhambra", imageUrl: "https://cf.geekdo-images.com/OiqKsYDh7pqeRYKG__kMSw__original/img/Oe2ZTGE2hUnyZQIEoIjM_zwYfcY=/0x0/filters:format(jpeg)/pic4893652.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 60, weight: 2.1, description: "Granada, 1278. Am Fuße der Sierra Nevada beginnt eines der spannendsten und interessantesten Projekte des spanischen Mittelalters: der Bau der ALHAMBRA.  Die besten Baumeister in ganz Europa und Arabien wollen ihr Können unter Beweis stellen.  Stellen Sie die am besten geeigneten Teams von Bauherren ein und stellen Sie sicher, dass Sie immer genug von der richtigen Währung haben.  Denn egal ob Steinmetze aus dem Norden oder Gartenbauer aus dem Süden, sie alle wollen einen ordentlichen Lohn und bestehen auf ihrer „heimischen“ Währung.  Mit ihrer Hilfe können Türme errichtet, Gärten angelegt, Pavillons und Arkaden errichtet und Seraglios und Kammern gebaut werden.\n\nIn Alhambra erwerben die Spieler Gebäude, die in ihrem Alhambra-Komplex platziert werden sollen.\n\nDas Geld in der Alhambra kommt in vier verschiedenen Währungen und ist auf dem offenen Geldmarkt erhältlich.  Die 54 Gebäude von sechs Typen werden jeweils vier auf einmal auf dem Baumarkt zum Kauf angeboten; ein Gebäude ist in jeder der vier verschiedenen Währungen verfügbar.  Wenn ein Spieler an der Reihe ist, kann ein Spieler 1) Geld vom offenen Geldmarkt nehmen, 2) ein Gebäude vom Baumarkt kaufen und es entweder in seine Alhambra oder sein Reservat legen oder 3) sich an Bau- und Wiederaufbauprojekten mit Gebäuden beteiligen, die in der Alhambra oder dem Reservat des Spielers platziert wurden. Das Spiel belohnt Effizienz, denn wenn ein Spieler ein Gebäude vom Markt für den genauen Geldbetrag kauft, kann der Spieler eine weitere Runde machen.\n\nSpieler mit", mechanics: ["Gebietskontrolle", "Handkartenmanagement", "Open Drafting", "Set Collection", "Plättchen platzieren"] },
  { title: "Ticket to Ride: Nordic Countries", imageUrl: "https://cf.geekdo-images.com/bCdjNIu-O_SzVCfMLZY_KQ__original/img/GhYRV-yJmYEiTaZsZcnEA04YucA=/0x0/filters:format(png)/pic7634498.png", minPlayers: 2, maxPlayers: 3, playTimeMinutes: 60, weight: 2, description: "Ticket to Ride: Nordic Countries takes you on a Nordic adventure through Denmark, Finland, Norway, and Sweden as you travel to the great northern cities of Copenhagen, Oslo, Helsinki, and Stockholm. This version was initially available only in the Nordic Countries of Denmark, Norway, Sweden, and Finland; a worldwide limited-edition release occurred in August 2008 and it has since been kept in print again by Days of Wonder.\n\nThe goal in \"Nordic\" remains the same as base Ticket to Ride: collect and play cards to place your trains on the board, attempting to connect the different cities on your ticket cards. The map incorporates tunnels from Europe and also has routes containing ferries. Ferries will require a certain number of Locomotives to be played, as well as other cards, in order to be claimed. Locomotives are handled a bit differently as well. On your turn you may take 2 Locomotives if you want, but you can only use them on ferries, tunnels, or the special 9 length route.\n\nUnlike the USA or Europe maps, Nordic is designed for 2-3 players only and has a heavier focus on blocking your opponent and more aggressive play.\n\nAlthough not an official expansion for this set, Ticket to Ride Map Collection 5: United Kingdom & Pennsylvania can be used as an expansion for Nordic Countries, although limited to the three players included in this set.  Nordic Countries includes three sets of 40 trains, with 5 spare for each colour; the UK map in Ticket to Ride Map Collection 5: United Kingdom & Pennsylvania requires 35 trains and the Pennsylvania map requires 45 trains.\n\nPart of the Ticket to Ride series.", mechanics: ["Handkartenmanagement", "Streckenbau", "Open Drafting", "Risikomanagement", "Set Collection"] },
  { title: "Ticket to Ride: Germany", imageUrl: "https://cf.geekdo-images.com/GHcyEOsBUOrWrmdXbbAb7w__original/img/_Fze50Bxkz7kk8O9kHiruRKh1IQ=/0x0/filters:format(jpeg)/pic3506961.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 60, weight: 1.8, description: "Ticket to Ride: Germany is a standalone game in the Ticket to Ride series. Over the course of the game, players collect cards in order to then claim routes on the game board between two cities. Ideally the players create a network of routes that connect the cities showing on their secret ticket cards. Players score points both for claiming routes and for completing tickets, with incomplete tickets counting against a player's score.\n\nIn addition to scoring points for tickets, whenever a player places a route on the board, they claim a passenger from the two cities that form the endpoints for that route (assuming that the passengers have not already been claimed). At the end of the game, whoever has the most passengers of each of the six colors scores 20 points for that color; whoever has the secondmost passengers in a color scores 10 points. Whoever has the most points at the end of the game wins.\n\nTicket to Ride: Germany combines most of Zug um Zug: Deutschland and the Deutschland 1902 expansion in one box. Zug um Zug: Deutschland, published solely for the German and Austrian market, consisted of the same map as Ticket to Ride: M&auml;rklin, but ZuZ:D didn't include the passenger mechanism from M&auml;rklin in which players scored additional points by moving passengers from city to city. The Deutschland 1902 expansion introduced a different method of scoring passengers, and that method is now present in this collection.", mechanics: ["Handkartenmanagement", "Streckenbau", "Open Drafting", "Set Collection"] },
  { title: "Carcassonne: Inns & Cathedrals", imageUrl: "https://cf.geekdo-images.com/9W3DkpIZwD-CrQrzfewG1Q__original/img/ukfywreE-NImHPVgXtXbUCyLGXA=/0x0/filters:format(jpeg)/pic9210962.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 60, weight: 1.9, description: "Carcassonne: Die Erweiterung (later prints used the title Inns & Cathedrals) is the first major expansion for Carcassonne and introduces a few new aspects to the game.  There are a couple of completely new kinds of tiles: the inns and cathedrals.  There are also new tiles that present cities, roads, and cloisters in new shapes.  Additionally, each player gets a \"big meeple\" which counts as two regular meeples.  Another whole set of meeples means 6 players can now enjoy the game.  Finally, a set of scoring cards helps make score-keeping a little clearer.\n\nPart of the Carcassonne series.", mechanics: ["Gebietskontrolle", "Plättchen platzieren"] },
  { title: "Robinson Crusoe: Adventures on the Cursed Island", imageUrl: "https://cf.geekdo-images.com/zvHPgrNb9mgkHQk-BwVemA__original/img/OUdMMPwYXTd5JIBG9skImPqa8bg=/0x0/filters:format(jpeg)/pic6026697.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 120, weight: 3.8, description: "Robinson Crusoe: Adventures on the Cursed Island is a game that takes the players to a deserted island, where they'll play the parts of shipwreck survivors confronted by an extraordinary adventure. They'll be faced with the challenges of building a shelter, finding food, fighting wild beasts, and protecting themselves from weather changes. The players decide in which direction the game will unfold and – after several in-game weeks of hard work – how their settlement will look. Will they manage to discover the secret of the island in the meantime? Will they find a pirate treasure, or an abandoned village? Will they discover an underground city or a cursed temple at the bottom of a volcano? Answers to these questions lie in hundreds of event cards and hundreds of object and structure cards that can be used during the game.\n\nIn Robinson Crusoe: Adventures on the Cursed Island you will take the role of one of four characters from the ship crew (cook, carpenter, explorer, or soldier) and work cooperatively to build a shelter, palisade, weapons, tools ,etc and do everything you can to survive. You will have to find food, fight wild beasts, and protect yourself from weather changes among other hazards.\n\nSearch for treasures. Discover mysteries. Follow goals of six different, engaging scenarios. Start by building a big pile of wood and setting it on fire to call for help, and then start new adventures.", mechanics: ["Action Queue", "Area Movement", "Kooperativ", "Würfelglück", "Die Icon Resolution", "Events", "Hexagon Grid", "Map Addition", "Movement Points", "Narrative Choice / Paragraph", "Scenario / Mission / Campaign Game", "Solospiel", "Plättchen platzieren", "Turn Order: Progressive", "Variable Spielerfähigkeiten", "Arbeitereinsatz"] },
  { title: "Mage Knight Board Game", imageUrl: "https://cf.geekdo-images.com/DUO2hz9AlLOH8p9ED-lCWg__original/img/PDDH38Vf9NEB_4ODURxcJKNBfVQ=/0x0/filters:format(jpeg)/pic1083380.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 240, weight: 4.4, description: "In Mage Knight Board Game you become one of four powerful Mage Knights who explore and subdue an important peninsula of the Atlantean Empire. Learn skills, gather an army, pack your deck with powerful spells and abilities as you conquer castles, battle dragons, and clear out dungeons, swelling with power until you're ready to assault the mighty heartland cities of the Atlanteans. Work with other Mage Knights--or bash them aside--as you wrestle your way into power. Play competitively, play cooperatively, play solo--only be sure to win.\n\nSo come, slip through the portal into a standalone game rich in role-playing, deck-building, and map exploration. Immerse yourself in the lush tapestry of the Mage Knight universe as you race toward danger, making the most of each choice, each card, each clash.", mechanics: ["Card Play Conflict Resolution", "Kooperativ", "Deck, Bag, and Pool Building", "Würfelglück", "Bewegung auf Gitterfeld", "Handkartenmanagement", "Hexagon Grid", "Map Addition", "Modularer Spielplan", "Multi-Use Cards", "Open Drafting", "Role Playing", "Scenario / Mission / Campaign Game", "Solospiel", "Tags", "Turn Order: Claim Action", "Variable Spielerfähigkeiten"] },
  { title: "The 7th Continent", imageUrl: "https://cf.geekdo-images.com/OYne8uBCHv5oEgRfpOrV0A__original/img/jcTlhpYG2496xQtuQ277bFTIldY=/0x0/filters:format(jpeg)/pic2648303.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 1000, weight: 2.9, description: "It's the early 20th century. You have decided to sail back to the newly discovered seventh continent to attempt to lift the terrible curse that has struck you since your return from the previous expedition.\n\nIn The 7th Continent, a solo or cooperative \"choose-your-own-adventure\" exploration board game, you choose a character and begin your adventure on your own or with a team of other explorers. Inspired by the Fighting Fantasy book series, you will discover the extent of this wild new land through a variety of terrain and event cards. In a land fraught with danger and wonders, you have to use every ounce of wit and cunning to survive, crafting tools, weapons, and shelter to ensure your survival.\n\nUnlike most board games, it will take you many, MANY hours of exploring and searching the seventh continent until you eventually discover how to remove the curse(s)...or die trying.\n\nThe 7th Continent features an easy saving system so that you can stop playing at any time and resume your adventure later on, just like in a video game!", mechanics: ["Area Movement", "Kooperativ", "Handkartenmanagement", "Map Addition", "Modularer Spielplan", "Narrative Choice / Paragraph", "Scenario / Mission / Campaign Game", "Solospiel", "Geschichten erzählen", "Variable Spielerfähigkeiten"] },
  { title: "Tainted Grail: The Fall of Avalon", imageUrl: "https://cf.geekdo-images.com/aAwBzPzta4joKfFZt05hCw__original/img/e1HfD3XIvObNuGH6rq7kUSK-5aQ=/0x0/filters:format(jpeg)/pic4385726.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 120, weight: 3.4, description: "Tainted Grail: the Fall of Avalon  is an unforgettable, solo or cooperative adventure experience for 1-4 players. Blending Arthurian legends and Celtic mythology with a unique vision, it allows you to impact the game world in deep and meaningful ways. A deep, branching storyline allows you to tackle problems in different ways, ensuring no two games play alike. Difficult decisions or harrowing choices wait behind every corner and seemingly minor tasks may reverberate with major long-term consequences.\n\nIn a land slowly sinking into the Wyrdness and torn apart by conﬂict; surviving each day is a challenge on its own. Starvation, sickness, violent weather, and random incidents all conspire to end your journey. Guardian Menhirs, that ensured safe travel throughout the realm, are slowly going dark turning simple logistics into an involving puzzle. To overcome these challenges, your character develops along several conﬂicting lines, such as Brutality / Empathy or Practicality / Spirituality. These traits unlock a rich choice of mutually exclusive skills and lead to diﬀerent deck-building strategies, making character advancement meaningful and deep.\n\nThe character you develop is going to be tested during dozens of combat and non-combat encounters. Sometimes you will need to brute force your way, but often diplomacy might be a better option. Regardless whether you fight with your strength or your wits, our unique dice-less encounter system makes resolving each conﬂict fun and exciting, while keeping you immersed in the game.\n\nIn Avalon, there&rsquo;s a legend waiting behind every stone and every tree. All locations have their own rich stories and secrets to discover. Places and characters are often much more than they seem. As you slowly put all the pieces of the larger puzzle together, the land will always have a surprise waiting for you just around the corner. Many secrets can be discovered only after several games. Created by one of the best Polish fantasy authors, Krzysztof Piskorski, the story of Tainted Grail: the Fall of Avalon aims to push the boundaries of non-linear narrative, building upon the rich experience.\n\n—description from the publisher", mechanics: ["Area Movement", "Campaign / Battle Card Driven", "Kooperativ", "Deck, Bag, and Pool Building", "Würfelglück", "Handkartenmanagement", "Map Addition", "Modularer Spielplan", "Narrative Choice / Paragraph", "Role Playing", "Scenario / Mission / Campaign Game", "Solospiel", "Geschichten erzählen", "Variable Spielerfähigkeiten"] },

  // Batch 8 (unique entries only — expansions/base-game duplicates of batch 1 dropped)
  { title: "Sword & Sorcery", imageUrl: null, minPlayers: 1, maxPlayers: 5, playTimeMinutes: 90, weight: 3.4, description: "Ein kooperatives Dungeon-Crawler-Spiel mit Miniaturen, in dem Helden gegen Orks und Untote kämpfen und sich über eine Kampagne hinweg weiterentwickeln.", mechanics: ["Kooperativ", "Miniaturen", "Kampagnenspiel", "Würfelglück"] },
  { title: "Too Many Bones", imageUrl: "https://cf.geekdo-images.com/wKwRk0wYBcrtLAfgn4PCdg__original/img/Wpp0vzsVe4HxXGUqiZ1hDvwAHZU=/0x0/filters:format(png)/pic6624445.png", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 120, weight: 3.9, description: "Too Many Bones comes loaded for bear by breaking into a new genre: the dice-builder RPG. This game takes everything you think you know about dice-rolling and turns it on its head. Dripping with strategy, this fantasy-based RPG puts you in the skin of a new race and takes you on an adventure to the northern territories to root out and defeat growing enemy forces and of course the infamous \"baddie\" responsible.\n\nTeam up or go it alone in a 1-4 player Coop or Solo play campaign. With over 100+ unique skill dice and 4-7 classes to choose from, every battle is its own mini challenge to figure out. Your adventure will consist of 8-12 battles before you reach your final destination and face off against one of a number of possible kingpins in order to win. Along the way, you will be faced with storyline decisions that will quickly have you weighing risk/reward, odds, and logic - with dice woven into every aspect! Your party will also be faced with other decisions: when to rest, when to explore, or even which fights to pursue! The Encounter cards offer fun plot twists and some comic relief, all while setting the stage for your next battle.", mechanics: ["Kooperativ", "Würfelglück", "Die Icon Resolution", "Bewegung auf Gitterfeld", "Narrative Choice / Paragraph", "Resource to Move", "Role Playing", "Scenario / Mission / Campaign Game", "Solospiel", "Square Grid", "Stat Check Resolution", "Tech Trees / Tech Tracks", "Turn Order: Role Order", "Variable Spielerfähigkeiten"] },
  { title: "Gloomhaven: Jaws of the Lion", imageUrl: "https://cf.geekdo-images.com/_HhIdavYW-hid20Iq3hhmg__original/img/PBzsLRqNKQKJxGnzpb7o3qLWPQM=/0x0/filters:format(jpeg)/pic5055631.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 120, weight: 3.6, description: "Gloomhaven: Jaws of the Lion is a standalone game that takes place before the events of Gloomhaven. The game includes four new characters — Valrath Red Guard (tank, crowd control), Inox Hatchet (ranged damage), Human Voidwarden (support, mind control), and Quatryl Demolitionist (melee damage, obstacle manipulation) — that can also be used in the original Gloomhaven game.\n\nThe game also includes 16 monster types (including seven new standard monsters and three new bosses) and a new campaign with 25 scenarios that invites the heroes to investigate a case of mysterious disappearances within the city. Is it the work of Vermlings, or is something far more sinister going on?\n\nGloomhaven: Jaws of the Lion is aimed at a more casual audience to get people into the gameplay more quickly. All of the hard-to-organize cardboard map tiles have been removed, and instead players will play on the scenario book itself, which features new artwork unique to each scenario. The last barrier to entry — i.e., learning the game — has also been lowered through a simplified rule set and a five-scenario tutorial that will ease new players into the experience.", mechanics: ["Action Queue", "Action Retrieval", "Campaign / Battle Card Driven", "Communication Limits", "Kooperativ", "Critical Hits and Failures", "Deck Construction", "Bewegung auf Gitterfeld", "Handkartenmanagement", "Hexagon Grid", "Legacy-Spiel", "Line of Sight", "Movement Points", "Multi-Use Cards", "Multiple Maps", "Narrative Choice / Paragraph", "Once-Per-Game Abilities", "Spielerausscheidung", "Role Playing", "Scenario / Mission / Campaign Game", "Gleichzeitige Aktionswahl", "Solospiel", "Variable Spielerfähigkeiten"] },
  { title: "Frosthaven", imageUrl: "https://cf.geekdo-images.com/cwUgf-f-qwri8UHBUnifuQ__original/img/Tk7wFDJuaU8RPjNkmyC3AWYOPpU=/0x0/filters:format(png)/pic5092291.png", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 180, weight: 4.4, description: "Frosthaven is the story of a small outpost far to the north of the capital city of White Oak.  It's an outpost barely surviving the harsh weather let alone invasions from forces both known and unknown. However, a group of mercenaries, at the end of their rope, will help bring this settlement back from the edge of destruction. Not only will they have to deal with the harsh elements, but with other, far more dangerous threats out in the unforgiving cold, as well. There are: Algox, the bigger, more yeti-like cousins of the Inox, attacking from the mountains; Lurkers flooding in from the northern sea; and rumors have it that there are machines that wander the frozen wastes of their own free will. The party of mercenaries must face all of these perils, and perhaps in doing so, make peace with these new races so they can work together against even more sinister forces.\n\nFrosthaven is a standalone adventure from the designer and publisher of Gloomhaven that features sixteen new characters, three new races, more than twenty new enemies, more than one hundred new items, and a new, 100-scenario campaign.  Characters and items from Gloomhaven will be usable in Frosthaven, and vice versa.\n\nIn addition to using the well-known combat mechanisms of Gloomhaven, Frosthaven features other elements, such as mysteries to solve, a seasonal event system to live through, and player control over how the ramshackle village expands, with each new building offering new ways to progress.\n\nFrosthaven has a whole new set of items but there is a mechanism for bringing items over from 'Gloomhaven'. However, as Frosthaven's outpost is a remote location, these products may be imported but are not present as standard items. Resources are much more valuable and you have to build items through a crafting system rather than just buying them.\n\n—description from the publisher", mechanics: ["Campaign / Battle Card Driven", "Communication Limits", "Kooperativ", "Deck Construction", "Deck, Bag, and Pool Building", "Bewegung auf Gitterfeld", "Handkartenmanagement", "Hexagon Grid", "Legacy-Spiel", "Modularer Spielplan", "Multi-Use Cards", "Narrative Choice / Paragraph", "Once-Per-Game Abilities", "Scenario / Mission / Campaign Game", "Gleichzeitige Aktionswahl", "Solospiel", "Variable Spielerfähigkeiten"] },
  { title: "Wingspan: Asia", imageUrl: null, minPlayers: 1, maxPlayers: 5, playTimeMinutes: 60, weight: 2.4, description: "Eine Erweiterung zu Wingspan mit asiatischen Vogelarten, die neue Kraftkarten und ein modulares Ass der Asse-Tableau einführt.", mechanics: ["Kartenmanagement", "Engine Building", "Würfelglück", "Set Collection"] },
  { title: "Terraforming Mars: Ares Expedition", imageUrl: "https://cf.geekdo-images.com/eT_Atcy_vRJvuUMgYakNrQ__original/img/upZwrb6k8zZMNTwB8VfpI372yuo=/0x0/filters:format(jpeg)/pic6260098.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 60, weight: 2.9, description: "Terraforming Mars: Ares Expedition is an engine-building game in which players control interplanetary corporations with the goal of making Mars habitable (and profitable). You will do this by investing mega credits (MC) into project cards that will directly or indirectly contribute to the terraforming process. In order to win, you will want to accumulate a high terraform rating (TR) and as many victory points (VP) as you can. Players raise their TR by increasing global parameters: oceans, oxygen, and temperature. TR also determines each corporation's basic income, and, at the end of the game TR counts as VP. Additional VP and production capabilities are awarded for building project cards and other actions taken during the game.\n\nThe game is played in rounds, and each round the players will choose one of five phases, which determines which activities will take place during that round. This means every round is different, but can consist of building new project cards, taking general and project-specific actions, producing income and resources (plants and heat), or researching to draw more project cards. Every player will take all the phases selected for the round, and will receive a special bonus during the phase that they selected. To speed up the game, within each phase, players can act simultaneously without waiting for each other!\n\nThe game board has tracks for oxygen, temperature, and terraform rating, as well as a place for all of the ocean tiles that will be flipped over the course of the game. The game ends when there is enough oxygen to breath (14%), oceans enough to allow Earth-like weather (9), and the temperature is well above freezing (+8&deg;C). It will then be possible, if not comfortable, to live on the surface of Mars!\n\nThe winner is the player with the most VP at the end of the game.", mechanics: ["End Game Bonuses", "Follow", "Handkartenmanagement", "Income", "Market", "Multi-Use Cards", "Set Collection", "Gleichzeitige Aktionswahl", "Solospiel", "Tags", "Tech Trees / Tech Tracks", "Track Movement", "Variable Phase Order", "Variable Spielerfähigkeiten", "Variable Set-up"] },
  { title: "Point Salad", imageUrl: "https://cf.geekdo-images.com/Xy0W9NtEpX0EVjwgxO3IEA__original/img/WdLBZcryNqysYsyC3PNF9FeaPWQ=/0x0/filters:format(png)/pic4621571.png", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 30, weight: 1.2, description: "Point Salad is a fast and fun card drafting game for the whole family. There are over 100 ways to score points. Players may use a variety of strategies and every game of Point Salad is unique!\n\nCards come in six different types of veggies, and the back of each card has a different scoring method. So for instance, one scoring method may award 2 points for every carrot you have, but deduct a point for every onion.  By drafting combinations of veggies and point cards that work for your strategy, you can amass the most points and win.\n\n—description from the publisher", mechanics: ["Contracts", "End Game Bonuses", "Open Drafting", "Set Collection"] },
  { title: "Ticket to Ride: Rails & Sails", imageUrl: "https://cf.geekdo-images.com/KaTRZHY0XpW-ZSgjaRNzmg__original/img/3XLzbo_56PB-0PVjHlCn4YLq1d8=/0x0/filters:format(jpeg)/pic3066862.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 120, weight: 2.5, description: "Ticket to Ride: Rails & Sails takes the familiar gameplay of Ticket to Ride and expands it across the globe — which means that you'll be moving across water, of course, and that's where the sails come in.\n\nAs in other Ticket to Ride games, in Ticket to Ride: Rails & Sails players start with tickets in hand that show two cities, and over the course of the game they try to collect colored cards, then claim routes on the game board with their colored train and ship tokens, scoring points while doing so. When any player has six or fewer tokens in their supply, each player takes two more turns, then the game ends. At that point, if they've created a continuous path between the two cities on a ticket, then they score the points on that ticket; if not, then they lose points instead.\n\nTicket to Ride: Rails & Sails puts a few twists on the TtR formula, starting with split card decks of trains and ships (with all of the wild cards going in the train deck). Three cards of each type are revealed at the start of the game, and when you draw cards, you replace them with a card from whichever deck you like. (Shuffle the card types separately to form new decks when needed.)\n\nSimilarly, players choose their own mix of train and ship tokens at the start of the game. To claim a train route (rectangular spaces), you must play train cards (or wilds) and cover those spaces with train tokens, and to claim a ship route (oval spaces), you must play ship cards (or wilds) and cover those spaces with ship tokens. Ship cards depict one or two ships on them, and when you play a double-ship card, you can cover one or two ship spaces. You can take an action during play to swap train tokens for ships (or vice versa), and you lose one point for each token you swap.\n\nSome tickets show tour routes with multiple cities instead of simply two cities. If you build a network that matches the tour exactly, you score more points than if you simply include all of those cities in your network.\n\nEach player also starts the game with three harbors. If you have built a route to a port city, you can take an action during the game to place a harbor in that city (with a limit of one harbor per port). To place the harbor, you must discard two train cards and two ship cards of the same color, all of which must bear the harbor symbol (an anchor). At the end of the game, you lose four points for each harbor not placed, and you gain 10-40 points for each placed harbor depending on how many of your completed tickets show that port city.\n\nTicket to Ride: Rails & Sails includes a double-sided game board, with one side showing the world and the other side showing the Great Lakes of North America. Players start with a differing number of cards and tokens depending on which side they play, and each side has a few differences in gameplay.\n\nPart of Ticket to Ride series.", mechanics: ["Connections", "Handkartenmanagement", "Streckenbau", "Open Drafting", "Set Collection"] },
  { title: "Long Shot: The Dice Game", imageUrl: "https://cf.geekdo-images.com/j9RO81ihYw0_oPj6iqV_bA__original/img/-jPNsFg5d9uA7D4WGDIP3TNLHX4=/0x0/filters:format(jpeg)/pic6682376.jpg", minPlayers: 1, maxPlayers: 8, playTimeMinutes: 25, weight: 1.9, description: "This is your ticket to the track!\n\nIn Long Shot: The Dice Game, you and up to seven other players will strategize and push your luck as the action unfolds in a tense race of eight horses. During the game you buy horses, place bets, influence race movement, and utilize special abilities. The roll of the dice determines which horses move and the options available each turn, so be ready to adapt your plans. Once three horses cross the finish line, earnings are totaled. While there are many ways to earn money during a horse race, only the player that makes the most money will be declared the winner. Will you play it safe, or risk it big on a long shot?\n\n—description from the publisher", mechanics: ["Betting and Bluffing", "Bids As Wagers", "Bingo", "Würfelglück", "End Game Bonuses", "Paper-and-Pencil", "Solospiel", "Victory Points as a Resource"] },
  { title: "Circle the Wagons", imageUrl: "https://cf.geekdo-images.com/J1WyesAIz4YPDH5sfPWguQ__original/img/OTXkidr0CYa_ndpu79Ur01-lxtU=/0x0/filters:format(png)/pic3380851.png", minPlayers: 2, maxPlayers: 2, playTimeMinutes: 15, weight: 1.6, description: "Each player in Circle the Wagons is fixin' to build up their own boomtown, but only one'll build the best in the West!\n\nBlaze a trail by draftin' cards 'round the circle and placin' 'em in yer town, tryin' to connect matchin' territories to score prosperity points! But don't forget about them three bonus cards in the center of the circle that can score ya even more points — that is, if ya play yer cards right. With over 800 unique ways to score and millions of draftin' and placin' combos, you'll never build the same town twice!\n\n\nCircle the Wagons is a 2-player map-building game designed by Steven Aramini (Yardmaster), Danny Devine (Ghosts Love Candy) and Paul Kluka; featuring the art of Beth Sobel (Herbaceous, World's Fair 1893 and Lanterns) and logo design of Bryan Fischer (Chicken Caesar). Circle the Wagons is the winner of the 2016 Button Shy Wallet Design Contest, beating out over 70 other games.", mechanics: ["Contracts", "Layering", "Open Drafting", "Set Collection", "Plättchen platzieren"] },
  { title: "Sea Salt & Paper", imageUrl: "https://cf.geekdo-images.com/CIh_rXKoRw9z8K0PJxT8nQ__original/img/AX2wyHhWFgVh5OArXAjVHY-nFZg=/0x0/filters:format(jpeg)/pic6973911.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 45, weight: 1.5, description: "During your turn, you assemble your hand, maybe place cards for their effect, and decide if you want to end the round. But do you think you are the one with the most points in hand?\nYou will have to choose: stop the round immediately or give the others an extra turn to try to extend the gap? Is it worth taking the risk? \nThe game ends when you reach 30/35/40 points (4/3/2 players).\n\nThe excitement of ending the round to catch your opponents off guard\n\nThe pleasure of playing your effect cards and making combos\n\nIt's a set collection card game like Rummy. The origami created especially for the game is just the illustrations on the cards.", mechanics: ["Handkartenmanagement", "Melding and Splaying", "Open Drafting", "Risikomanagement", "Score-and-Reset Game", "Set Collection", "Sudden Death Ending", "Take That"] },
  { title: "Sky Team", imageUrl: "https://cf.geekdo-images.com/uXMeQzNenHb3zK7Hoa6b2w__original/img/mWOQnkpyYBorh_Y1-0Y2o-ew17k=/0x0/filters:format(jpeg)/pic7398904.jpg", minPlayers: 2, maxPlayers: 2, playTimeMinutes: 20, weight: 2, description: "Sky Team is a co-operative game, exclusively for two players, in which you play a pilot and co-pilot at the controls of an airliner. Your goal is to work together as a team to land your airplane in different airports around the world.\n\nTo land your plane, you need to silently assign your dice to the correct spaces in your cockpit to balance the axis of your plane, control its speed, deploy the flaps, extend the landing gear, contact the control tower to clear your path, and even have a little coffee to improve your concentration enough to change the value of your dice.\n\nIf the aircraft tilts too much and stalls, overshoots the airport, or collides with another aircraft, you lose the game...and your pilot's license...and probably your life.\n\nFrom Montreal to Tokyo, each airport offers its own set of challenges. Watch out for the turbulence as this could end up being a bumpy ride!\n\n—description from the publisher", mechanics: ["Communication Limits", "Kooperativ", "Würfelglück", "Scenario / Mission / Campaign Game", "Turn Order: Progressive", "Variable Spielerfähigkeiten", "Variable Set-up", "Worker Placement with Dice Workers"] },
  { title: "Ark Nova", imageUrl: "https://cf.geekdo-images.com/SoU8p28Sk1s8MSvoM4N8pQ__original/img/g4S18szTdrXCdIwVKzMKrZrYAcM=/0x0/filters:format(jpeg)/pic6293412.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 150, weight: 3.8, description: "In Ark Nova planen und gestalten Sie einen modernen, wissenschaftlich geführten Zoo. Mit dem ultimativen Ziel, die erfolgreichste zoologische Einrichtung zu besitzen, werden Sie Gehege bauen, Tiere aufnehmen und Naturschutzprojekte auf der ganzen Welt unterstützen. Spezialisten und einzigartige Gebäude helfen Ihnen dabei, dieses Ziel zu erreichen.\n\nJeder Spieler hat einen Satz von fünf Aktionskarten, um sein Gameplay zu verwalten, und die Kraft einer Aktion wird durch den Slot bestimmt, den die Karte derzeit einnimmt. Es handelt sich um:\n\n\n    KARTEN: Ermöglicht es dir, neue Zoo-Karten (Tiere, Sponsoren und Naturschutz-Projektkarten) zu erhalten.\n    BAUEN: Ermöglicht den Bau von Standard- oder Spezialgehäusen, Kiosken und Pavillons.\n    TIERE: Ermöglicht es Ihnen, Tiere in Ihrem Zoo unterzubringen.\n    ASSOZIATION: Ermöglicht Ihren Assoziationsmitarbeitern, verschiedene Aufgaben auszuführen.\n    SPONSOREN: Ermöglicht es Ihnen, eine Sponsorenkarte in Ihrem Zoo zu spielen oder Geld zu sammeln.\n\n\n255 Karten mit Tieren, Spezialisten, speziellen Gehegen und Naturschutzprojekten mit jeweils einer besonderen Fähigkeit stehen im Mittelpunkt von Ark Nova. Nutze sie, um die Attraktivität und den wissenschaftlichen Ruf deines Zoos zu steigern und Erhaltungspunkte zu sammeln.\n\n-Beschreibung des Verlages", mechanics: ["Contracts", "End Game Bonuses", "Events", "Grid Coverage", "Handkartenmanagement", "Hexagon Grid", "Income", "Increase Value of Unchosen Resources", "Open Drafting", "Race", "Set Collection", "Solospiel", "Tags", "Plättchen platzieren", "Track Movement", "Variable Spielerfähigkeiten", "Variable Set-up"] },
  { title: "Res Arcana", imageUrl: "https://cf.geekdo-images.com/gcALy45JfcjyKUn6T3mBIQ__original/img/YLSAurBSWEGi3PHsuQWi8St_0Yg=/0x0/filters:format(jpeg)/pic4422847.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 60, weight: 2.7, description: "Prepare Your Place of Power!\n\nIn a high tower, an Alchemist prepares potions, using vials filled with otherworldly fluids. In a sacred grove, a Druid grinds herbs for a mystical ritual. In the catacombs, a Necromancer summons a bone dragon... Welcome to the world of Res Arcana!\n\nIn it, Life, Death, Elan, Calm, and Gold are the essences that fuel the art of magic. Choose your mage, gather essences, craft unique artifacts, and use them to summon dragons, conquer places of power, and achieve victory!\n\nA game typically lasts 4-6 rounds. In each round, players do these steps:\n\n\n    Collect essences: performs  any Collect abilities, and may take essences from components.\n    Do actions, 1 per turn, clockwise from the First Player: place an artifact, claim a monument or Place of Power, discard a card for 1 Gold or any 2 other essences, use a power on a straightened component, or pass: exchange magic items and draw 1 card. Play continues until all players have passed.\n    Pass procedure: If you are first to pass, take the First Player token, swap your magic item for a different magic item, draw 1 card.\n    Check victory points (10+ VPs). If no one has won: straighten all turned components, and begin the next round.", mechanics: ["Handkartenmanagement", "Income", "Multi-Use Cards", "Open Drafting", "Race", "Score-and-Reset Game", "Take That", "Turn Order: Pass Order", "Variable Spielerfähigkeiten"] },
  { title: "Lost Ruins of Arnak", imageUrl: "https://cf.geekdo-images.com/6GqH14TJJhza86BX5HCLEQ__original/img/CXqwimJPonWy1oyXEMgPN_ZVmUI=/0x0/filters:format(jpeg)/pic5674958.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 120, weight: 2.9, description: "On an uninhabited island in uncharted seas, explorers have found traces of a great civilization. Now you will lead an expedition to explore the island, find lost artifacts, and face fearsome guardians, all in a quest to learn the island's secrets.\n\nLost Ruins of Arnak combines deck-building and worker placement in a game of exploration, resource management, and discovery. In addition to traditional deck-builder effects, cards can also be used to place workers, and new worker actions become available as players explore the island. Some of these actions require resources instead of workers, so building a solid resource base will be essential. You are limited to only one action per turn, so make your choice carefully... what action will benefit you most now? And what can you afford to do later... assuming someone else doesn't take the action first!?\n\nDecks are small, and randomness in the game is heavily mitigated by the wealth of tactical decisions offered on the game board. With a variety of worker actions, artifacts, and equipment cards, the set-up for each game will be unique, encouraging players to explore new strategies to meet the challenge.\n\nDiscover the Lost Ruins of Arnak!\n\n—description from the publisher", mechanics: ["Area Movement", "Contracts", "Deck, Bag, and Pool Building", "Delayed Purchase", "End Game Bonuses", "Handkartenmanagement", "Multi-Use Cards", "Once-Per-Game Abilities", "Open Drafting", "Resource to Move", "Solospiel", "Track Movement", "Turn Order: Progressive", "Arbeitereinsatz"] },

  // Batch 9 (unique entries only — Root: The Underworld Expansion duplicate of batch 5 dropped)
  { title: "Wingspan: European Expansion", imageUrl: "https://cf.geekdo-images.com/7izK8WM_bgtvBzxQvLGz-A__original/img/NFkKrFCKJ1YUC1x7bpx-WVDhLq0=/0x0/filters:format(jpeg)/pic4982682.jpg", minPlayers: 1, maxPlayers: 5, playTimeMinutes: 70, weight: 2.4, description: "In this first expansion to Wingspan, we increase the scope of the world to include the regal, beautiful, and varied birds of Europe. These birds feature a variety of new abilities, including a number of birds with round end abilities, abilities that increase interaction between players, and birds that benefit from excess cards/food. Along with the new bonus cards, they&rsquo;re designed to be shuffled into the original decks of cards (and cards from future expansions).\n\nThe European Expansion also includes an additional tray for storing the growing collection of birds (past, present, and future), as well as 15 purple eggs, extra food tokens, and a colorful new scorepad designed for both multi-player and single-player scoring. It's designed by Elizabeth Hargrave and features birds illustrated by Natalia Rojas and Ana Maria Martinez.\n\n—description from the publisher", mechanics: ["Würfelglück", "End Game Bonuses", "Handkartenmanagement", "Open Drafting", "Set Collection"] },
  { title: "Everdell: Pearlbrook", imageUrl: "https://cf.geekdo-images.com/vg4eDYz27RMPdvU5tjRCzQ__original/img/jo894zE2dhfeAW_Le8mPUNBGXOw=/0x0/filters:format(jpeg)/pic4299282.jpg", minPlayers: 1, maxPlayers: 4, playTimeMinutes: 80, weight: 2.9, description: "Explore a new underwater society in Pearlbrook, the first expansion for Everdell!\n\nPearlbrook introduces a new side board, the river board, where you'll send your frog ambassador to gather a new resource: pearls. You'll also encounter new aquatic critters and constructions! Collect enough pearls and you can construct fabulous wonders and adornments, to make your city the pride of Everdell!\n\n—description from publisher", mechanics: ["Handkartenmanagement", "Open Drafting", "Set Collection", "Arbeitereinsatz"] },
  { title: "Catan: Traders and Barbarians", imageUrl: "https://upload.wikimedia.org/wikipedia/en/a/a3/Catan-2015-boxart.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 120, weight: 2.6, description: "Die dritte große Erweiterung zu Catan bündelt mehrere Szenarien und Regelvarianten, unter anderem Handelsrouten, Barbaren-Angriffe und ein Würfelspiel-Modul.", mechanics: ["Handel", "Würfelglück", "Gebietsausbau"] },
  { title: "Carcassonne: The River", imageUrl: "https://cf.geekdo-images.com/qCiVmugRuY47bf9YFXlQ8A__original/img/xgYF8t4-_U8DJPv_DxPoM_Nstzg=/0x0/filters:format(jpeg)/pic193765.jpg", minPlayers: 2, maxPlayers: 5, playTimeMinutes: 45, weight: 1.7, description: "Der Fluss (The River) is a mini-expansion for Carcassonne. It adds twelve river tiles. All the familiar landscape elements are also present.\n\nThe river tiles are placed first, after that the game continues as normal. No followers may be placed on the river so the scoring is the same as in the basic game.\n\nPart of the Carcassonne series.", mechanics: ["Gebietskontrolle", "Enclosure", "End Game Bonuses", "Kill Steal", "Map Addition", "Modularer Spielplan", "Musterbildung", "Square Grid", "Plättchen platzieren", "Variable Set-up"] },
  { title: "Dixit: Journey", imageUrl: "https://cf.geekdo-images.com/HX0lvc-JiPzf7Nrqp_N-Fw__original/img/9qsDO-TCNWxVxNZEbgLX08aYeJc=/0x0/filters:format(jpeg)/pic1387599.jpg", minPlayers: 3, maxPlayers: 6, playTimeMinutes: 30, weight: 1.3, description: "Dixit: Journey features the same basic game play as Dixit: Each round one player takes on the role of Storyteller, choosing one card from their hand, then telling a story, singing a ditty or otherwise doing something that in their opinion is associated with the played card. Each other player then chooses one card in their own hand and gives it to the Storyteller in secret. These cards are shuffled and revealed, then players vote on which card was played by the Storyteller.\n\nIf no one or everyone votes for the Storyteller, then they receive no points; if they received some votes but not all the votes, they score based on the number of votes received. Each player who submitted a correct vote or who received a vote on their card submission also scores. After a certain number of rounds, the player with the most points wins.\n\nDixit: Journey differs from Dixit in a number of ways, starting with a simplified scoring board that doesn't have players moving around a track in the bottom of the game box. Instead the scoring track is on its own board, and this game board includes a summary of the rules as well as numbered places to put the cards each round to facilitate voting. The game rules  have been revised to make the game easier to learn, while keeping game play the same.\n\nSimilar to:\n\n    Dixit 3: Journey – In Europe, the cards from Dixit: Journey will be packaged as an expansion and not sold as a complete game.", mechanics: ["Acting", "Gleichzeitige Aktionswahl", "Geschichten erzählen", "Targeted Clues", "Abstimmung"] },
  { title: "Ticket to Ride: Switzerland", imageUrl: "https://cf.geekdo-images.com/NGuzKhH_fRZkUlT11Sef7Q__original/img/xcJxl3clJmjVDKhXy1qZNT-OpQs=/0x0/filters:format(jpeg)/pic620078.jpg", minPlayers: 2, maxPlayers: 3, playTimeMinutes: 60, weight: 1.9, description: "Officially an expansion that works with either Ticket to Ride or Ticket to Ride: Europe, Ticket to Ride: Switzerland requires the train pieces and train cards from the above mentioned original games to work. It comes with a new board, 46 new destination cards and a set of rules (in several languages) to create a new game. The Ticket to Ride: Switzerland map and rules first appeared as an exclusive map for the Ticket to Ride computer game. In addition to being specifically designed for a smaller numbers of players the map has several new features. Locomotive cards are used exclusively for tunnels (which work as they do in Ticket to Ride: Europe). Some destination cards have an end point inside Switzerland and other possible ends in adjacent countries (the value of the completed card is based on the farthest possible connection completed). There are also destination cards for connections between adjacent countries.\n\nAlthough not officially sanctioned, it works fine with Ticket to Ride: Nordic Countries also. Due to Ticket to Ride: Märklin's different distribution of train cards, Ticket to Ride: Switzerland is not considered to be compatible.\n\nPart of Ticket to Ride series.\n\nRe-implemented / Re-printed in:\n\n    Ticket to Ride Map Collection 2: India & Switzerland", mechanics: ["Handkartenmanagement", "Streckenbau", "Open Drafting", "Set Collection"] },
  { title: "King of Tokyo: Power Up!", imageUrl: "https://cf.geekdo-images.com/ukYD9rs-jvEK-s9BhgqBEA__original/img/pHc_rWQXyznkOlx9UYs8g1cbu6E=/0x0/filters:format(jpeg)/pic3330452.jpg", minPlayers: 2, maxPlayers: 6, playTimeMinutes: 30, weight: 1.7, description: "With King of Tokyo: Power Up! – an expansion for the King of Tokyo base game – Included is the new monster Pandakai, a giant panda bear. After choosing a monster, each player takes the eight Evolution cards associated with that monster, shuffles those cards, and creates a personal deck. At the end of a player's turn, if she has three hearts, she draws one Evolution card and adds it to her hand; this is possible even in Tokyo (when hearts are normally useless) and even if the hearts are used for some other action, such as healing.\n\nA player can reveal and play an Evolution card at any time. Some Evolutions are temporary, allowing a one-time bonus, while others are Permanent, such as Gigazaur's \"Tail Sweep\", which allows him to change one die to a 1 or 2 each turn. Each Evolution card also identifies whether a monster is a Mutant, Invader, or Robot, and while not relevant for Power Up!, this species identification could come into play in future expansions.\n\nThe rules for King of Tokyo: Power Up! contain a few variants: Players start with a random Evolution in play, or draw two cards and choose the one they want, or draft a set of Evolutions prior to the start of play. However you play, the goal of the game remains the same: Score 20 points or be the last monster standing amid the rubble of what was once Tokyo.\n\nPart of the King of Tokyo series.", mechanics: ["Würfelglück", "Variable Spielerfähigkeiten"] },
  { title: "Pandemic: Fall of Rome", imageUrl: "https://cf.geekdo-images.com/eGXgHOp40KYVqUGoSJ09bw__original/img/V17DBpCDqoRpLPwa3jZNGNqwvm8=/0x0/filters:format(jpeg)/pic8031112.jpg", minPlayers: 1, maxPlayers: 5, playTimeMinutes: 60, weight: 2.5, description: "At the height of its power, the Roman Empire held more than two million square miles of territory containing over a hundred million people. Throughout the centuries of its existence, the Empire brought major advancements in engineering, architecture, science, art, and literature. By the beginning of the 5th Century, decades of political corruption, economic crisis, and an overburdened military had exacted a severe toll on the stability of the Empire. This paved the way for severe incursions from aggressive barbarian tribes, leading to a decline from which Rome would not recover. Now citizens, soldiers, and allies of Rome must unite to protect the Empire.\n\nCombining the cooperative gameplay of Pandemic with innovative new mechanisms, Pandemic: Fall of Rome takes players back in history to the time of the world's greatest empire: Rome. A weakened military has left the borders open to invasion from countless tribes such as the Anglo-Saxons, Goths, Vandals, and Huns. As you march through the Roman Empire, you must recruit armies, fortify cities, forge alliances, and face off against the invading hordes in battle.\n\nSimply defending Rome is not enough; players must find a way to stop the incursions and find peace with their neighboring peoples. Players collect sets of matching-colored cards to forge an alliance with the different tribes. In doing so, they gain the ability to use cards matching the tribe to convert other members of that tribe into Roman soldiers, furthering their ability to hold the line against other invaders.\n\nTake on unique roles with special abilities to improve your team's chances to protect against the invaders. Work together, use your skills wisely, and stop the fall of Rome!\n\nPandemic: Fall of Rome includes a solitaire mode in which the player takes on the burden of being the Emperor and commands three different roles to try to protect the city from the invading hordes. Players who want a more difficult game can try the \"Roma Caput Mundi\" challenge by adding more Revolt cards to the deck; they must also respect the law in Rome that Roman legions are not allowed in the city.\n\n—description from the publisher", mechanics: ["Aktionspunkte", "Kooperativ", "Würfelglück", "Events", "Handkartenmanagement", "Bewegung entlang von Punkten", "Set Collection", "Solospiel", "Variable Spielerfähigkeiten"] },
  { title: "Azul: Queen's Garden", imageUrl: "https://cf.geekdo-images.com/l-NBWJ1gIcfOCfrvAw8qvw__original/img/VaPUWBlEE3Wg_QGYAsHxKV8mBkw=/0x0/filters:format(jpeg)/pic6389125.jpg", minPlayers: 2, maxPlayers: 4, playTimeMinutes: 60, weight: 2.9, description: "Willkommen zurück im Palast von Sintra! König Manuel I. hat die besten Gartengestalter Portugals beauftragt, den außergewöhnlichsten Garten für seine Frau, Königin Maria von Aragon, zu bauen.\n\nIn Azul: Queen's Garden haben die Spieler die Aufgabe, einen prächtigen Garten für die schöne Frau des Königs zu arrangieren, indem sie wunderschöne Pflanzen, Bäume und Zierelemente arrangieren.\n\nMit einem innovativen Entwurfsmechanismus, der Signatur der Azul-Serie, müssen die Spieler sorgfältig bunte Kacheln auswählen, um ihren Garten zu dekorieren. Nur die unglaublichsten Gartengestalter werden gedeihen und den Segen der Königin gewinnen.\n\n-Beschreibung des Verlages", mechanics: ["End Game Bonuses", "Musterbildung", "Set Collection", "Plättchen platzieren", "Turn Order: Claim Action"] },
];
